/* ════════════════════════════════════════════════════════════════════════
   PISTAS Y EXPLICACIONES COMPLETAS (sesión de 3 intentos con pistas)
   Cada pregunta tiene:
     p:   [pista 1 (general), pista 2 (más concreta)] — se muestran tras el
          1.er y el 2.º error, sin decir la respuesta.
     exp: explicación completa, que se muestra al final.
   BIO_AJ agrega pistas y explicación a las preguntas de arriba (se buscan
   por el comienzo del enunciado); BIO_NUEVAS agrega preguntas nuevas.
   Meta: al menos 40 preguntas por tema.
   ════════════════════════════════════════════════════════════════════════ */
(function(){
var B=window.BANCO_BIO;
window.BIO_AJ=function(t,lista){lista.forEach(function(x){
  var q=B.filter(function(y){return y.t===t&&y.q.indexOf(x[0])===0;})[0];
  if(!q){if(window.console)console.warn('BIO_AJ: no se encontró «'+x[0]+'» en '+t);return;}
  if(x[1]||x[2])q.p=[x[1],x[2]].filter(Boolean);
  if(x[3])q.exp=x[3];
});};
window.BIO_NUEVAS=function(lista){lista.forEach(function(q){B.push(q);});};
})();
/* ───────── LA CÉLULA ───────── */
BIO_AJ('celula',[
['¿Quién usó por primera vez la palabra «célula»','Fue un científico inglés del siglo XVII que construyó su propio microscopio.','Publicó sus dibujos en el libro «Micrographia» (1665).','Robert Hooke observó en 1665 una lámina de corcho y vio unas celdillas vacías que le recordaron las celdas de un monasterio; por eso las llamó «células». En realidad vio las paredes de células muertas.'],
['¿Quién observó por primera vez microorganismos vivos','Era un comerciante de telas holandés, no un científico de universidad.','Pulía él mismo lentes diminutos y muy potentes.','Anton van Leeuwenhoek, con microscopios de una sola lente que él mismo pulía, fue el primero en ver seres vivos microscópicos (bacterias y protozoos) en el agua y en el sarro de los dientes. Los llamó «animálculos».'],
['La frase «toda célula proviene de otra célula»','Es el tercer postulado de la teoría celular, el más reciente.','La dijo un médico alemán en 1855, en latín: «Omnis cellula e cellula».','Rudolf Virchow completó la teoría celular en 1855 al afirmar que toda célula viene de otra célula que se divide. Así se descartó la idea de que las células aparecen de la nada (generación espontánea).'],
['Los virus son células muy pequeñas','','','Falso. Los virus no son células: son material genético (ADN o ARN) dentro de una cubierta de proteínas. No tienen citoplasma ni ribosomas, no se nutren por sí mismos y solo se multiplican dentro de una célula a la que infectan.'],
['¿Qué diferencia principal hay entre una célula procariota','Piensa en el significado de las palabras: «pro» = antes, «eu» = verdadero, «carion» = núcleo.','La diferencia está en dónde se guarda el ADN.','La célula procariota no tiene núcleo: su ADN está suelto en una zona del citoplasma llamada nucleoide. La eucariota guarda el ADN dentro de un núcleo rodeado por membrana. Las dos tienen ADN, membrana y ribosomas.'],
['¿Qué organelo realiza la respiración celular','Es la «central eléctrica» de la célula.','Usa oxígeno y glucosa, y tiene su propio ADN.','La mitocondria hace la respiración celular: usa el oxígeno para degradar la glucosa y guarda la energía liberada en moléculas de ATP. Las células que gastan mucha energía, como las del músculo, tienen muchas mitocondrias.'],
['¿Qué organelo empaca y distribuye las proteínas','Recibe las proteínas que vienen del retículo endoplasmático.','Está formado por sacos aplanados apilados y suelta vesículas.','El aparato de Golgi recibe las proteínas del retículo endoplasmático, las modifica, las empaca en vesículas y las envía a su destino, dentro o fuera de la célula: por eso se le compara con una oficina de correos.'],
['¿Cómo se llama el organelo de las células vegetales donde ocurre la fotosíntesis','Es de color verde.','Contiene el pigmento clorofila.','El cloroplasto es el organelo donde ocurre la fotosíntesis: su clorofila capta la luz y con esa energía se fabrica glucosa a partir de CO₂ y agua, liberando oxígeno.'],
['Las células vegetales tienen mitocondrias además','','','Verdadero. Las plantas también necesitan obtener energía de la glucosa: los cloroplastos la fabrican y las mitocondrias la «queman» en la respiración celular, de día y de noche.'],
['¿Cuál de estas estructuras tiene la célula vegetal pero NO la animal','Piensa en qué le da a la planta su forma rígida.','Es una cubierta que está por fuera de la membrana y está hecha de celulosa.','La pared celular de celulosa solo la tienen las células vegetales (los hongos tienen pared, pero de quitina). Está por fuera de la membrana y le da a la célula una forma fija y resistencia. Membrana, núcleo y mitocondrias los tienen ambas.'],
['¿Qué estructura tienen TODAS las células','Debe estar también en las bacterias, que no tienen organelos con membrana.','Sirve para fabricar proteínas.','Todas las células, procariotas y eucariotas, tienen ribosomas, porque todas necesitan fabricar proteínas. Además todas tienen membrana, citoplasma y ADN. Núcleo, mitocondrias y cloroplastos solo los tienen algunas.'],
['Si pones glóbulos rojos en agua destilada','Compara la cantidad de sales dentro de la célula y en el agua destilada.','El agua se mueve por ósmosis hacia donde hay más solutos.','El agua destilada no tiene sales (medio hipotónico), mientras que el glóbulo rojo sí. Por ósmosis, el agua entra a la célula, que se hincha y puede reventar (hemólisis). Por eso los sueros médicos tienen la misma concentración de sales que la sangre.'],
['¿Cómo se llama el paso del agua a través de una membrana semipermeable','Es un tipo de transporte pasivo: no gasta energía.','Es lo que le pasa al glóbulo rojo en agua destilada.','La ósmosis es el paso del agua a través de una membrana semipermeable desde el lado con menos solutos hacia el lado con más solutos. Es transporte pasivo: no gasta ATP.'],
['Ordena los descubrimientos, del más antiguo al más reciente','El primero usó la palabra «célula» al mirar corcho, en el siglo XVII.','El último dijo «toda célula viene de otra célula», ya en el siglo XIX.','Hooke vio el corcho (1665); Leeuwenhoek vio microorganismos (1674); Schleiden (plantas) y Schwann (animales) propusieron que todos los seres vivos están hechos de células (1838-1839); y Virchow completó la teoría: toda célula viene de otra (1855).'],
['La teoría endosimbiótica de Lynn Margulis','«Endo» = dentro y «simbiosis» = vivir juntos.','Una prueba es que las mitocondrias tienen ADN propio, circular como el de las bacterias.','Según Lynn Margulis, las mitocondrias (y los cloroplastos) fueron bacterias que una célula mayor englobó y que se quedaron a vivir dentro de ella en beneficio mutuo. Por eso tienen ADN propio, ribosomas parecidos a los bacterianos y se dividen por su cuenta.'],
['¿Qué organelo contiene enzimas digestivas','Es el «servicio de reciclaje» de la célula.','Su nombre viene de «lisis», que significa romper.','Los lisosomas son vesículas llenas de enzimas digestivas: rompen organelos viejos, restos de alimento y bacterias que la célula ha englobado, y reciclan sus materiales.'],
['Las bacterias tienen el ADN dentro de un núcleo','','','Falso. Las bacterias son procariotas: su ADN está en el citoplasma, en una zona llamada nucleoide, sin membrana que lo rodee.'],
['¿Qué instrumento necesitas para ver un virus','Los virus son mucho más pequeños que una bacteria: miden nanómetros.','Necesitas un microscopio que no use luz, sino un haz de partículas.','Los virus miden entre 20 y 300 nanómetros, menos que el límite del microscopio óptico (unos 200 nm). Para verlos se usa el microscopio electrónico, que usa electrones en lugar de luz y aumenta cientos de miles de veces.'],
['La membrana celular es «semipermeable»','«Semi» significa «a medias».','Piensa en un colador que deja pasar el agua pero no los fideos.','Semipermeable quiere decir que la membrana deja pasar algunas sustancias (como el agua o el oxígeno) y otras no, o solo con ayuda de proteínas. Así la célula controla qué entra y qué sale.'],
['¿Cuál es la estructura que guarda el ADN en las células eucariotas','Es lo que NO tienen las procariotas.','Está rodeado por una doble membrana con poros.','El núcleo guarda el ADN de las células eucariotas. Lo rodea una envoltura nuclear doble con poros por donde sale el ARN mensajero hacia el citoplasma.'],
['El paso de sustancias en contra de su diferencia de concentración','Si va «cuesta arriba», necesita energía.','La bomba de sodio y potasio de las neuronas es un ejemplo.','El transporte activo mueve sustancias desde donde hay menos hacia donde hay más (en contra del gradiente) y por eso gasta ATP. Lo hacen proteínas de la membrana llamadas bombas, como la bomba de sodio y potasio.'],
['Un glóbulo blanco que envuelve y se «come»','La sustancia entra a la célula, así que el prefijo es «endo».','Cuando lo que se engloba es una partícula sólida grande se llama «fagocitosis» (comer).','Es endocitosis, en su forma de fagocitosis: la membrana del glóbulo blanco rodea a la bacteria y la encierra en una vesícula, que luego se une a un lisosoma para destruirla.'],
['En el laboratorio de las papas, la concentración de azúcar','Hay una variable que tú decides y otra que mides.','La que el investigador cambia a propósito para ver qué pasa es…','La concentración de azúcar es la variable independiente porque el investigador la escoge y la cambia a propósito. Lo que se mide como resultado (el cambio de masa de la papa) es la variable dependiente.'],
['¿Qué gas libera la fase luminosa de la fotosíntesis','Viene de romper moléculas de agua con la energía de la luz.','Es el gas que respiramos.','En la fase luminosa la luz rompe moléculas de agua (fotólisis): se liberan electrones, protones y oxígeno (O₂). Todo el oxígeno del aire que respiramos viene de este proceso.'],
['¿Dónde se arma la glucosa a partir del CO₂','Ocurre dentro del cloroplasto, pero no en las membranas (tilacoides).','Es el líquido que rodea a los tilacoides.','El ciclo de Calvin ocurre en el estroma, el líquido interno del cloroplasto. Allí se usan el ATP y el NADPH de la fase luminosa para fijar el CO₂ y armar glucosa.'],
['¿Cuántos ATP se obtienen aproximadamente de una glucosa','Con oxígeno se obtiene muchísimo más que sin él.','La fermentación da solo 2; la respiración con oxígeno da unas 18 veces más.','La respiración celular aerobia saca cerca de 36 a 38 ATP de cada glucosa. Sin oxígeno, la fermentación solo obtiene 2 ATP, por eso los músculos se cansan rápido cuando les falta oxígeno.'],
['Ordena las fases de la mitosis','La primera es cuando los cromosomas se condensan y se hacen visibles.','Recuerda la palabra «PMAT».','Profase (los cromosomas se condensan), metafase (se alinean en el centro), anafase (las cromátidas se separan hacia los polos) y telofase (se forman dos núcleos). Después la citocinesis divide el citoplasma.'],
['En la anafase se separan las cromátidas hermanas','','','Verdadero. En la anafase las fibras del huso jalan las cromátidas hermanas de cada cromosoma hacia polos opuestos, para que cada célula hija reciba una copia completa.'],
['El cáncer se produce cuando','Piensa en el ciclo celular y en sus «frenos».','Los puntos de control dejan de funcionar.','El cáncer aparece cuando mutaciones dañan los genes que controlan el ciclo celular: las células se dividen sin control, forman tumores y pueden invadir otros tejidos (metástasis).']
]);
BIO_NUEVAS([
{t:'celula',k:'mc',q:'¿Qué organelo fabrica proteínas cuando tiene ribosomas pegados a su superficie?',ops:['Retículo endoplasmático rugoso','Retículo endoplasmático liso','Vacuola','Centriolo'],a:0,p:['Es una red de membranas conectada con el núcleo.','Su nombre describe cómo se ve: áspero, por los ribosomas.'],exp:'El retículo endoplasmático rugoso tiene ribosomas pegados que le dan aspecto áspero; allí se fabrican las proteínas que luego van al aparato de Golgi. El liso no tiene ribosomas y fabrica lípidos.'},
{t:'celula',k:'mc',q:'¿Qué organelo grande guarda agua y sales en las células vegetales y les ayuda a mantenerse firmes?',ops:['Vacuola central','Lisosoma','Núcleo','Ribosoma'],a:0,p:['Ocupa casi todo el espacio dentro de la célula vegetal.','Cuando la planta se marchita es porque este organelo perdió agua.'],exp:'La vacuola central guarda agua, sales y pigmentos. Al llenarse, empuja contra la pared celular (turgencia) y mantiene firme a la planta; si pierde agua, la planta se marchita.'},
{t:'celula',k:'mc',q:'Schleiden y Schwann propusieron que…',ops:['todos los seres vivos están formados por células','la célula se divide por mitosis','los virus son células','las células salen de la materia sin vida'],a:0,p:['Uno estudiaba plantas y el otro animales.','Es el primer postulado de la teoría celular.'],exp:'Matthias Schleiden (plantas, 1838) y Theodor Schwann (animales, 1839) concluyeron que todos los seres vivos están formados por una o más células: el primer postulado de la teoría celular.'},
{t:'celula',k:'vf',q:'La célula es la unidad más pequeña que tiene vida propia.',a:true,exp:'Verdadero. La célula es la unidad básica de la vida: es lo más pequeño que se nutre, se relaciona y se reproduce por sí mismo. Sus partes (organelos, moléculas) por separado no están vivas.'},
{t:'celula',k:'mc',q:'¿Qué parte del microscopio óptico sirve para enfocar con precisión la muestra?',ops:['El tornillo micrométrico','El diafragma','La platina','El espejo'],a:0,p:['Hay dos tornillos: uno grueso y otro fino.','Se usa al final, con el objetivo de mayor aumento.'],exp:'El tornillo micrométrico mueve la platina muy poco y permite el enfoque fino. El macrométrico hace el enfoque grueso; el diafragma regula la luz y la platina sostiene la lámina.'},
{t:'celula',k:'mc',q:'Si un microscopio tiene un ocular de 10× y un objetivo de 40×, ¿cuál es el aumento total?',ops:['400×','50×','40×','4000×'],a:0,p:['Los dos lentes trabajan juntos: no se suman.','Multiplica el aumento del ocular por el del objetivo.'],exp:'El aumento total es el producto del ocular por el objetivo: 10 × 40 = 400 aumentos. La imagen se ve 400 veces más grande que el objeto real.'},
{t:'celula',k:'mc',q:'¿Qué estructura forma el esqueleto interno de la célula y le permite moverse y mantener su forma?',ops:['Citoesqueleto','Pared celular','Nucleolo','Membrana nuclear'],a:0,p:['Está formado por fibras y tubos de proteína en el citoplasma.','Su nombre combina «célula» y «esqueleto».'],exp:'El citoesqueleto es una red de filamentos y microtúbulos de proteína que da forma a la célula, sostiene los organelos, los transporta y forma el huso durante la división celular.'},
{t:'celula',k:'esc',q:'¿Cómo se llama el líquido gelatinoso que llena la célula y donde flotan los organelos?',a:['citoplasma','el citoplasma','citosol'],p:['Está entre la membrana y el núcleo.','Empieza por «cito», que significa célula.'],exp:'El citoplasma es todo lo que hay entre la membrana y el núcleo: un líquido gelatinoso (citosol) con los organelos. Allí ocurren muchas reacciones químicas de la célula.'},
{t:'celula',k:'mc',q:'El paso de oxígeno del alvéolo a la sangre, de donde hay más a donde hay menos y sin gastar energía, es:',ops:['difusión simple','transporte activo','endocitosis','exocitosis'],a:0,p:['Va «cuesta abajo», a favor del gradiente.','Es la forma más sencilla de transporte pasivo.'],exp:'Es difusión simple: las moléculas pequeñas como el O₂ y el CO₂ atraviesan la membrana desde donde están más concentradas hacia donde lo están menos, sin gastar ATP.'},
{t:'celula',k:'mc',q:'¿Qué produce la fermentación láctica en los músculos cuando falta oxígeno?',ops:['Ácido láctico','Alcohol','Oxígeno','Almidón'],a:0,p:['Es la misma fermentación que convierte la leche en yogur.','Su nombre lo dice: «láctica».'],exp:'Sin oxígeno, las células musculares hacen fermentación láctica: convierten la glucosa en ácido láctico y obtienen solo 2 ATP. Las levaduras, en cambio, hacen fermentación alcohólica (alcohol y CO₂).'},
{t:'celula',k:'ord',q:'Ordena los niveles, del más pequeño al más grande:',ops:['Molécula','Organelo','Célula','Tejido'],p:['El organelo es parte de una célula.','Muchas células parecidas forman el nivel más grande de la lista.'],exp:'Las moléculas forman organelos; los organelos forman la célula; y muchas células parecidas que trabajan juntas forman un tejido.'},
{t:'celula',k:'mc',q:'¿Para qué le sirve a la célula hacer mitosis?',ops:['Para crecer, reparar tejidos y reemplazar células','Para formar óvulos y espermatozoides','Para fabricar proteínas','Para hacer fotosíntesis'],a:0,p:['Las dos células hijas son idénticas a la madre.','Es lo que pasa cuando se cierra una herida.'],exp:'La mitosis produce dos células hijas idénticas a la madre, con el mismo número de cromosomas. Sirve para crecer, reparar heridas y reemplazar células viejas. Los gametos se forman por meiosis.'},
{t:'celula',k:'vf',q:'Los hongos tienen pared celular de celulosa, igual que las plantas.',a:false,exp:'Falso. Los hongos sí tienen pared celular, pero de quitina, el mismo material del caparazón de los insectos. La celulosa es propia de las plantas.'}
]);

/* ───────── REINOS Y CLASIFICACIÓN ───────── */
BIO_AJ('reinos',[
['Ordena las categorías de la más amplia a la más específica','La más amplia es la que agrupa a más seres vivos distintos.','Usa la frase «Doña Reina Fina Clara Ordena Familias Géneros Especies».','Dominio, Reino, Filo, Clase, Orden, Familia, Género y Especie. Al bajar de categoría hay menos organismos en cada grupo y se parecen más entre sí. La frase «Doña Reina Fina Clara Ordena Familias Géneros Especies» ayuda a recordarlo.'],
['¿Cuál nombre científico está bien escrito','Son dos palabras en latín: la primera es el género y la segunda la especie.','Solo el género lleva mayúscula, y todo va en cursiva (o subrayado a mano).','Se escribe Panthera onca, en cursiva: el género con mayúscula inicial y el epíteto de la especie en minúscula. Así lo estableció Linneo con el sistema binomial.'],
['¿A qué reino pertenecen los hongos','No son plantas: no hacen fotosíntesis.','Su nombre en latín significa precisamente «hongos».','Los hongos forman el reino Fungi: son eucariotas heterótrofos que se alimentan por absorción (sueltan enzimas y absorben lo digerido) y tienen pared de quitina. El champiñón es pluricelular y la levadura es unicelular.'],
['¿Qué tienen las células de los hongos en su pared celular','No es celulosa, como en las plantas.','Es el mismo material del caparazón de los insectos.','La pared de los hongos es de quitina, un polisacárido duro que también forma el exoesqueleto de insectos y crustáceos. Esa es una prueba de que los hongos están más cerca de los animales que de las plantas.'],
['Las bacterias y las cianobacterias pertenecen al reino','Son seres sin núcleo (procariotas).','En el modelo de cinco reinos de Whittaker es el único reino de procariotas.','En el modelo de cinco reinos, todas las procariotas (bacterias y cianobacterias) forman el reino Monera. Hoy se separan en dos dominios: Bacteria y Archaea.'],
['Las arqueas y las eubacterias son procariotas','','','Verdadero. Ambas carecen de núcleo, pero Carl Woese encontró que su pared, su membrana y sus genes (ARN ribosomal) son muy distintos; por eso las separó en dos dominios: Archaea y Bacteria.'],
['¿Quién propuso los tres dominios','Lo hizo en 1990 comparando el ARN de los ribosomas.','Fue un microbiólogo estadounidense, no Linneo ni Whittaker.','Carl Woese propuso en 1990 los tres dominios —Bacteria, Archaea y Eukarya— al comparar el ARN ribosomal de muchos organismos. Descubrió que las arqueas son tan distintas de las bacterias como de nosotros.'],
['¿Qué característica tienen las arqueas que NO tienen las eubacterias','Está en la química de su membrana.','Es un tipo de enlace químico que las hace resistentes al calor extremo.','Las arqueas tienen en su membrana lípidos unidos por enlaces éter, mucho más resistentes que los enlaces éster de bacterias y eucariotas. Por eso muchas arqueas viven en aguas hirvientes, muy ácidas o muy saladas.'],
['Una arquea que vive en las salinas de Manaure','El prefijo indica qué le gusta al organismo.','«Halo» significa sal y «filo» significa amante.','Es una arquea halófila («amante de la sal»). Vive en concentraciones de sal que matarían a casi cualquier otro ser vivo; algunas tiñen de rosado las salinas.'],
['La ameba y el paramecio pertenecen al reino','Son eucariotas (tienen núcleo) pero de una sola célula.','Es el reino «cajón de sastre» de los eucariotas que no son plantas, hongos ni animales.','La ameba y el paramecio son protistas: eucariotas unicelulares que viven en el agua. El reino Protista también incluye algas y otros seres sencillos con núcleo.'],
['¿Qué reino reúne a seres pluricelulares, autótrofos','Hacen fotosíntesis y no se desplazan.','Su pared celular es de celulosa.','El reino Plantae agrupa organismos pluricelulares, eucariotas, autótrofos por fotosíntesis (tienen cloroplastos) y con pared de celulosa.'],
['La esponja de mar es un animal','','','Verdadero. Aunque viva fija, la esponja es pluricelular, eucariota, heterótrofa por ingestión (filtra el agua para comer) y sus células no tienen pared celular: todas son características del reino Animalia.'],
['¿Cómo se llama la ciencia que nombra y clasifica','Su padre es Carl von Linneo.','Viene del griego «taxis» (orden) y «nomos» (ley).','La taxonomía es la ciencia que describe, nombra y clasifica a los seres vivos en grupos. Linneo creó el sistema binomial y las categorías que todavía usamos.'],
['El sistema de nombrar cada especie con dos palabras','«Bi» significa dos.','Lo creó Linneo en el siglo XVIII.','El sistema binomial, creado por Linneo, nombra cada especie con dos palabras en latín: el género y el epíteto específico (por ejemplo, Homo sapiens). Así un científico de cualquier país sabe de qué especie se habla.'],
['Una clave dicotómica funciona con','«Dicotómica» viene del griego «cortar en dos».','En cada paso escoges uno de dos caminos.','La clave dicotómica es una serie de preguntas o afirmaciones con dos opciones opuestas («tiene alas / no tiene alas»). Cada respuesta lleva al siguiente paso hasta identificar el grupo del organismo.'],
['¿En qué categoría se parecen MÁS los organismos','Entre más específica la categoría, más se parecen sus miembros.','Es la última de la lista Dominio → … → Género → ?','La especie es la categoría más específica: sus miembros se parecen tanto que pueden reproducirse entre sí y tener hijos fértiles.'],
['La cianobacteria es una planta porque hace fotosíntesis','','','Falso. La cianobacteria hace fotosíntesis, pero no tiene núcleo ni cloroplastos: es procariota, así que pertenece a Monera (dominio Bacteria). Hacer fotosíntesis no basta para ser planta.'],
['Colombia es el primer país del mundo en número de especies de','Son dos grupos: uno de animales con plumas y otro de plantas con flores muy vistosas.','La flor nacional de Colombia pertenece a uno de los dos grupos.','Colombia es el primer país del mundo en especies de aves (más de 1900) y de orquídeas (más de 4200). La flor nacional, la Cattleya trianae, es una orquídea.'],
['El modelo de cinco reinos fue propuesto por','No fue Linneo, que solo distinguía plantas y animales.','Fue un ecólogo estadounidense, en 1969.','Robert Whittaker propuso en 1969 los cinco reinos: Monera, Protista, Fungi, Plantae y Animalia, según el tipo de célula, el número de células y la forma de nutrición.'],
['Escribe el nombre del reino de los seres vivos sin núcleo','Son las bacterias.','Empieza por «M».','Monera es el reino de los procariotas (bacterias y cianobacterias) en el modelo de cinco reinos de Whittaker.']
]);
BIO_NUEVAS([
{t:'reinos',k:'mc',q:'¿Qué tienen en común todos los animales?',ops:['Son pluricelulares y heterótrofos por ingestión','Tienen pared celular','Hacen fotosíntesis','Son unicelulares'],a:0,p:['Piensa en cómo consiguen su alimento.','Tienen muchas células y se comen su alimento.'],exp:'Todos los animales son eucariotas, pluricelulares, heterótrofos por ingestión (tragan su alimento y lo digieren por dentro) y sus células no tienen pared celular.'},
{t:'reinos',k:'mc',q:'¿Cómo se nutren los hongos?',ops:['Por absorción: sueltan enzimas y absorben lo digerido','Por fotosíntesis','Tragan su alimento','Fabrican su alimento con sales minerales'],a:0,p:['No tienen boca ni clorofila.','Digieren el alimento por fuera de su cuerpo.'],exp:'Los hongos son heterótrofos por absorción: sueltan enzimas sobre la materia orgánica, la digieren por fuera y absorben las sustancias. Por eso muchos son descomponedores.'},
{t:'reinos',k:'mc',q:'Los líquenes que crecen sobre las rocas del páramo son una asociación entre:',ops:['un hongo y un alga o cianobacteria','una planta y un animal','dos bacterias','un musgo y un helecho'],a:0,p:['Son dos organismos de reinos distintos que viven juntos.','Uno da el refugio y la humedad; el otro hace fotosíntesis.'],exp:'Un liquen es un mutualismo entre un hongo, que da protección y humedad, y un alga o cianobacteria, que hace fotosíntesis y aporta alimento. Son pioneros: colonizan rocas desnudas.'},
{t:'reinos',k:'mc',q:'¿Qué grupo de plantas NO tiene vasos conductores (xilema y floema)?',ops:['Los musgos','Los helechos','Los pinos','Las orquídeas'],a:0,p:['Son plantas pequeñas que viven en lugares muy húmedos.','Por no tener vasos no pueden crecer altas.'],exp:'Los musgos (briofitos) no tienen vasos conductores: el agua pasa de célula a célula. Por eso son pequeños y viven en lugares húmedos. Helechos, pinos y plantas con flor sí son vasculares.'},
{t:'reinos',k:'mc',q:'¿Qué plantas tienen semillas desnudas, sin fruto, como el pino?',ops:['Gimnospermas','Angiospermas','Briofitos','Pteridofitos'],a:0,p:['«Gimnos» significa desnudo.','Forman conos o piñas en lugar de flores.'],exp:'Las gimnospermas (pinos, cipreses, el pino colombiano Podocarpus) tienen semillas «desnudas» en conos, sin un fruto que las cubra. Las angiospermas tienen flores y frutos que envuelven sus semillas.'},
{t:'reinos',k:'mc',q:'Los animales sin columna vertebral se llaman:',ops:['invertebrados','vertebrados','cordados','mamíferos'],a:0,p:['El prefijo «in» indica que les falta algo.','Son la gran mayoría de los animales, como los insectos.'],exp:'Los invertebrados no tienen columna vertebral; son más del 95 % de las especies animales (insectos, arañas, moluscos, gusanos…). Los vertebrados sí la tienen: peces, anfibios, reptiles, aves y mamíferos.'},
{t:'reinos',k:'mc',q:'La rana dorada venenosa del Chocó es un anfibio porque…',ops:['su piel es húmeda y su vida empieza en el agua','tiene plumas','tiene escamas secas','se alimenta de leche materna'],a:0,p:['«Anfibio» quiere decir «doble vida».','Sus crías (renacuajos) viven en el agua y respiran por branquias.'],exp:'Los anfibios tienen piel húmeda y sin escamas, ponen huevos sin cáscara en el agua y sus crías (renacuajos) respiran por branquias; de adultos pasan a la tierra: viven una «doble vida». La rana dorada (Phyllobates terribilis) es endémica del Chocó.'},
{t:'reinos',k:'vf',q:'Las aves y los mamíferos mantienen su temperatura corporal constante.',a:true,exp:'Verdadero. Aves y mamíferos son endotermos: producen su propio calor y lo conservan con plumas o pelo. Peces, anfibios y reptiles dependen del calor del ambiente.'},
{t:'reinos',k:'mc',q:'¿Qué característica tiene un insecto?',ops:['Seis patas y cuerpo en tres partes','Ocho patas','Columna vertebral','Pelo y glándulas mamarias'],a:0,p:['Cuenta las patas de una hormiga.','Su cuerpo se divide en cabeza, tórax y abdomen.'],exp:'Los insectos son artrópodos con seis patas, cuerpo dividido en cabeza, tórax y abdomen, un par de antenas y casi siempre alas. Las arañas, con ocho patas, son arácnidos.'},
{t:'reinos',k:'mc',q:'El nombre científico del oso de anteojos es Tremarctos ornatus. ¿Cuál es su género?',ops:['Tremarctos','ornatus','Ursidae','Mammalia'],a:0,p:['El nombre tiene dos palabras: ¿cuál va con mayúscula?','La primera palabra del nombre binomial es…'],exp:'En el nombre binomial la primera palabra (con mayúscula) es el género: Tremarctos. La segunda, ornatus, es el epíteto de la especie. Ursidae es la familia y Mammalia la clase.'},
{t:'reinos',k:'mc',q:'¿Por qué los virus no aparecen en ningún reino?',ops:['Porque no son células','Porque son muy grandes','Porque hacen fotosíntesis','Porque viven solo en el mar'],a:0,p:['Los reinos agrupan seres vivos formados por células.','Recuerda qué les falta a los virus: citoplasma, ribosomas…'],exp:'Los virus no están en ningún reino porque no son células: solo tienen material genético dentro de una cápsula de proteínas y necesitan una célula para multiplicarse. Muchos científicos no los consideran seres vivos.'},
{t:'reinos',k:'mc',q:'¿Qué protista produce la malaria, enfermedad que transmite el mosquito Anopheles?',ops:['Plasmodium','Ameba','Paramecio','Euglena'],a:0,p:['Es un parásito que vive dentro de los glóbulos rojos.','Su nombre empieza por «P».'],exp:'La malaria (paludismo) la causa el protista Plasmodium, que el mosquito Anopheles hembra pasa a la sangre al picar. El parásito destruye los glóbulos rojos y produce fiebres. Es frecuente en zonas cálidas de Colombia como el Pacífico.'},
{t:'reinos',k:'esc',q:'¿Cómo se llama la clase de vertebrados que tienen pelo y alimentan a sus crías con leche?',a:['mamiferos','los mamiferos','mamifero'],p:['Los seres humanos pertenecemos a esta clase.','Su nombre viene de «mama», la glándula que produce leche.'],exp:'Los mamíferos tienen pelo, glándulas mamarias que producen leche y son endotermos. Ejemplos colombianos: el jaguar, el oso de anteojos, la danta y el delfín rosado.'},
{t:'reinos',k:'ord',q:'Ordena desde el dominio hasta la especie del ser humano:',ops:['Eukarya','Animalia','Chordata','Mammalia','Primates','Hominidae','Homo','Homo sapiens'],p:['Empieza por el dominio de los seres con núcleo.','Después del reino vienen filo (cordados), clase (mamíferos) y orden (primates).'],exp:'Dominio Eukarya → reino Animalia → filo Chordata → clase Mammalia → orden Primates → familia Hominidae → género Homo → especie Homo sapiens.'},
{t:'reinos',k:'mc',q:'Las algas verdes, rojas y pardas se clasifican tradicionalmente en el reino:',ops:['Protista','Plantae','Fungi','Monera'],a:0,p:['Hacen fotosíntesis, pero no tienen raíz, tallo ni hojas verdaderas.','Es el mismo reino de la ameba.'],exp:'En el modelo de cinco reinos, las algas están en Protista: son eucariotas que hacen fotosíntesis, pero no forman tejidos ni órganos verdaderos como las plantas.'},
{t:'reinos',k:'vf',q:'El champiñón hace fotosíntesis porque vive en la tierra como las plantas.',a:false,exp:'Falso. El champiñón es un hongo: no tiene clorofila ni cloroplastos, así que no hace fotosíntesis. Se alimenta por absorción de materia orgánica en descomposición.'},
{t:'reinos',k:'mc',q:'¿Qué criterio usó Whittaker para separar los cinco reinos?',ops:['Tipo de célula, número de células y forma de nutrición','El color y el tamaño','El lugar donde viven','Si son útiles o dañinos'],a:0,p:['Son características de la célula y de la alimentación, no del aspecto.','Pregúntate: ¿tiene núcleo?, ¿una o muchas células?, ¿cómo come?'],exp:'Whittaker clasificó a los seres vivos según el tipo de célula (procariota o eucariota), el número de células (unicelular o pluricelular) y la forma de nutrición (fotosíntesis, absorción o ingestión).'},
{t:'reinos',k:'mc',q:'¿Qué organismo pertenece al reino Monera?',ops:['Escherichia coli (bacteria del intestino)','La levadura del pan','El paramecio','El helecho'],a:0,p:['Busca el que no tiene núcleo.','Es una bacteria.'],exp:'Escherichia coli es una bacteria (procariota), por eso pertenece a Monera. La levadura es un hongo, el paramecio un protista y el helecho una planta.'},
{t:'reinos',k:'mc',q:'Una especie endémica es la que…',ops:['solo vive en un lugar del mundo','vive en todos los continentes','fue traída de otro país','ya está extinta'],a:0,p:['Es lo contrario de una especie que está en todas partes.','El colibrí de Santa Marta solo vive en la Sierra Nevada.'],exp:'Una especie endémica vive solo en una región determinada y en ningún otro lugar del mundo. Colombia tiene muchas, como la rana dorada del Chocó o aves de la Sierra Nevada de Santa Marta.'},
{t:'reinos',k:'mc',q:'Los reptiles, como la tortuga y la iguana, se caracterizan por…',ops:['piel seca con escamas y huevos con cáscara','piel húmeda y renacuajos','plumas','pelo y leche materna'],a:0,p:['Piensa en la piel de una iguana.','Sus huevos pueden ponerse en tierra porque tienen cubierta protectora.'],exp:'Los reptiles tienen piel seca cubierta de escamas, respiran por pulmones y ponen huevos con cáscara que no se secan en tierra. Dependen del calor del ambiente (ectotermos).'},
{t:'reinos',k:'vf',q:'Los hongos están más emparentados con los animales que con las plantas.',a:true,exp:'Verdadero. Los estudios de ADN muestran que hongos y animales comparten un antepasado más reciente que con las plantas. Una pista: ambos son heterótrofos y usan quitina (pared de los hongos, caparazón de los insectos).'}
]);

/* ───────── SISTEMAS DEL CUERPO ───────── */
BIO_AJ('sistemas',[
['Ordena del nivel más sencillo al más complejo','Empieza por la unidad más pequeña con vida.','Varias células forman un tejido; varios tejidos, un órgano.','Célula → tejido (células parecidas) → órgano (varios tejidos, como el corazón) → sistema (órganos que trabajan juntos, como el circulatorio) → organismo completo.'],
['¿A qué tipo de tejido pertenece la sangre','Aunque sea líquida, es un tejido.','Es el mismo grupo de tejidos que el hueso y el cartílago: unen y sostienen.','La sangre es tejido conectivo: células (glóbulos rojos, blancos y plaquetas) dispersas en una matriz líquida, el plasma. El conectivo también incluye hueso, cartílago y grasa.'],
['¿Dónde ocurre la mayor parte de la absorción de nutrientes','Es el tubo más largo del sistema digestivo, unos 6 metros.','Sus paredes tienen millones de pliegues llamados vellosidades.','En el intestino delgado se termina la digestión y se absorben los nutrientes. Sus vellosidades aumentan mucho la superficie que toca el alimento, y por allí los nutrientes pasan a la sangre.'],
['¿Qué órgano produce la bilis','Es el órgano interno más grande del cuerpo.','La vesícula biliar solo guarda la bilis; la fabrica otro órgano.','El hígado produce la bilis, que la vesícula biliar almacena y suelta en el intestino delgado. La bilis divide las grasas en gotitas para que las enzimas puedan digerirlas.'],
['¿Cómo se llaman los sacos diminutos de los pulmones','Están al final de los bronquiolos, como racimos de uvas.','Están rodeados de capilares sanguíneos.','Los alvéolos pulmonares son sacos diminutos rodeados de capilares: el oxígeno pasa del aire a la sangre y el CO₂ de la sangre al aire, por difusión. Hay unos 300 millones en los pulmones.'],
['¿Qué vasos sanguíneos llevan la sangre DESDE el corazón','Tienen paredes gruesas porque resisten la presión del bombeo.','Son los vasos donde se toma el pulso.','Las arterias llevan la sangre desde el corazón hacia el cuerpo; tienen paredes gruesas y elásticas por la presión. Las venas la devuelven al corazón y los capilares conectan unas con otras.'],
['¿Qué órganos filtran la sangre y producen la orina','Son dos órganos con forma de fríjol.','Están en la parte de atrás del abdomen, a los lados de la columna.','Los riñones filtran la sangre en millones de nefronas, retiran la urea, el exceso de sales y de agua, y forman la orina, que baja por los uréteres a la vejiga.'],
['¿Cuántas cavidades tiene el corazón humano','Hay cavidades arriba que reciben la sangre y abajo que la impulsan.','Son dos aurículas y …','El corazón humano tiene 4 cavidades: dos aurículas arriba (reciben la sangre) y dos ventrículos abajo (la impulsan). El lado derecho envía sangre a los pulmones y el izquierdo al resto del cuerpo.'],
['El sistema endocrino se comunica con hormonas','','','Verdadero. Las glándulas endocrinas sueltan hormonas a la sangre, que las lleva a todo el cuerpo. Por eso su efecto es más lento que el de los impulsos nerviosos, pero dura más.'],
['¿Qué glándula produce la adrenalina','Es la hormona del susto: acelera el corazón.','Están encima de los riñones.','Las glándulas suprarrenales, ubicadas sobre los riñones, producen la adrenalina, que prepara al cuerpo para «luchar o huir»: acelera el corazón y la respiración y sube el azúcar en la sangre.'],
['¿Qué hormona regula el azúcar de la sangre','La produce el páncreas.','Las personas con diabetes tipo 1 deben inyectársela.','La insulina, producida por el páncreas, hace que las células tomen la glucosa de la sangre y así baja el azúcar. Si el páncreas no la produce o el cuerpo no responde a ella, aparece la diabetes.'],
['¿Qué estructura controla los actos reflejos','La respuesta ocurre antes de que el cerebro se entere.','Está protegida dentro de la columna vertebral.','La médula espinal controla los actos reflejos: recibe el mensaje del receptor y envía la orden al músculo directamente, sin esperar al cerebro. Así quitamos la mano del fuego en una fracción de segundo.'],
['¿Por qué los músculos trabajan en pares','Un músculo solo hace fuerza cuando se contrae (se acorta).','Piensa en qué pasa con el tríceps cuando el bíceps dobla el brazo.','Los músculos solo pueden jalar al contraerse; no pueden empujar. Por eso trabajan en pares opuestos: el bíceps se contrae para doblar el brazo y el tríceps se contrae para estirarlo.'],
['Ordena el recorrido del alimento','Empieza donde se mastica.','El estómago está antes de los intestinos; el intestino grueso es el último tramo.','Boca (masticación y saliva) → esófago (tubo que lo lleva) → estómago (jugos gástricos) → intestino delgado (absorción de nutrientes) → intestino grueso (absorción de agua y formación de heces).'],
['El músculo que baja al contraerse y hace entrar el aire','Está debajo de los pulmones y los separa del abdomen.','Tiene forma de cúpula.','El diafragma es un músculo en forma de cúpula bajo los pulmones. Al contraerse baja, el tórax se agranda y el aire entra (inspiración); al relajarse sube y el aire sale.'],
['El sistema circulatorio, el digestivo y el respiratorio cumplen sobre todo la función de','Piensa para qué sirve comer, respirar y que la sangre circule.','Los tres ayudan a conseguir y repartir materia y energía a las células.','Los tres cumplen la función de nutrición: el digestivo obtiene los nutrientes, el respiratorio el oxígeno, y el circulatorio los reparte a todas las células (junto con el excretor, que saca los desechos).'],
['¿Cómo se llama el hueso más largo y fuerte del cuerpo humano','Está en la pierna.','Está en el muslo, entre la cadera y la rodilla.','El fémur, en el muslo, es el hueso más largo y fuerte del cuerpo: soporta el peso al caminar y correr.'],
['La piel también es un órgano excretor','','','Verdadero. Las glándulas sudoríparas de la piel eliminan sudor, que lleva agua, sales y algo de urea. Además, el sudor ayuda a regular la temperatura.'],
['La tiroides necesita yodo','La tiroides fabrica hormonas que llevan yodo.','La falta de yodo hace que la glándula se agrande en el cuello.','La tiroides usa yodo para fabricar sus hormonas. Si falta, la glándula crece (bocio) y hay problemas de crecimiento y desarrollo. Por eso en Colombia la sal de cocina se yoda por ley.'],
['¿Cuál de estos NO es uno de los cuatro tejidos animales básicos','Los cuatro son epitelial, conectivo, muscular y nervioso.','Una de las opciones es un tejido que conduce agua en las plantas.','Los cuatro tejidos animales son epitelial, conectivo, muscular y nervioso. El xilema es un tejido vegetal: conduce el agua y las sales desde la raíz hasta las hojas.'],
['Los anticuerpos los fabrican los','Son glóbulos blancos del sistema inmune específico.','Son un tipo de linfocito, distinto de los T.','Los linfocitos B fabrican anticuerpos: proteínas en forma de Y que se pegan a los microbios y los marcan para que otras células los destruyan.'],
['¿Por qué funcionan las vacunas','Tienen el microbio muerto, debilitado o solo una parte de él.','El sistema inmune «recuerda» lo que ya conoció.','La vacuna presenta al sistema inmune una parte o una versión inofensiva del microbio. Se forman anticuerpos y células de memoria sin enfermarse; si después llega el microbio real, la respuesta es rápida y fuerte.'],
['Los antibióticos sirven para curar la gripa','','','Falso. La gripa la causa un virus, y los antibióticos solo matan bacterias. Usarlos sin necesidad favorece que las bacterias se vuelvan resistentes.'],
['Después de comer, el azúcar de la sangre sube','Es una hormona del páncreas.','Es la misma hormona que falla en la diabetes.','Al subir la glucosa después de comer, el páncreas libera insulina, que hace que las células y el hígado tomen la glucosa. Así el azúcar en la sangre vuelve a su nivel normal: es un ejemplo de homeostasis.'],
['¿Cómo se llama la capacidad del cuerpo de mantener estables','Viene del griego «homeo» (igual) y «stasis» (estable).','El sudor y el escalofrío son ejemplos.','La homeostasis es la capacidad de mantener estable el medio interno (temperatura, agua, azúcar, pH) aunque cambie el exterior. Por ejemplo, sudamos para bajar la temperatura.'],
['La papa que brota de un tubérculo','Solo hay un progenitor.','Los hijos son clones de la planta madre.','Es reproducción asexual vegetativa: una parte de la planta (el tubérculo) forma una planta nueva, idéntica a la madre. No hay gametos ni variación genética.'],
['¿Qué ventaja tiene la reproducción sexual','Se mezclan los genes de dos progenitores.','Esa mezcla hace que los hijos sean diferentes entre sí.','La reproducción sexual combina los genes de dos padres, así que los hijos tienen variabilidad genética. Esa variedad aumenta la probabilidad de que algunos sobrevivan si el ambiente cambia.'],
['¿Dónde ocurre normalmente la fecundación en los seres humanos','No es en el útero, aunque allí se desarrolle el bebé.','Es el conducto que va del ovario al útero.','La fecundación ocurre normalmente en la trompa de Falopio, donde el espermatozoide se une al óvulo. El cigoto baja dividiéndose y se implanta en el útero unos 7 días después.'],
['¿Hacia qué semana del embarazo termina la etapa de embrión','Ocurre al final del segundo mes.','En ese momento ya están formados los órganos principales.','Hacia la semana 8 termina la etapa embrionaria, cuando ya se formaron los órganos principales. Desde allí y hasta el parto (semana 38-40) se le llama feto, que sobre todo crece y madura.']
]);
BIO_NUEVAS([
{t:'sistemas',k:'mc',q:'¿Qué tipo de célula transmite los mensajes del sistema nervioso?',ops:['La neurona','El glóbulo rojo','El osteocito','El adipocito'],a:0,p:['Tiene dendritas y un axón muy largo.','Su mensaje es un impulso eléctrico.'],exp:'La neurona es la célula del sistema nervioso: recibe estímulos por sus dendritas y conduce impulsos eléctricos por su axón hasta otra neurona o un músculo, a través de la sinapsis.'},
{t:'sistemas',k:'mc',q:'¿Qué célula de la sangre transporta el oxígeno?',ops:['Glóbulo rojo','Glóbulo blanco','Plaqueta','Linfocito'],a:0,p:['Contiene hemoglobina, que tiene hierro.','Su color le da el color a la sangre.'],exp:'Los glóbulos rojos (eritrocitos) contienen hemoglobina, una proteína con hierro que se une al oxígeno en los pulmones y lo suelta en los tejidos. Los glóbulos blancos defienden y las plaquetas coagulan.'},
{t:'sistemas',k:'mc',q:'¿Qué parte del encéfalo controla el equilibrio y la coordinación de los movimientos?',ops:['Cerebelo','Bulbo raquídeo','Médula espinal','Hipófisis'],a:0,p:['Está en la parte de atrás y abajo del encéfalo.','Su nombre significa «cerebro pequeño».'],exp:'El cerebelo coordina los movimientos y mantiene el equilibrio y la postura. El cerebro piensa y ordena los movimientos voluntarios; el bulbo raquídeo controla la respiración y el latido.'},
{t:'sistemas',k:'mc',q:'La sangre sin oxígeno sale del corazón hacia los pulmones por:',ops:['la arteria pulmonar','la aorta','la vena cava','las venas pulmonares'],a:0,p:['Sale del corazón, así que es una arteria.','Sale del ventrículo derecho y va a los pulmones.'],exp:'La arteria pulmonar lleva la sangre pobre en oxígeno del ventrículo derecho a los pulmones (circulación menor). Es la única arteria que lleva sangre sin oxígeno; regresa oxigenada por las venas pulmonares.'},
{t:'sistemas',k:'esc',q:'¿Cómo se llaman los vasos sanguíneos más delgados, donde la sangre intercambia sustancias con las células?',a:['capilares','los capilares','capilar'],p:['Son tan delgados como un cabello, o más.','Unen las arterias más pequeñas con las venas más pequeñas.'],exp:'Los capilares son vasos de paredes muy delgadas (una sola capa de células) que unen arterias y venas. A través de ellos pasan oxígeno y nutrientes a las células, y CO₂ y desechos a la sangre.'},
{t:'sistemas',k:'mc',q:'¿Qué enzima de la saliva empieza la digestión del almidón en la boca?',ops:['Amilasa','Pepsina','Bilis','Insulina'],a:0,p:['Su nombre se parece a «almidón» en latín (amylum).','Por eso el pan se pone dulce si lo masticas mucho rato.'],exp:'La amilasa salival empieza a romper el almidón en azúcares más sencillos; por eso el pan sabe dulce si se mastica mucho. La pepsina digiere proteínas en el estómago y la bilis emulsiona grasas.'},
{t:'sistemas',k:'mc',q:'¿Qué hormona producen los testículos y causa los cambios de la pubertad en los hombres?',ops:['Testosterona','Estrógeno','Insulina','Adrenalina'],a:0,p:['Su nombre recuerda al órgano que la fabrica.','Produce cambio de voz, vello y aumento de músculo.'],exp:'Los testículos producen testosterona, responsable de los caracteres sexuales secundarios masculinos (voz grave, vello, músculos). Los ovarios producen estrógenos y progesterona.'},
{t:'sistemas',k:'vf',q:'Las venas tienen válvulas que impiden que la sangre se devuelva.',a:true,exp:'Verdadero. Como la sangre de las venas va con poca presión, sobre todo en las piernas, las válvulas evitan que se devuelva. Si fallan, aparecen las várices.'},
{t:'sistemas',k:'mc',q:'¿Cuál es la función principal del intestino grueso?',ops:['Absorber agua y formar las heces','Producir bilis','Digerir proteínas','Producir insulina'],a:0,p:['Para cuando el alimento llega allí, los nutrientes ya se absorbieron.','Si funciona mal, aparece diarrea o estreñimiento.'],exp:'El intestino grueso absorbe la mayor parte del agua que queda y forma las heces. Además, sus bacterias (microbiota) producen algunas vitaminas como la K.'},
{t:'sistemas',k:'ord',q:'Ordena el camino del aire al respirar:',ops:['Nariz','Faringe','Laringe','Tráquea','Bronquios','Alvéolos'],p:['El aire entra por la nariz y termina en los sacos donde se intercambian gases.','La laringe (donde está la voz) va antes de la tráquea.'],exp:'Nariz (calienta y filtra) → faringe → laringe (cuerdas vocales) → tráquea → bronquios → bronquiolos → alvéolos, donde ocurre el intercambio de gases.'},
{t:'sistemas',k:'mc',q:'¿Qué sentido se pierde si se daña el nervio óptico?',ops:['La vista','El oído','El olfato','El gusto'],a:0,p:['«Óptico» tiene que ver con la luz.','Conecta la retina con el cerebro.'],exp:'El nervio óptico lleva la información de la retina al cerebro. Si se daña, se pierde la vista aunque el ojo esté sano: quien «ve» realmente es el cerebro.'},
{t:'sistemas',k:'mc',q:'¿Qué sistema forman los huesos y cuál es una de sus funciones?',ops:['Esquelético: sostiene y protege los órganos','Muscular: produce hormonas','Nervioso: filtra la sangre','Excretor: mueve el cuerpo'],a:0,p:['El cráneo protege el encéfalo y las costillas a los pulmones.','También fabrica células de la sangre en la médula ósea.'],exp:'El sistema esquelético (206 huesos en el adulto) sostiene el cuerpo, protege órganos (cráneo, costillas), permite el movimiento junto con los músculos, guarda calcio y produce células sanguíneas en la médula ósea roja.'},
{t:'sistemas',k:'vf',q:'El sistema nervioso y el endocrino trabajan juntos para coordinar el cuerpo.',a:true,exp:'Verdadero. Ambos son sistemas de control y relación: el nervioso con impulsos eléctricos rápidos y el endocrino con hormonas más lentas. El hipotálamo, en el encéfalo, conecta los dos.'}
]);

/* ───────── GENÉTICA ───────── */
BIO_AJ('genetica',[
['Un organismo con genotipo Aa es','«Homo» significa igual y «hetero» significa diferente.','Fíjate si las dos letras son iguales o distintas.','Aa es heterocigoto porque tiene dos alelos diferentes del mismo gen: uno dominante (A) y uno recesivo (a). AA y aa son homocigotos. Un heterocigoto muestra el carácter dominante.'],
['Al cruzar AA × aa','Un padre solo puede dar A y el otro solo puede dar a.','Haz el cuadro de Punnett: las cuatro casillas son iguales.','Todos los hijos son Aa. El padre AA solo produce gametos A y el aa solo gametos a, así que cada hijo recibe una A y una a. Es la 1.ª ley de Mendel (uniformidad).'],
['En un cruce Aa × Aa, ¿qué proporción','Haz el cuadro de Punnett de 2 × 2.','El carácter recesivo solo aparece en aa. ¿Cuántas de las 4 casillas son aa?','Del cruce Aa × Aa salen AA, Aa, Aa y aa. Solo aa muestra el carácter recesivo: 1 de 4, es decir, 25 %. La proporción de fenotipos es 3 dominantes : 1 recesivo.'],
['En un cruce Aa × aa, ¿qué probabilidad','El padre aa solo puede dar a.','Del padre Aa, la mitad de los gametos llevan a.','El cruce Aa × aa da Aa, Aa, aa y aa: 2 de las 4 casillas son aa, es decir, 50 %. Este cruce se usa como cruce de prueba para saber si un individuo dominante es AA o Aa.'],
['El fenotipo es la combinación de alelos','','','Falso. La combinación de alelos (las letras, como Aa) es el genotipo. El fenotipo es lo que se observa o se mide: el color, la forma, el grupo sanguíneo.'],
['¿Qué proporción fenotípica da el cruce dihíbrido','Son dos genes a la vez, cada uno con 3:1.','El cuadro tiene 16 casillas.','El cruce AaBb × AaBb da 9 con los dos caracteres dominantes, 3 con el primero dominante y el segundo recesivo, 3 al revés y 1 con los dos recesivos: 9:3:3:1, de 16 combinaciones. Se debe a la 3.ª ley de Mendel.'],
['¿Con qué planta hizo Mendel sus experimentos','Es una leguminosa que se come en sopas.','Su nombre científico es Pisum sativum.','Mendel trabajó con la arveja (guisante) porque crece rápido, tiene muchos hijos, se puede autopolinizar o cruzar a mano y tiene caracteres fáciles de ver (color, forma de la semilla).'],
['Una persona AB tiene el genotipo','En el grupo AB se expresan los dos alelos a la vez.','Iᴬ e Iᴮ son codominantes.','El grupo AB tiene genotipo IᴬIᴮ: los dos alelos son codominantes y ambos se expresan, así que en los glóbulos rojos están los antígenos A y B.'],
['Una persona de grupo O tiene genotipo','El alelo i es recesivo frente a Iᴬ e Iᴮ.','Para que se exprese un recesivo debe estar doble.','El grupo O solo aparece con genotipo ii, porque el alelo i es recesivo: basta un Iᴬ o un Iᴮ para que la persona sea A o B.'],
['Al cruzar una flor roja (RR) con una blanca (BB)','El hijo no se parece a ninguno de los padres: es una mezcla.','Ninguno de los alelos domina al otro por completo.','Es dominancia incompleta: el heterocigoto tiene un fenotipo intermedio (rosado) porque ningún alelo domina. En la codominancia, en cambio, se ven los dos caracteres a la vez (como en el grupo AB).'],
['El daltonismo es más frecuente en hombres','','','Verdadero. El gen está en el cromosoma X. El hombre (XY) tiene un solo X, así que le basta un alelo Xᵈ para ser daltónico; la mujer (XX) necesita dos.'],
['En el ADN, la adenina (A) siempre se une con','Las bases se unen en parejas fijas.','Recuerda: A con … y C con G.','En el ADN la adenina se une con la timina (A–T) y la citosina con la guanina (C–G). Esta regla de complementariedad permite copiar el ADN.'],
['Escribe la cadena complementaria de ADN para','Cambia cada base por su pareja.','A ↔ T y G ↔ C.','Se reemplaza cada base por su complementaria: A→T, T→A, G→C, C→G. Así, ATGC da TACG.'],
['¿Quién obtuvo la «Foto 51»','Fue una científica británica experta en rayos X.','Watson y Crick usaron su foto sin que ella lo supiera.','Rosalind Franklin obtuvo en 1952 la «Foto 51» por difracción de rayos X, que mostraba que el ADN es una hélice. Con ella Watson y Crick propusieron el modelo de doble hélice en 1953.'],
['¿Qué base tiene el ARN en lugar de la timina','El ARN tiene A, C, G y una cuarta base distinta.','Empieza por «U».','El ARN tiene uracilo (U) en lugar de timina. Además, el ARN tiene una sola cadena y su azúcar es la ribosa (el del ADN es la desoxirribosa).'],
['Ordena el «dogma central» de la biología','La información va del material hereditario a lo que hace el trabajo en la célula.','Primero se transcribe y después se traduce.','ADN → ARN mensajero (transcripción, en el núcleo) → proteína (traducción, en los ribosomas). Es el camino de la información genética.'],
['¿Dónde ocurre la traducción del ARN mensajero','Es la estructura que fabrica proteínas.','La tienen todas las células, incluso las bacterias.','La traducción ocurre en los ribosomas: leen el ARN mensajero de tres en tres bases (codones) y unen los aminoácidos en el orden indicado.'],
['Un codón está formado por','Cada codón indica un aminoácido.','Hay 64 codones posibles: 4 × 4 × 4.','Un codón tiene 3 bases del ARN mensajero. Con 4 bases tomadas de 3 en 3 hay 64 combinaciones, suficientes para los 20 aminoácidos y las señales de parada.'],
['La anemia falciforme se produce por','Es una mutación muy pequeña.','Cambia un solo aminoácido de la hemoglobina.','La anemia falciforme se debe a una sustitución de una sola base: GAG cambia a GUG y el ácido glutámico se reemplaza por valina. La hemoglobina cambia y los glóbulos rojos se deforman en forma de hoz.'],
['Una inserción de una sola base puede cambiar','','','Verdadero. El ribosoma lee de tres en tres: si se agrega una base, se corre el marco de lectura y cambian todos los codones siguientes, así que la proteína queda muy distinta o se corta.'],
['¿Cuántas células hijas produce la meiosis','Hay dos divisiones seguidas.','Cada una de las dos células de la primera división se divide otra vez.','La meiosis tiene dos divisiones y produce 4 células hijas haploides (con la mitad de los cromosomas), todas diferentes entre sí. Así se forman los gametos.'],
['Una célula humana con 46 cromosomas hace meiosis','La meiosis reduce el número de cromosomas.','Al unirse óvulo y espermatozoide, el cigoto debe volver a tener 46.','Cada gameto tiene 23 cromosomas, la mitad. Al unirse un óvulo (23) y un espermatozoide (23), el cigoto vuelve a tener 46.'],
['La transmisión independiente de Mendel se explica','Ocurre en la primera división de la meiosis.','Cada pareja de cromosomas se acomoda en el centro sin «mirar» a las demás.','En la metafase I cada pareja de cromosomas homólogos se orienta al azar, sin depender de las otras. Por eso los genes de cromosomas distintos se heredan de forma independiente (3.ª ley de Mendel).'],
['¿Qué tipo de ARN lleva los aminoácidos al ribosoma','Hay tres tipos de ARN: mensajero, ribosomal y …','Tiene un anticodón que encaja con el codón.','El ARN de transferencia (ARNt) carga un aminoácido en un extremo y tiene un anticodón en el otro, que se empareja con el codón del ARN mensajero en el ribosoma.'],
['La replicación del ADN es semiconservativa','«Semi» significa mitad.','Cada cadena original sirve de molde.','Al copiarse, las dos cadenas del ADN se separan y cada una sirve de molde para una nueva. Cada molécula hija conserva una cadena vieja y tiene una nueva: por eso se llama semiconservativa.'],
['Dos padres sin albinismo tienen una hija albina','El albinismo es recesivo: la hija es aa.','La hija recibió una a de cada padre, pero ellos no son albinos.','Los dos padres son Aa (portadores): no son albinos porque tienen un alelo A, pero cada uno le pasó una a a la hija. Entre sus hijos, la probabilidad de un hijo albino es 25 %.'],
['La estatura depende de muchos genes y de la alimentación','«Poli» significa muchos.','No hay solo «altos» y «bajos»: hay toda una gama.','La estatura es herencia poligénica (muchos genes suman su efecto) e influida por el ambiente (alimentación, salud). Por eso los valores forman una curva de campana en la población.'],
['¿Cuál de estos es un agente mutágeno','Un mutágeno daña el ADN.','Por eso se recomienda usar bloqueador solar.','La radiación ultravioleta del sol daña el ADN de las células de la piel y puede causar mutaciones y cáncer de piel. Otros mutágenos son el humo del cigarrillo y los rayos X en exceso.'],
['Un organismo al que se le insertó un gen de otra especie','Se hace con ingeniería genética.','«Trans» significa «a través de» o «de un lado a otro».','Un organismo transgénico tiene un gen de otra especie insertado con ingeniería genética, como el maíz Bt (resistente a insectos) o las bacterias que producen insulina humana.'],
['La oveja Dolly fue el primer mamífero obtenido por','Es una copia genética exacta de otro animal.','Se usó el núcleo de una célula adulta de la ubre.','Dolly (1996) fue el primer mamífero clonado a partir de una célula adulta: se puso el núcleo de una célula de la ubre en un óvulo sin núcleo. Era genéticamente idéntica a la oveja donante.']
]);
BIO_NUEVAS([
{t:'genetica',k:'mc',q:'¿Qué es un gen?',ops:['Un fragmento de ADN con la información para una característica','Un tipo de célula','Una proteína de la sangre','Un organelo'],a:0,p:['Está en los cromosomas.','Contiene las instrucciones para fabricar una proteína.'],exp:'Un gen es un fragmento de ADN que tiene la información para fabricar una proteína, y así determina una característica. Los genes están en los cromosomas y se heredan de padres a hijos.'},
{t:'genetica',k:'mc',q:'¿Cuántos cromosomas tiene una célula del cuerpo humano (no sexual)?',ops:['46','23','48','92'],a:0,p:['Son 23 parejas.','Es el doble de los que tiene un gameto.'],exp:'Las células somáticas humanas tienen 46 cromosomas en 23 parejas: 22 parejas de autosomas y una de cromosomas sexuales (XX en la mujer, XY en el hombre).'},
{t:'genetica',k:'mc',q:'¿Qué cromosomas sexuales tiene un hombre?',ops:['XY','XX','YY','X solo'],a:0,p:['La madre siempre aporta una X.','El sexo del bebé depende del cromosoma que aporta el espermatozoide.'],exp:'El hombre tiene XY y la mujer XX. Como la madre siempre aporta una X, el sexo del bebé depende de si el espermatozoide lleva X (niña) o Y (niño): la probabilidad es 50 %.'},
{t:'genetica',k:'vf',q:'Un alelo dominante se expresa aunque esté en una sola copia.',a:true,exp:'Verdadero. Basta una copia del alelo dominante (Aa) para que se vea su carácter. El recesivo solo se expresa cuando está en las dos copias (aa).'},
{t:'genetica',k:'mc',q:'Si una pareja ya tuvo tres hijos varones, ¿qué probabilidad hay de que el cuarto sea niña?',ops:['50 %','25 %','75 %','100 %'],a:0,p:['Cada embarazo es independiente de los anteriores.','Piensa en el cruce XX × XY.'],exp:'Cada fecundación es un evento independiente: los hijos anteriores no cambian la probabilidad. En el cruce XX × XY, la mitad de los espermatozoides lleva X, así que la probabilidad es 50 %.'},
{t:'genetica',k:'mc',q:'¿Cuál es la forma del ADN?',ops:['Doble hélice','Una sola cadena recta','Un círculo de proteínas','Una esfera'],a:0,p:['Parece una escalera torcida.','Tiene dos cadenas enrolladas.'],exp:'El ADN es una doble hélice: dos cadenas de nucleótidos enrolladas, unidas por las bases complementarias (A–T, C–G) como los peldaños de una escalera de caracol.'},
{t:'genetica',k:'esc',q:'¿Cómo se llama el padre de la genética, que descubrió las leyes de la herencia con arvejas?',a:['mendel','gregor mendel','gregorio mendel'],p:['Era un monje austríaco del siglo XIX.','Su apellido da nombre a las tres leyes de la herencia.'],exp:'Gregor Mendel, monje agustino, cruzó miles de plantas de arveja y en 1866 publicó las leyes de la herencia. Su trabajo se redescubrió en 1900.'},
{t:'genetica',k:'mc',q:'Una mutación es…',ops:['un cambio en la secuencia del ADN','una enfermedad contagiosa','una característica aprendida','un tipo de célula'],a:0,p:['Ocurre en el material genético.','Puede ser una base cambiada, agregada o eliminada.'],exp:'Una mutación es un cambio en la secuencia del ADN. Puede ser dañina, neutra o beneficiosa; si ocurre en los gametos, pasa a los hijos. Las mutaciones son la fuente original de la variación genética.'},
{t:'genetica',k:'mc',q:'El síndrome de Down se debe a…',ops:['una copia extra del cromosoma 21','la falta de un gen','una infección','la alimentación de la madre'],a:0,p:['Es una alteración en el número de cromosomas.','Las personas con este síndrome tienen 47 cromosomas.'],exp:'El síndrome de Down se debe a una trisomía 21: tres copias del cromosoma 21 en lugar de dos (47 cromosomas). Ocurre por un error en la separación de los cromosomas durante la meiosis.'},
{t:'genetica',k:'ord',q:'Ordena desde lo más grande hasta lo más pequeño:',ops:['Núcleo','Cromosoma','Gen','Nucleótido'],p:['El ADN está dentro del núcleo, empaquetado.','La unidad más pequeña tiene un azúcar, un fosfato y una base.'],exp:'El núcleo contiene los cromosomas; cada cromosoma es una molécula de ADN con muchos genes; y cada gen está formado por muchos nucleótidos (azúcar + fosfato + base).'},
{t:'genetica',k:'mc',q:'¿Para qué sirve la prueba de ADN en una investigación de paternidad?',ops:['Para comparar el ADN del hijo con el del posible padre','Para saber el grupo de sangre del bebé','Para curar enfermedades','Para saber la edad del padre'],a:0,p:['La mitad del ADN del hijo viene del padre.','Se comparan regiones del ADN que varían mucho entre personas.'],exp:'El hijo recibe la mitad de su ADN de la madre y la otra mitad del padre. Al comparar regiones del ADN muy variables entre el hijo y el posible padre, se confirma o descarta la paternidad con mucha seguridad.'}
]);

/* ───────── EVOLUCIÓN ───────── */
BIO_AJ('evolucion',[
['Según Lamarck, las jirafas tienen el cuello largo','Lamarck creía que usar mucho un órgano lo hace crecer.','Pensaba que lo ganado en vida se pasaba a los hijos.','Lamarck proponía el «uso y desuso» (un órgano que se usa mucho se desarrolla) y la herencia de los caracteres adquiridos: las jirafas estiraban el cuello y sus hijas nacían con el cuello más largo. Hoy sabemos que lo adquirido en vida no se hereda.'],
['Según Darwin, las jirafas tienen el cuello largo','Darwin parte de que los individuos ya son diferentes entre sí.','El ambiente favorece a algunos, que dejan más descendencia.','Para Darwin, en la población ya había jirafas de cuello más largo y más corto (variación). Las de cuello largo alcanzaban más hojas, sobrevivían mejor y dejaban más crías, que heredaban ese rasgo: eso es la selección natural.'],
['Los hijos de un fisicoculturista heredan los músculos','','','Falso. Los músculos ganados con ejercicio son un carácter adquirido: no cambian el ADN de los espermatozoides, así que no se heredan. Esa era la idea equivocada de Lamarck.'],
['¿Quién llegó a la idea de la selección natural al mismo tiempo','Era un naturalista británico que trabajaba en Indonesia.','Darwin y él presentaron sus ideas juntos en 1858.','Alfred Russel Wallace llegó a la idea de la selección natural estudiando animales en el archipiélago malayo. Le escribió a Darwin, y en 1858 presentaron juntos sus trabajos.'],
['¿Qué es lo que evoluciona','Un individuo no cambia sus genes durante su vida.','La evolución se nota al comparar muchas generaciones de un grupo.','Evolucionan las poblaciones a lo largo de las generaciones: cambia la frecuencia de los alelos en el grupo. Un individuo no evoluciona; solo vive, se reproduce o no.'],
['Con troncos oscuros por el hollín, ¿qué polillas','Las aves cazan a las polillas que se ven fácilmente.','Piensa en cuáles se camuflan mejor sobre un tronco negro.','En la Inglaterra industrial, el hollín oscureció los troncos. Las polillas oscuras se camuflaban, las aves se las comían menos y dejaban más crías: aumentaron. Es un ejemplo de selección natural observada.'],
['El brazo humano, la aleta de la ballena y el ala del murciélago','Tienen los mismos huesos, aunque sirven para cosas distintas.','Esa semejanza indica que tienen un antepasado común.','Son órganos homólogos: tienen la misma estructura de huesos (húmero, radio, cúbito, falanges) porque vienen de un antepasado común, aunque hoy cumplen funciones distintas.'],
['El ala de una mariposa y el ala de un ave','Sirven para lo mismo: volar.','Pero su estructura y su origen son totalmente distintos.','Son órganos análogos: cumplen la misma función pero tienen origen y estructura diferentes (el ala del insecto no tiene huesos). Muestran que ambientes parecidos seleccionan soluciones parecidas.'],
['¿Cuál es un órgano vestigial en los humanos','Un órgano vestigial ya no cumple su función original.','Está al final de la columna vertebral.','El coxis es un vestigio de la cola de nuestros antepasados primates: ya no cumple esa función. Los órganos vestigiales son una prueba de la evolución.'],
['¿En qué islas estudió Darwin los pinzones','Están en el océano Pacífico, frente a Ecuador.','Son famosas por sus tortugas gigantes.','Darwin visitó las islas Galápagos en 1835 durante el viaje del Beagle. Vio que cada isla tenía pinzones con picos distintos, adaptados a su alimento: una pista clave para la selección natural.'],
['Los pinzones con pico grueso y fuerte','La forma del pico está relacionada con lo que comen.','Un pico así funciona como un cascanueces.','Los pinzones de pico grueso y fuerte rompen semillas duras; los de pico delgado comen insectos. Cada forma de pico es una adaptación al alimento disponible en su isla.'],
['La serpiente gigante Titanoboa se encontró','Es un hallazgo colombiano.','Se halló en una gran mina de carbón de La Guajira.','Titanoboa cerrejonensis se descubrió en la mina del Cerrejón (La Guajira). Vivió hace unos 60 millones de años, medía unos 13 metros y muestra que el clima de entonces era muy cálido.'],
['Las bacterias pueden volverse resistentes a un antibiótico','','','Verdadero. En una población de bacterias algunas tienen por azar mutaciones que las hacen resistentes. El antibiótico mata a las demás y las resistentes se multiplican: es selección natural, y por eso no hay que usar antibióticos sin necesidad.'],
['¿Con qué especie compartimos el mayor porcentaje de ADN','Es un primate africano.','Es nuestro pariente vivo más cercano.','Compartimos cerca del 98,8 % del ADN con el chimpancé (y con el bonobo). Esto no significa que vengamos del chimpancé, sino que ambos tenemos un antepasado común de hace unos 6 a 7 millones de años.'],
['Ordena estos eventos de la historia de la Tierra','La vida empezó con seres sin núcleo.','Los seres humanos son lo más reciente; los dinosaurios vivieron antes.','Primeras bacterias (≈3800 millones de años) → primeras células eucariotas (≈2000 Ma) → explosión cámbrica de animales (≈540 Ma) → dinosaurios (≈230 Ma) → seres humanos (≈0,3 Ma).'],
['La formación de especies nuevas cuando una población','Una barrera, como una cordillera, separa a la población en dos grupos.','Con el tiempo los dos grupos ya no pueden cruzarse.','Es la especiación: cuando una población queda separada (por ejemplo, por la cordillera de los Andes o un río), cada grupo acumula cambios distintos hasta que ya no pueden reproducirse entre sí y forman especies nuevas.'],
['¿Cómo se llama el libro que publicó Darwin en 1859','El título habla de cómo aparecen las especies.','Empieza por «El origen…».','«El origen de las especies» (1859) explica la evolución por selección natural, con muchas pruebas reunidas por Darwin durante más de 20 años.'],
['La teoría sintética de la evolución une la selección natural con','Darwin no sabía cómo se heredaban los caracteres.','Une las ideas de Darwin con las del monje de las arvejas.','La teoría sintética (neodarwinismo, siglo XX) une la selección natural de Darwin con la genética de Mendel: las mutaciones y la recombinación aportan la variación, y la selección natural actúa sobre ella.'],
['Las especies cambian porque necesitan o desean adaptarse','','','Falso. Los organismos no cambian porque lo necesiten o lo deseen. La variación aparece al azar (mutaciones y recombinación) y el ambiente selecciona a los mejor adaptados, que dejan más descendencia.'],
['¿Qué es un fósil','Se estudian en la paleontología.','Pueden ser huesos, conchas o huellas en las rocas.','Un fósil son restos (huesos, conchas) o huellas de seres que vivieron hace mucho, conservados en rocas sedimentarias. Las capas más profundas suelen ser más antiguas, y así se ordena la historia de la vida.'],
['El cambio al azar de las frecuencias de los alelos','No depende de que un alelo sea mejor o peor.','Pesa más cuando la población es pequeña.','La deriva genética es el cambio al azar de las frecuencias de los alelos: en poblaciones pequeñas, por pura suerte, algunos alelos se pierden y otros se vuelven comunes, sin que importe si son ventajosos.'],
['El maíz se obtuvo a partir del teosinte','No fue la naturaleza la que eligió.','Los agricultores sembraron durante miles de años las semillas de las mejores plantas.','El maíz se obtuvo por selección artificial: durante miles de años los agricultores de México escogieron y sembraron las plantas de teosinte con mazorcas más grandes. El ser humano hizo de «ambiente» que selecciona.'],
['¿En qué continente apareció el Homo sapiens','Allí se encuentran los fósiles humanos más antiguos.','Es el mismo continente de chimpancés y gorilas.','El Homo sapiens apareció en África hace unos 300 000 años; desde allí migró a los otros continentes. A América llegó hace unos 15 000 a 20 000 años.'],
['¿Qué homínido dominó el fuego y salió primero de África','Su nombre significa «hombre erguido».','Es del género Homo, pero anterior al Homo sapiens.','Homo erectus, hace unos 1,9 millones de años, fue el primer homínido que salió de África y llegó a Asia y Europa. Dominó el fuego y fabricaba hachas de piedra.'],
['Los hipopótamos del Magdalena medio son una especie','No son de Colombia: los trajo una persona.','Crecen sin control porque aquí no tienen depredadores.','Son una especie invasora: fueron traídos de África en los años 80 y, al escapar, se reprodujeron sin depredadores. Hoy amenazan a los manatíes, a los peces y a las personas del Magdalena medio.'],
['Ordena las eras geológicas de la más antigua','La más antigua es la más larga y casi no tiene fósiles.','Los dinosaurios vivieron en la era «media» (meso); los mamíferos dominan la más reciente.','Precámbrico (vida sencilla) → Paleozoico («vida antigua», peces y primeras plantas terrestres) → Mesozoico («vida media», dinosaurios) → Cenozoico («vida reciente», mamíferos y humanos).']
]);
BIO_NUEVAS([
{t:'evolucion',k:'mc',q:'¿Qué es una adaptación?',ops:['Una característica heredada que ayuda a sobrevivir y reproducirse en un ambiente','Un cambio que el organismo hace porque lo desea','Una enfermedad','Un hábito aprendido que no se hereda'],a:0,p:['Debe poder pasar a los hijos.','Las espinas del cactus que evitan la pérdida de agua son un ejemplo.'],exp:'Una adaptación es una característica heredada (de forma, de funcionamiento o de comportamiento) que aumenta la supervivencia y la reproducción en un ambiente determinado. Se forma por selección natural a lo largo de muchas generaciones.'},
{t:'evolucion',k:'mc',q:'¿En qué barco viajó Darwin alrededor del mundo?',ops:['HMS Beagle','Titanic','Santa María','Endeavour'],a:0,p:['Viajó entre 1831 y 1836.','El nombre del barco es una raza de perro.'],exp:'Darwin viajó cinco años en el HMS Beagle, una expedición británica alrededor del mundo. Recogió fósiles, plantas y animales, y visitó las Galápagos; esas observaciones lo llevaron a la teoría de la selección natural.'},
{t:'evolucion',k:'vf',q:'Para que la selección natural funcione debe haber variación entre los individuos de la población.',a:true,exp:'Verdadero. Si todos los individuos fueran iguales, el ambiente no tendría nada que «escoger». La selección natural actúa sobre la variación heredable que ya existe en la población.'},
{t:'evolucion',k:'mc',q:'¿Qué prueba de la evolución aporta la embriología?',ops:['Los embriones de vertebrados se parecen mucho en sus primeras etapas','Los fósiles están en capas','Todos los animales comen lo mismo','Las especies nunca cambian'],a:0,p:['Compara embriones de pez, pollo y humano.','Al principio todos tienen hendiduras en el cuello y cola.'],exp:'En sus primeras etapas, los embriones de peces, aves y mamíferos se parecen mucho (tienen hendiduras faríngeas y cola). Esa semejanza sugiere un antepasado común.'},
{t:'evolucion',k:'mc',q:'¿Qué prueba de la evolución es la más precisa hoy en día?',ops:['Comparar el ADN de las especies','Contar las patas','Medir el tamaño','Ver el color'],a:0,p:['Es una prueba molecular.','Entre más se parecen dos secuencias, más cercano es su parentesco.'],exp:'La comparación del ADN y de las proteínas (pruebas moleculares) es la más precisa: entre más parecidas son las secuencias de dos especies, más reciente es su antepasado común.'},
{t:'evolucion',k:'mc',q:'El camuflaje del camaleón y el mimetismo de una mariposa que imita a otra venenosa son ejemplos de:',ops:['adaptaciones producidas por selección natural','caracteres adquiridos','deriva genética','selección artificial'],a:0,p:['Los que se camuflaban mejor sobrevivían más.','Nadie escogió esos rasgos a propósito.'],exp:'Son adaptaciones producidas por selección natural: los individuos que se confundían mejor con el ambiente, o que parecían peligrosos, eran menos cazados y dejaban más crías.'},
{t:'evolucion',k:'mc',q:'¿Qué homínido es famoso por el fósil «Lucy»?',ops:['Australopithecus afarensis','Homo sapiens','Homo erectus','Neandertal'],a:0,p:['Vivió en Etiopía hace unos 3,2 millones de años.','Ya caminaba en dos patas, pero su cerebro era pequeño.'],exp:'Lucy es un fósil de Australopithecus afarensis de hace unos 3,2 millones de años, hallado en Etiopía. Caminaba erguida en dos patas pero tenía un cerebro del tamaño del de un chimpancé.'},
{t:'evolucion',k:'esc',q:'¿Cómo se llama el mecanismo de la evolución propuesto por Darwin?',a:['seleccion natural','la seleccion natural'],p:['Son dos palabras.','La naturaleza «escoge» a los mejor adaptados.'],exp:'La selección natural: los individuos con características que les ayudan a sobrevivir y reproducirse dejan más descendencia, y así esas características se vuelven más comunes en la población.'},
{t:'evolucion',k:'mc',q:'¿Qué causó la extinción de los dinosaurios hace 66 millones de años, según la hipótesis más aceptada?',ops:['El choque de un asteroide','Una glaciación causada por humanos','La falta de oxígeno en el mar','Una enfermedad de los mamíferos'],a:0,p:['Vino del espacio.','Se encontró un cráter enorme en México (Chicxulub).'],exp:'La hipótesis más aceptada es el impacto de un asteroide de unos 10 km en Chicxulub (México). El polvo bloqueó la luz del sol, las plantas murieron y con ellas gran parte de los animales, incluidos los dinosaurios no avianos.'},
{t:'evolucion',k:'vf',q:'Las aves actuales son descendientes de los dinosaurios.',a:true,exp:'Verdadero. Las aves descienden de dinosaurios terópodos con plumas, como muestran fósiles como Archaeopteryx. Por eso los científicos dicen que las aves son dinosaurios vivos.'},
{t:'evolucion',k:'mc',q:'Varias especies de pinzones salieron de un solo antepasado y ocuparon distintos ambientes. Esto es:',ops:['radiación adaptativa','extinción','selección artificial','reproducción asexual'],a:0,p:['Un antepasado «se irradia» en muchas formas.','Cada especie nueva se adaptó a un alimento distinto.'],exp:'Es radiación adaptativa: a partir de un antepasado común aparecen muchas especies adaptadas a distintos nichos. Los pinzones de Galápagos y los colibríes de los Andes son ejemplos.'},
{t:'evolucion',k:'mc',q:'¿Qué papel tienen las mutaciones en la evolución?',ops:['Aportan variación nueva sobre la que actúa la selección','Siempre matan al organismo','Hacen que los seres vivos dejen de cambiar','Solo ocurren en las plantas'],a:0,p:['Sin cambios en el ADN no habría rasgos nuevos.','Son la fuente original de la variación.'],exp:'Las mutaciones son la fuente original de variación genética: crean alelos nuevos. La mayoría son neutras o dañinas, pero algunas resultan ventajosas, y la selección natural las hace más comunes.'},
{t:'evolucion',k:'ord',q:'Ordena los pasos de la selección natural:',ops:['Hay variación entre los individuos','Nacen más individuos de los que pueden sobrevivir','Los mejor adaptados sobreviven y se reproducen más','Sus características se vuelven más comunes en la población'],p:['Todo empieza porque los individuos son diferentes.','El final es un cambio en la población.'],exp:'1) Hay variación heredable; 2) nacen más individuos de los que el ambiente puede mantener (lucha por la existencia); 3) los mejor adaptados sobreviven y se reproducen más; 4) sus rasgos se vuelven más comunes con las generaciones.'},
{t:'evolucion',k:'mc',q:'Los fósiles de La Venta, en el desierto de la Tatacoa (Huila), muestran que hace 13 millones de años allí había:',ops:['una selva húmeda con ríos, primates y cocodrilos','un glaciar','un mar profundo','el mismo desierto de hoy'],a:0,p:['Se encontraron fósiles de monos y de grandes reptiles de agua.','El ambiente era mucho más húmedo que el actual.'],exp:'En La Venta hay fósiles de primates, cocodrilos, tortugas y peces de hace unos 13 millones de años: allí había una selva húmeda con ríos. El ambiente cambió con el levantamiento de los Andes.'},
{t:'evolucion',k:'vf',q:'La evolución es solo una opinión sin pruebas.',a:false,exp:'Falso. En ciencia, una teoría es una explicación apoyada por muchísimas pruebas: fósiles, anatomía comparada, embriología, ADN y evolución observada (como la resistencia a antibióticos). La evolución es una de las teorías mejor comprobadas de la biología.'},
{t:'evolucion',k:'mc',q:'El guácharo de la cueva en Huila se orienta en la oscuridad con sonidos, igual que los murciélagos, aunque no son parientes cercanos. Esto se llama:',ops:['evolución convergente','órganos vestigiales','selección artificial','deriva genética'],a:0,p:['Dos linajes distintos «llegan» a la misma solución.','Es lo mismo que pasa con las alas de aves e insectos.'],exp:'Es evolución convergente: ambientes parecidos (cuevas oscuras) seleccionan soluciones parecidas (ecolocalización) en grupos que no están emparentados. Produce estructuras análogas.'}
]);

/* ───────── ECOSISTEMAS ───────── */
BIO_AJ('ecosistemas',[
['¿Cuál es un factor abiótico','«A» significa sin y «bio» vida.','Busca lo que no está vivo ni lo estuvo.','La temperatura es un factor abiótico: no tiene vida. Otros son la luz, el agua, el suelo, el viento y la humedad. Los factores bióticos son los seres vivos y sus relaciones.'],
['En una cadena trófica, los productores son','Son el primer eslabón de toda cadena.','Fabrican su propio alimento con la energía del Sol.','Los productores son autótrofos (plantas, algas y cianobacterias): fabrican materia orgánica por fotosíntesis. Todos los demás seres de la cadena dependen de ellos.'],
['Los hongos y bacterias que degradan la materia muerta','Cierran el ciclo de la materia.','Devuelven los minerales al suelo.','Son los descomponedores: degradan cadáveres, hojas caídas y excrementos, y devuelven los minerales al suelo para que los usen de nuevo los productores.'],
['Ordena esta cadena trófica del páramo','Empieza por quien hace fotosíntesis.','Termina con el depredador más grande.','Frailejón (productor) → oruga (consumidor primario, herbívoro) → copetón (consumidor secundario, come insectos) → águila (consumidor terciario, depredador).'],
['Si los productores captan 10 000 kcal','En cada eslabón pasa solo una pequeña parte de la energía.','Usa la regla del 10 %: divide entre 10 en cada paso.','Por la regla del 10 %, a cada nivel llega cerca de la décima parte de la energía del anterior: 10 000 kcal (productores) → 1000 (consumidores primarios) → 100 kcal (consumidores secundarios). El resto se pierde como calor.'],
['En las redes tróficas, la flecha va del que come','','','Falso. La flecha va del que es comido hacia el que come: indica hacia dónde fluye la energía (por ejemplo, pasto → vaca).'],
['La relación entre el colibrí y la flor es','Piensa qué gana cada uno.','El colibrí toma el néctar y la flor queda polinizada.','Es mutualismo (+ +): el colibrí obtiene néctar y, al pasar de flor en flor, transporta el polen y ayuda a la planta a reproducirse. Los dos se benefician.'],
['Una bromelia que vive sobre la rama de un árbol','La bromelia gana un lugar con más luz.','Al árbol no le pasa nada: ni gana ni pierde.','Es comensalismo (+ 0): la bromelia (epífita) gana luz al vivir en lo alto, y el árbol no se beneficia ni se perjudica.'],
['Las garrapatas en el ganado son un ejemplo de','Una se beneficia y la otra sale perjudicada.','La garrapata se alimenta de la sangre de la vaca sin matarla.','Es parasitismo (+ −): la garrapata (parásito) se alimenta de la sangre de la vaca (hospedero), que se debilita y puede enfermar.'],
['¿Cómo se llama el proceso por el que las plantas sueltan vapor','Ocurre por los estomas de las hojas.','Es parte del ciclo del agua y se parece a «sudar».','La transpiración es la salida de vapor de agua por los estomas de las hojas. Ayuda a subir el agua desde la raíz y aporta humedad al aire; las selvas producen así gran parte de su propia lluvia.'],
['Ordena el ciclo del agua empezando por el mar','El sol calienta el agua y la convierte en vapor.','Las nubes se forman antes de la lluvia.','Evaporación (el agua del mar pasa a vapor) → condensación (el vapor se enfría y forma nubes) → precipitación (lluvia) → escorrentía (el agua corre por ríos de vuelta al mar).'],
['¿Qué proceso saca CO₂ del aire y lo convierte en materia orgánica','Lo hacen los productores.','Necesita luz, agua y clorofila.','La fotosíntesis toma el CO₂ del aire y, con la energía de la luz, lo convierte en glucosa (materia orgánica). Por eso los bosques son sumideros de carbono.'],
['Quemar petróleo y carbón aumenta','Esos combustibles tienen carbono guardado durante millones de años.','Al quemarse sueltan un gas de efecto invernadero.','Quemar combustibles fósiles libera CO₂ que estaba guardado bajo tierra. Así aumenta el CO₂ del aire y se refuerza el efecto invernadero, que calienta el planeta.'],
['La energía se recicla en el ecosistema igual que la materia','','','Falso. La materia se recicla (los descomponedores devuelven los minerales), pero la energía fluye en una sola dirección: entra como luz y se pierde como calor en cada nivel. Por eso los ecosistemas necesitan la energía del Sol todo el tiempo.'],
['El número máximo de individuos que un ambiente puede mantener','Depende del alimento, el espacio y el agua disponibles.','Es el «techo» de la curva en forma de S.','La capacidad de carga es el número máximo de individuos que el ambiente puede mantener con sus recursos. Al acercarse a ella, la población deja de crecer y se estabiliza (curva en S).'],
['Un ecosistema está formado por','Incluye seres vivos y cosas sin vida.','Es la comunidad más algo más.','Un ecosistema es la comunidad (todas las poblaciones de un lugar) más el ambiente físico (agua, suelo, luz, clima) y todas las relaciones entre ellos.'],
['Todos los individuos de la misma especie que viven en un lugar','Son de la misma especie.','Si fueran de varias especies sería una comunidad.','Es una población: el conjunto de individuos de una misma especie que viven en un lugar al mismo tiempo, por ejemplo, los chigüiros de un estero.'],
['Si desaparecen los peces de un río amazónico','Busca al animal que come casi solo peces.','Es un mamífero rosado de río.','El delfín rosado (bufeo) se alimenta casi solo de peces. Si estos desaparecen (por pesca excesiva o mercurio de la minería), el delfín se queda sin alimento: así se ve cómo está conectada la red trófica.'],
['¿Cómo se llama el depredador que está en la cima','Nadie lo caza.','En Colombia, el jaguar es un ejemplo.','Es el superdepredador (depredador tope), como el jaguar o el águila arpía. Controla las poblaciones de sus presas; si desaparece, el ecosistema se desequilibra.'],
['Una especie que llega a un lugar nuevo y crece sin control','No es nativa de ese lugar.','Allí no tiene depredadores ni enfermedades que la frenen.','Es una especie invasora: llega de otro lugar (muchas veces traída por humanos) y se expande sin control porque no tiene enemigos naturales, desplazando a las especies nativas. El retamo espinoso invade los páramos.'],
['¿Qué organismos convierten el nitrógeno del aire','Viven en bolitas de las raíces del fríjol.','Son bacterias, como Rhizobium.','Las bacterias fijadoras de nitrógeno, como Rhizobium, viven en nódulos de las raíces de las leguminosas (fríjol, arveja) y convierten el N₂ del aire en compuestos que la planta usa para fabricar proteínas.'],
['El exceso de fertilizantes que llega a un lago produce','Los fertilizantes son «comida» para las algas.','Al morir tantas algas, su descomposición gasta el oxígeno del agua.','Es la eutrofización: el exceso de nutrientes (nitrógeno y fósforo) hace crecer muchísimas algas; al morir, las bacterias que las descomponen gastan el oxígeno y los peces mueren.'],
['El nicho ecológico de una especie es','No es solo el lugar donde vive (eso es el hábitat).','Piensa en su «oficio»: qué come, cuándo se activa, quién se la come.','El nicho ecológico es el papel de la especie en el ecosistema: qué come, quién se la come, a qué hora está activa y cómo usa los recursos. El hábitat, en cambio, es solo el lugar donde vive.'],
['Los pelos del frailejón que lo protegen del frío','Es algo de la forma de la planta, no de su comportamiento.','Se ve a simple vista en la estructura del cuerpo.','Es una adaptación morfológica (de forma): los pelos de las hojas del frailejón forman un abrigo que lo protege del frío de la noche y de la radiación del día en el páramo.'],
['La migración de las ballenas jorobadas al Pacífico','No es una forma del cuerpo, sino algo que hacen.','Tiene que ver con el comportamiento del animal.','Es una adaptación conductual (de comportamiento): las ballenas jorobadas viajan miles de kilómetros desde la Antártida hasta las aguas cálidas del Pacífico colombiano para tener a sus crías, entre julio y octubre.']
]);
BIO_NUEVAS([
{t:'ecosistemas',k:'mc',q:'¿Qué es una comunidad biológica?',ops:['Todas las poblaciones de distintas especies que viven en un lugar','Los individuos de una sola especie','El suelo y el clima de un lugar','Un solo organismo'],a:0,p:['Incluye varias especies.','Es la parte viva de un ecosistema.'],exp:'Una comunidad es el conjunto de poblaciones de diferentes especies que viven e interactúan en un mismo lugar. Si se le suma el ambiente físico, se tiene un ecosistema.'},
{t:'ecosistemas',k:'mc',q:'Un ratón que come semillas es un consumidor:',ops:['primario','secundario','terciario','productor'],a:0,p:['Come directamente a un productor.','Es herbívoro.'],exp:'Es consumidor primario porque se alimenta directamente de los productores (semillas). Los consumidores secundarios comen herbívoros, y los terciarios comen a los secundarios.'},
{t:'ecosistemas',k:'mc',q:'La relación entre un jaguar y un chigüiro es de:',ops:['depredación','mutualismo','comensalismo','competencia'],a:0,p:['Uno caza y se come al otro.','Es una relación + −, pero la presa muere.'],exp:'Es depredación: el jaguar (depredador) caza y se come al chigüiro (presa). La depredación controla el tamaño de las poblaciones de presas.'},
{t:'ecosistemas',k:'mc',q:'Dos especies de aves que comen los mismos frutos en un bosque tienen una relación de:',ops:['competencia','mutualismo','parasitismo','comensalismo'],a:0,p:['Las dos necesitan el mismo recurso limitado.','Las dos salen perdiendo (− −).'],exp:'Es competencia (− −): las dos especies usan el mismo recurso limitado, así que cada una deja menos alimento para la otra. Puede ocurrir entre especies distintas o entre individuos de la misma especie.'},
{t:'ecosistemas',k:'vf',q:'En una pirámide de energía, los productores siempre están en la base.',a:true,exp:'Verdadero. Los productores captan la energía del Sol y tienen la mayor cantidad de energía del ecosistema; cada nivel superior tiene menos, porque en cada paso se pierde cerca del 90 % como calor.'},
{t:'ecosistemas',k:'mc',q:'¿Qué es la sucesión ecológica?',ops:['El cambio gradual de una comunidad a lo largo del tiempo','La migración de las aves','La cadena alimenticia','La extinción de una especie'],a:0,p:['Ocurre, por ejemplo, después de un incendio o en una roca desnuda.','Primero llegan los líquenes y musgos; al final, el bosque.'],exp:'La sucesión ecológica es el cambio ordenado de una comunidad con el tiempo: en un lugar sin vida llegan primero las especies pioneras (líquenes, musgos), luego hierbas y arbustos, y finalmente se forma una comunidad estable como un bosque.'},
{t:'ecosistemas',k:'mc',q:'¿Qué parte del ciclo del carbono devuelve CO₂ a la atmósfera desde los seres vivos?',ops:['La respiración','La fotosíntesis','La condensación','La fijación de nitrógeno'],a:0,p:['Lo hacen plantas y animales día y noche.','Es el proceso contrario a la fotosíntesis.'],exp:'La respiración celular de todos los seres vivos (y la descomposición) devuelve CO₂ al aire. La fotosíntesis lo retira. Quemar combustibles fósiles agrega CO₂ extra que el ciclo no alcanza a absorber.'},
{t:'ecosistemas',k:'esc',q:'¿Cómo se llama el lugar físico donde vive una especie?',a:['habitat','el habitat'],p:['Es la «dirección» de la especie; el nicho sería su «oficio».','Empieza por «h».'],exp:'El hábitat es el lugar donde vive una especie (por ejemplo, el páramo para el frailejón). El nicho es el papel que cumple allí.'},
{t:'ecosistemas',k:'mc',q:'Si se eliminan los depredadores de los venados en un bosque, ¿qué pasa primero?',ops:['Aumentan los venados y disminuye la vegetación','Disminuyen los venados','Aumentan los depredadores','No pasa nada'],a:0,p:['Sin quién los cace, ¿qué pasa con los venados?','Muchos venados comen muchas plantas.'],exp:'Sin depredadores, la población de venados crece sin control y consume demasiada vegetación; después, sin alimento, los venados también sufren. Muestra la importancia de los depredadores en el equilibrio.'},
{t:'ecosistemas',k:'ord',q:'Ordena los niveles de organización ecológica, del más pequeño al más grande:',ops:['Individuo','Población','Comunidad','Ecosistema','Biosfera'],p:['Empieza por un solo organismo.','El más grande incluye toda la vida del planeta.'],exp:'Individuo (un organismo) → población (misma especie) → comunidad (varias especies) → ecosistema (comunidad + ambiente físico) → biosfera (todos los ecosistemas de la Tierra).'},
{t:'ecosistemas',k:'mc',q:'Las abejas son muy importantes para los cultivos porque…',ops:['polinizan las flores y así se forman frutos','comen las plagas','fijan nitrógeno','descomponen la materia'],a:0,p:['Visitan las flores para buscar néctar.','Sin ellas, muchas plantas no producirían frutos.'],exp:'Las abejas polinizan: al visitar flores llevan polen de una a otra y permiten que se formen frutos y semillas. Gran parte de los alimentos que comemos depende de los polinizadores, y los insecticidas los están afectando.'},
{t:'ecosistemas',k:'vf',q:'Un ecosistema con más especies suele resistir mejor los cambios que uno con pocas.',a:true,exp:'Verdadero. En un ecosistema biodiverso hay muchas relaciones: si una especie falla, otras cumplen su papel. Los monocultivos, con una sola especie, son más frágiles frente a plagas y cambios del clima.'},
{t:'ecosistemas',k:'mc',q:'Las bacterias de nuestro intestino nos ayudan a digerir y producen vitaminas, y nosotros les damos alimento y refugio. Es un caso de:',ops:['mutualismo','parasitismo','depredación','competencia'],a:0,p:['¿Alguno de los dos sale perjudicado?','Ambos ganan.'],exp:'Es mutualismo (+ +): la microbiota intestinal recibe alimento y un lugar para vivir, y nosotros obtenemos ayuda para digerir, vitaminas como la K y protección contra microbios dañinos.'},
{t:'ecosistemas',k:'mc',q:'¿Qué ecosistema acuático se forma donde el agua dulce de un río se mezcla con el agua salada del mar?',ops:['Estuario','Arrecife','Páramo','Lago'],a:0,p:['El agua allí es «salobre».','Allí suelen crecer los manglares.'],exp:'El estuario es la zona donde un río desemboca en el mar y se mezclan el agua dulce y la salada. Es muy productivo y allí suelen crecer los manglares, que son guardería de muchos peces.'},
{t:'ecosistemas',k:'mc',q:'¿Qué factor abiótico limita más la vida en el desierto de La Guajira?',ops:['La falta de agua','La falta de luz','El frío','La falta de oxígeno'],a:0,p:['Allí casi no llueve.','Los cactus guardan lo que falta en sus tallos.'],exp:'En el desierto el factor limitante es el agua. Por eso sus seres vivos tienen adaptaciones para ahorrarla, como los cactus que la guardan en sus tallos y tienen espinas en lugar de hojas.'},
{t:'ecosistemas',k:'vf',q:'Los descomponedores no son necesarios en un ecosistema.',a:false,exp:'Falso. Sin descomponedores los restos de seres vivos se acumularían y los minerales no volverían al suelo; los productores se quedarían sin nutrientes y el ciclo de la materia se detendría.'}
]);

/* ───────── ECOSISTEMAS DE COLOMBIA ───────── */
BIO_AJ('colombia',[
['¿En qué región está el páramo de Sumapaz','Los páramos están en lo alto de las montañas.','Es la región de las tres cordilleras.','Sumapaz está en la región Andina, en la cordillera Oriental (Bogotá D. C., Cundinamarca, Meta y Huila). Es el páramo más grande del mundo, con unas 333 000 hectáreas.'],
['¿Cuál es la principal importancia de los páramos','Piensa en de dónde sale el agua que llega a las ciudades andinas.','Su suelo y su vegetación funcionan como una esponja.','Los páramos regulan y guardan el agua: sus suelos y plantas (musgos, frailejones) captan la humedad de la neblina y la lluvia y la sueltan poco a poco a los ríos. De ellos depende el agua de Bogotá y de muchas ciudades.'],
['¿Qué región es una de las más lluviosas del mundo','Está entre la cordillera Occidental y el océano.','Allí está el Chocó.','La región Pacífica es una de las más lluviosas del planeta: los vientos húmedos del océano chocan con la cordillera Occidental y descargan la lluvia. En Lloró (Chocó) caen más de 10 000 mm al año.'],
['Caño Cristales, «el río de los cinco colores»','Está en el departamento del Meta.','Está en una serranía aislada entre los Andes, la Orinoquía y la Amazonía.','Caño Cristales está en la serranía de La Macarena (Meta). Su color rojo lo da una planta acuática (Macarenia clavigera) que florece entre junio y noviembre.'],
['¿Dónde vive el delfín rosado','Es un delfín de agua dulce.','Vive en las grandes cuencas del sur y oriente del país.','El delfín rosado (Inia geoffrensis) vive en los ríos de la Amazonía y la Orinoquía. Está amenazado por la pesca, la contaminación con mercurio y las represas.'],
['El bosque seco tropical es muy importante porque','Piensa en cuánto queda de él.','Gran parte se ha convertido en potreros y ciudades.','El bosque seco tropical es uno de los ecosistemas más amenazados de Colombia: queda menos del 8 % del original, porque sus tierras planas y fértiles se convirtieron en potreros, cultivos y ciudades.'],
['Los manglares son importantes porque','Crecen en la orilla del mar, con raíces en zancos.','Allí nacen y crecen muchos peces y camarones.','Los manglares protegen la costa de la erosión y de las olas, filtran el agua, guardan mucho carbono y sus raíces son guardería de peces, camarones y cangrejos.'],
['¿Cuál es el árbol nacional de Colombia','Es la palma más alta del mundo.','Crece en el Valle de Cocora (Quindío) y su tronco es blanco por una cera.','La palma de cera del Quindío (Ceroxylon quindiuense) es el árbol nacional. Puede medir más de 60 metros y está amenazada; el loro orejiamarillo depende de ella.'],
['¿A qué piso térmico pertenece Bogotá','Bogotá está a 2600 metros sobre el nivel del mar.','Entre 2000 y 3000 m de altura la temperatura media está entre 12 y 17 °C.','Bogotá, a 2600 m, está en el piso térmico frío (2000 a 3000 m, entre 12 y 17 °C). Por encima de los 3000 m empieza el páramo.'],
['El café se cultiva sobre todo en el piso térmico','No es ni tan caliente como la costa ni tan frío como Bogotá.','Está entre 1000 y 2000 metros de altura.','El café se cultiva sobre todo en el piso templado (1000 a 2000 m, entre 17 y 24 °C), en las laderas de las cordilleras: el Eje Cafetero es el ejemplo más conocido.'],
['Ordena los pisos térmicos de abajo hacia arriba','Al subir la montaña, la temperatura baja.','El más alto tiene nieve.','Cálido (0-1000 m) → templado (1000-2000 m) → frío (2000-3000 m) → páramo (3000-4000 m) → nival (más de 4700 m, con nieve). La temperatura baja unos 6 °C por cada 1000 m.'],
['¿Qué región ocupa cerca del 42 % del territorio','Es la región más grande y menos poblada.','Es selva húmeda en el sur del país.','La Amazonía ocupa cerca del 42 % del territorio colombiano. Es selva húmeda tropical con enorme biodiversidad y territorio de muchos pueblos indígenas.'],
['La Reserva de Biosfera Seaflower','Tiene arrecifes de coral.','Está en el mar Caribe, lejos del continente.','Seaflower está en la región Insular: el archipiélago de San Andrés, Providencia y Santa Catalina. Tiene uno de los arrecifes de coral más grandes del Caribe.'],
['La Sierra Nevada de Santa Marta es la montaña junto al mar','','','Verdadero. La Sierra Nevada llega a 5775 m (picos Cristóbal Colón y Simón Bolívar) a solo 42 km de la costa del Caribe, y en ella están todos los pisos térmicos, de la playa a la nieve.'],
['El chigüiro y las sabanas inundables son típicos de','Es la región de los Llanos Orientales.','Sus ríos llevan las aguas al río Orinoco.','La Orinoquía (Llanos Orientales) tiene sabanas que se inundan en la época de lluvias. Allí viven el chigüiro (el roedor más grande del mundo), el caimán del Orinoco y la anaconda.'],
['¿Cuál es la principal amenaza de la Amazonía colombiana','Se tumba la selva para otro uso del suelo.','Ese uso tiene que ver con potreros para vacas.','La principal amenaza es la deforestación, sobre todo para convertir la selva en potreros (praderización y acaparamiento de tierras), además de cultivos ilícitos, minería ilegal y carreteras.'],
['¿Cómo se llama la planta típica del páramo','Tiene hojas peludas y plateadas.','Su nombre recuerda a los monjes («frailes»).','El frailejón (género Espeletia) es la planta típica del páramo: sus hojas peludas lo protegen del frío y captan la humedad de la niebla. Crece apenas cerca de un centímetro al año.'],
['Chiribiquete, el parque nacional más grande del país','Está en la Amazonía, entre Caquetá y Guaviare.','Tiene montañas de paredes verticales y miles de dibujos antiguos.','Chiribiquete es famoso por sus tepuyes (mesetas de paredes verticales) y por más de 75 000 pinturas rupestres. Es Patrimonio Mixto de la Humanidad (natural y cultural) desde 2018.'],
['El desierto de la Tatacoa es en realidad un bosque seco','','','Verdadero. La Tatacoa (Huila) es un bosque seco tropical muy erosionado, con cactus y pocas lluvias. Además tiene muchos fósiles de La Venta, de hace unos 13 millones de años.'],
['¿Por qué Colombia tiene tantos ecosistemas diferentes','Son tres razones geográficas juntas.','Piensa en la ubicación del país, sus costas y sus montañas.','Colombia es megadiversa porque está en el trópico (mucha energía solar todo el año), tiene costas en dos océanos (Pacífico y Caribe) y las tres cordilleras de los Andes crean todos los pisos térmicos.'],
['En la escala de la UICN, ¿cuál es la categoría de mayor riesgo','Busca la categoría justo antes de «extinta en estado silvestre».','Es peor que «en peligro» y que «vulnerable».','«En peligro crítico» (CR) es el mayor riesgo para una especie que todavía vive libre. El orden es: preocupación menor → casi amenazada → vulnerable → en peligro → en peligro crítico → extinta en estado silvestre → extinta.'],
['¿Qué especie de Colombia está en peligro crítico y se cría en cautiverio','Es un reptil grande de los ríos de los Llanos.','Lo cazaron por su piel en el siglo XX.','El caimán del Orinoco (Crocodylus intermedius) está en peligro crítico por la cacería de su piel. La Estación Roberto Franco (Villavicencio) y otros programas lo crían para liberarlo en los ríos.'],
['Un corredor biológico sirve para','Piensa en un «puente» entre dos parches de bosque.','Sin él, las poblaciones quedan encerradas y se cruzan entre parientes.','Un corredor biológico conecta áreas de bosque separadas para que los animales y las plantas puedan moverse entre ellas. Así las poblaciones no quedan aisladas y se mantiene la variabilidad genética.'],
['Comprar un mico o una guacamaya como mascota','','','Falso. Comprar fauna silvestre alimenta el tráfico ilegal: por cada animal vendido mueren varios en la captura y el transporte. Además, es un delito en Colombia.']
]);
BIO_NUEVAS([
{t:'colombia',k:'mc',q:'¿Cuántas regiones naturales tiene Colombia?',ops:['Seis','Cuatro','Ocho','Tres'],a:0,p:['Son Caribe, Pacífica, Andina, Orinoquía, Amazonía y…','La última incluye las islas.'],exp:'Colombia tiene seis regiones naturales: Caribe, Pacífica, Andina, Orinoquía, Amazonía e Insular (San Andrés, Providencia, Malpelo y Gorgona).'},
{t:'colombia',k:'mc',q:'¿Qué región tiene la mayor parte de la población colombiana?',ops:['Andina','Amazonía','Orinoquía','Insular'],a:0,p:['Allí están Bogotá, Medellín y Cali.','Es la región de las montañas.'],exp:'La región Andina concentra cerca del 70 % de la población. Su clima variado y sus suelos fértiles favorecieron las ciudades y la agricultura, pero también la pérdida de bosques andinos.'},
{t:'colombia',k:'mc',q:'La isla de Gorgona, antigua cárcel y hoy Parque Nacional, está en el océano:',ops:['Pacífico','Atlántico (mar Caribe)','Índico','Ártico'],a:0,p:['Está frente a la costa de Cauca.','Es el mismo océano al que llegan las ballenas jorobadas.'],exp:'Gorgona está en el océano Pacífico, frente al Cauca. Fue cárcel hasta 1984 y hoy es Parque Nacional Natural, con arrecifes, ballenas jorobadas y especies endémicas.'},
{t:'colombia',k:'mc',q:'¿Qué ave es el símbolo nacional de Colombia?',ops:['El cóndor de los Andes','La guacamaya','El colibrí','El tucán'],a:0,p:['Está en el escudo nacional.','Es una de las aves voladoras más grandes del mundo.'],exp:'El cóndor de los Andes es el ave nacional y aparece en el escudo. Es un carroñero de alta montaña que está en peligro en Colombia, donde quedan muy pocos individuos.'},
{t:'colombia',k:'vf',q:'La Ciénaga Grande de Santa Marta es el complejo de lagunas costeras más grande de Colombia.',a:true,exp:'Verdadero. La Ciénaga Grande de Santa Marta es el mayor complejo lagunar del país, con manglares y gran pesca. Está amenazada por la desviación del agua dulce, las carreteras que cortan el intercambio con el mar y la contaminación.'},
{t:'colombia',k:'mc',q:'¿Qué ecosistema de la región Andina está siempre cubierto de neblina y tiene muchas orquídeas y musgos?',ops:['El bosque de niebla','El desierto','La sabana','El manglar'],a:0,p:['Se encuentra entre los 2000 y 3000 m de altura.','La humedad viene de las nubes que lo atraviesan.'],exp:'El bosque de niebla (bosque altoandino) está casi siempre entre las nubes: los árboles cubiertos de musgos, bromelias y orquídeas captan el agua de la neblina. Es clave para el agua y uno de los más deforestados.'},
{t:'colombia',k:'mc',q:'¿Por qué se dice que Colombia es un país «megadiverso»?',ops:['Porque tiene una enorme cantidad de especies en su territorio','Porque tiene mucha población','Porque tiene muchas ciudades','Porque exporta café'],a:0,p:['Es una de las 17 naciones con más biodiversidad del mundo.','Tiene cerca del 10 % de las especies del planeta.'],exp:'Colombia es uno de los 17 países megadiversos: con menos del 1 % de la superficie terrestre, tiene cerca del 10 % de las especies conocidas. Es primero en aves y orquídeas y segundo en plantas, anfibios y peces de agua dulce.'},
{t:'colombia',k:'esc',q:'¿Cómo se llama el roedor más grande del mundo, típico de los Llanos Orientales?',a:['chiguiro','el chiguiro','capibara','chigüiro'],p:['Vive en las sabanas inundables y nada muy bien.','También se le llama capibara.'],exp:'El chigüiro o capibara (Hydrochoerus hydrochaeris) es el roedor más grande del mundo. Vive en grupos cerca del agua en la Orinoquía y es presa del jaguar y la anaconda.'},
{t:'colombia',k:'mc',q:'El oso de anteojos vive principalmente en:',ops:['los bosques andinos y páramos','el desierto de La Guajira','los arrecifes de coral','las sabanas de los Llanos'],a:0,p:['Es el único oso de Sudamérica.','Vive en las montañas, entre el bosque de niebla y el páramo.'],exp:'El oso de anteojos (Tremarctos ornatus) vive en bosques andinos y páramos. Come sobre todo plantas (bromelias, frutos) y dispersa semillas; está amenazado por la pérdida de su hábitat.'},
{t:'colombia',k:'mc',q:'¿Qué región natural incluye la península de La Guajira, la Sierra Nevada y la Mojana?',ops:['Caribe','Pacífica','Amazonía','Insular'],a:0,p:['Está al norte del país.','Sus costas dan al mar de las Antillas.'],exp:'La región Caribe, al norte, incluye el desierto de La Guajira, la Sierra Nevada de Santa Marta, la Mojana, ciénagas, manglares y el bosque seco. Es muy variada en ecosistemas.'},
{t:'colombia',k:'ord',q:'Ordena estas regiones de la que ocupa más territorio a la que ocupa menos:',ops:['Amazonía','Orinoquía','Andina','Caribe','Pacífica','Insular'],p:['La más grande es la selva del sur.','La más pequeña son las islas.'],exp:'Amazonía (≈42 %) → Orinoquía (≈22 %) → Andina (≈20 %) → Caribe (≈11 %) → Pacífica (≈6 %) → Insular (la más pequeña). Los porcentajes son aproximados.'},
{t:'colombia',k:'mc',q:'Las ballenas jorobadas llegan cada año a Bahía Solano y Nuquí para:',ops:['tener a sus crías en aguas cálidas','comer krill','escapar de los tiburones','hibernar'],a:0,p:['Vienen desde la Antártida en julio.','El agua cálida es mejor para los recién nacidos.'],exp:'Entre julio y octubre las ballenas jorobadas migran desde la Antártida al Pacífico colombiano para aparearse y tener a sus crías en aguas cálidas y tranquilas. Es un atractivo de turismo responsable en el Chocó.'},
{t:'colombia',k:'vf',q:'La Amazonía colombiana produce gran parte de su propia lluvia gracias a la transpiración de sus árboles.',a:true,exp:'Verdadero. Los árboles de la selva sueltan enormes cantidades de vapor por transpiración, que forma nubes y vuelve a caer como lluvia («ríos voladores»). Si se tala la selva, llueve menos y puede convertirse en sabana.'},
{t:'colombia',k:'mc',q:'¿Qué actividad ilegal contamina con mercurio los ríos del Chocó y la Amazonía?',ops:['La minería ilegal de oro','La pesca artesanal','El turismo','La siembra de cacao'],a:0,p:['El mercurio se usa para separar un metal precioso.','Se hace con dragas en los ríos.'],exp:'La minería ilegal de oro usa mercurio para separar el oro y lo vierte a los ríos. El mercurio se acumula en los peces y llega a las personas que los comen, causando daños graves en el sistema nervioso.'},
{t:'colombia',k:'mc',q:'¿Qué hacen los Parques Nacionales Naturales de Colombia?',ops:['Protegen ecosistemas y especies en áreas donde está prohibido explotarlos','Venden madera','Crían ganado','Construyen ciudades'],a:0,p:['Son áreas protegidas por la ley.','Hay 60 o más en todo el país.'],exp:'Los Parques Nacionales Naturales son áreas protegidas por el Estado donde se conservan ecosistemas, especies y culturas. Allí no se permite la minería, la tala ni la ganadería. Colombia tiene más de 60.'},
{t:'colombia',k:'mc',q:'El caracol pala, la tortuga carey y el pez loro se encuentran en:',ops:['los arrecifes coralinos del Caribe y San Andrés','los páramos','el desierto de La Guajira','las sabanas inundables'],a:0,p:['Son animales marinos.','Viven cerca de los corales.'],exp:'Son especies de los arrecifes coralinos del Caribe colombiano, sobre todo de San Andrés y Providencia. La tortuga carey está en peligro crítico; el pez loro ayuda a mantener limpios los corales.'},
{t:'colombia',k:'mc',q:'El macizo colombiano, donde nacen los ríos Magdalena, Cauca, Patía y Caquetá, se conoce como:',ops:['la estrella fluvial de Colombia','el desierto de la Tatacoa','la Orinoquía','el valle de Cocora'],a:0,p:['Está en el sur del país, en Cauca y Huila.','De allí salen ríos hacia varios lados, como los brazos de una estrella.'],exp:'El Macizo Colombiano es la «estrella fluvial»: allí nacen los ríos Magdalena, Cauca, Patía y Caquetá, que llevan agua a gran parte del país. Por eso conservar sus páramos es vital.'}
]);

/* ───────── AMBIENTE Y CAMBIO CLIMÁTICO ───────── */
BIO_AJ('ambiente',[
['¿Cuál de estos es un gas de efecto invernadero','Retiene el calor en la atmósfera.','Es el gas que sale al quemar combustibles y que exhalamos.','El dióxido de carbono (CO₂) es el principal gas de efecto invernadero emitido por los humanos. También lo son el metano (CH₄), el óxido nitroso (N₂O) y el vapor de agua. El oxígeno y el nitrógeno no lo son.'],
['Sin ningún efecto invernadero la Tierra sería mucho más fría','','','Verdadero. El efecto invernadero natural mantiene el planeta en unos 15 °C de promedio; sin él estaría a unos −18 °C. El problema actual es que los humanos lo estamos aumentando.'],
['¿Cuál es la principal fuente de gases de efecto invernadero en Colombia','En Colombia es diferente al resto del mundo.','Tiene que ver con tumbar bosques y con las vacas.','En Colombia la mayor fuente de emisiones es la agricultura, la silvicultura y el cambio de uso del suelo: la deforestación (sobre todo en la Amazonía) y la ganadería. En el mundo, la principal fuente es quemar combustibles fósiles.'],
['¿Qué gas producen las vacas al digerir el pasto','Lo producen bacterias del estómago de la vaca.','Es el mismo gas que sale de los rellenos de basura.','Las vacas producen metano (CH₄) cuando las bacterias de su estómago fermentan el pasto. El metano calienta unas 80 veces más que el CO₂ en sus primeros 20 años en la atmósfera.'],
['Actualmente el CO₂ de la atmósfera está en aproximadamente','Antes de la Revolución Industrial había unas 280 ppm.','Ha subido mucho más de un 40 %.','Hoy el CO₂ supera las 420 partes por millón (ppm), frente a unas 280 ppm antes de la industria. Es el nivel más alto en al menos 800 000 años, según el hielo de la Antártida.'],
['Durante El Niño, en Colombia suele haber','El Pacífico se calienta y en Colombia llueve menos.','Bajan los niveles de los embalses.','Con El Niño llueve menos en gran parte de Colombia: hay sequías, incendios forestales, bajan los embalses (riesgo de racionamiento de energía) y sube el precio de los alimentos.'],
['Durante La Niña, en Colombia suele haber','Es lo contrario de El Niño.','Llueve mucho más de lo normal.','Con La Niña llueve más de lo normal: hay inundaciones, crecientes y deslizamientos. La Niña de 2010-2011 afectó a más de tres millones de personas en Colombia.'],
['¿Por qué el blanqueamiento de los corales es un problema','El color de los corales viene de unas algas que viven dentro de ellos.','Cuando el agua se calienta, el coral expulsa esas algas.','Los corales viven en mutualismo con algas que les dan alimento y color. Si el agua se calienta, el coral las expulsa, se pone blanco y, si el calor sigue, muere de hambre; con él se pierde el hogar de miles de especies.'],
['El mar se acidifica porque','El océano absorbe parte del gas que emitimos.','Ese gas, disuelto en agua, forma un ácido.','El océano absorbe cerca de un cuarto del CO₂ que emitimos. Al disolverse forma ácido carbónico y el agua se vuelve más ácida, lo que dificulta a corales, moluscos y cangrejos formar sus conchas y esqueletos de carbonato de calcio.'],
['¿Cuál es una fuente de energía renovable','Renovable es la que no se agota.','La Guajira tiene mucho de ella.','El viento (energía eólica) es renovable, igual que el sol, el agua de los ríos y el calor de la Tierra. El petróleo, el carbón y el gas son fósiles: se agotan y emiten CO₂.'],
['La mayor parte de la electricidad de Colombia viene de','Colombia tiene muchos ríos con mucha agua.','Se usa la fuerza del agua en represas.','Cerca de dos tercios de la electricidad de Colombia viene de hidroeléctricas, que usan la fuerza del agua de los ríos. Por eso, en épocas de El Niño, la falta de lluvia puede causar racionamientos.'],
['Detener la deforestación para reducir las emisiones','Hay dos tipos de acciones frente al cambio climático.','Esta ataca la causa del problema.','Es mitigación: reducir las emisiones o aumentar la captura de gases de efecto invernadero, es decir, atacar la causa del cambio climático. Proteger los bosques, usar energías limpias y ahorrar energía son acciones de mitigación.'],
['Sembrar cultivos resistentes a la sequía','No reduce las emisiones.','Prepara a las personas para el clima que viene.','Es adaptación: ajustarse a los efectos del cambio climático que ya ocurren o vendrán, como sequías e inundaciones. Ejemplos: semillas resistentes, recoger agua lluvia, no construir en zonas inundables.'],
['¿Qué está pasando con los glaciares de Colombia','Piensa en el efecto del calentamiento en la nieve de las montañas.','Ya desaparecieron varios en el último siglo.','Los glaciares colombianos se están derritiendo rápidamente: se ha perdido cerca del 90 % de su área desde el siglo XIX y solo quedan seis nevados con glaciar (como el Nevado del Ruiz y la Sierra Nevada del Cocuy).'],
['¿Qué acción reduce tu huella de carbono','Busca la opción que no queme combustible.','Además, es buena para la salud.','Caminar o usar la bicicleta no quema combustibles fósiles, así que no emite CO₂. Usar el carro en trayectos cortos, comer mucha carne de res y dejar las luces encendidas aumentan la huella de carbono.'],
['El Niño y La Niña los causa directamente el ser humano','','','Falso. El Niño y La Niña son fenómenos naturales del océano Pacífico que existen desde hace miles de años. Lo que preocupa es que el calentamiento global puede hacerlos más intensos.'],
['Los rellenos sanitarios producen metano porque','Hay algo que se pudre allí.','La basura queda enterrada, sin aire.','La basura orgánica (restos de comida) enterrada en el relleno se descompone sin oxígeno, y las bacterias producen metano. Separar y compostar los residuos orgánicos reduce ese metano y produce abono.'],
['¿Cómo se llama la cantidad de gases de efecto invernadero que producen las actividades de una persona','Se mide en toneladas de CO₂.','Es como la «marca» que dejas al pisar.','La huella de carbono es la cantidad total de gases de efecto invernadero que producen las actividades de una persona, empresa o país, expresada en toneladas de CO₂ equivalente.'],
['¿Qué comunidades son más vulnerables al cambio climático','Son las que tienen menos recursos para recuperarse.','Su sustento depende de la lluvia, la pesca o la cosecha.','Las comunidades rurales, pobres y que dependen directamente de la naturaleza (campesinos, pescadores, pueblos indígenas) son las más vulnerables: una sequía o una inundación les quita el sustento y tienen menos recursos para recuperarse.'],
['Ordena la cadena de causas','Empieza con una acción humana en la selva.','El último eslabón es el calentamiento del planeta.','Se tala la selva → el carbono de los árboles sale como CO₂ a la atmósfera → aumenta el efecto invernadero → sube la temperatura del planeta. Por eso proteger la Amazonía es una acción contra el cambio climático.']
]);
BIO_NUEVAS([
{t:'ambiente',k:'mc',q:'¿Qué es el efecto invernadero?',ops:['La retención del calor por algunos gases de la atmósfera','Un agujero en la capa de ozono','La lluvia ácida','El calor que sale de los volcanes'],a:0,p:['Se parece a lo que pasa dentro de un carro cerrado al sol.','Unos gases dejan entrar la luz pero no dejan salir todo el calor.'],exp:'El efecto invernadero es el calentamiento que producen algunos gases (CO₂, metano, vapor de agua): dejan pasar la luz del Sol, pero retienen parte del calor que la Tierra emite. Es natural, pero los humanos lo estamos aumentando.'},
{t:'ambiente',k:'mc',q:'¿Qué diferencia hay entre el tiempo atmosférico y el clima?',ops:['El tiempo es el estado de un día; el clima es el promedio de muchos años','Son lo mismo','El clima cambia cada hora','El tiempo solo existe en las ciudades'],a:0,p:['Uno cambia de un día a otro; el otro se mide en décadas.','El clima se calcula con al menos 30 años de datos.'],exp:'El tiempo atmosférico es el estado de la atmósfera en un momento (hoy llueve). El clima es el promedio de esas condiciones durante 30 años o más. Un día frío no desmiente el calentamiento global.'},
{t:'ambiente',k:'vf',q:'El agujero de la capa de ozono y el cambio climático son el mismo problema.',a:false,exp:'Falso. El agujero de ozono lo causaron gases como los CFC de los aerosoles viejos, y deja pasar más radiación ultravioleta; se está recuperando gracias al Protocolo de Montreal. El cambio climático lo causan los gases de efecto invernadero.'},
{t:'ambiente',k:'mc',q:'¿Qué acuerdo internacional de 2015 busca que el calentamiento no supere 1,5 a 2 °C?',ops:['El Acuerdo de París','El Protocolo de Montreal','La Carta de la ONU','El Tratado de Tordesillas'],a:0,p:['Se firmó en una capital europea.','Casi todos los países del mundo se comprometieron a reducir emisiones.'],exp:'El Acuerdo de París (2015) compromete a casi todos los países a reducir sus emisiones para que el calentamiento global se mantenga muy por debajo de 2 °C, idealmente en 1,5 °C. Colombia lo ratificó.'},
{t:'ambiente',k:'mc',q:'¿Cuál de estas acciones reduce más los residuos?',ops:['Reducir: comprar solo lo necesario y evitar desechables','Botar todo en la misma bolsa','Quemar la basura','Enterrar los plásticos'],a:0,p:['De las tres R, es la primera y la más importante.','El mejor residuo es el que no se produce.'],exp:'De las tres R (reducir, reutilizar, reciclar), reducir es la más efectiva: si no se compra un desechable, no hay que fabricarlo ni botarlo. Reciclar ayuda, pero gasta energía.'},
{t:'ambiente',k:'mc',q:'Los plásticos de un solo uso son un problema porque…',ops:['tardan cientos de años en degradarse y llegan al mar','se descomponen en una semana','son comida para los peces','producen oxígeno'],a:0,p:['Piensa cuánto dura una bolsa enterrada.','Se rompen en pedacitos (microplásticos) que entran a las cadenas tróficas.'],exp:'Los plásticos de un solo uso tardan de 100 a 500 años en degradarse. Muchos llegan a los ríos y al mar, donde los animales se enredan o se los comen, y se rompen en microplásticos que entran a las cadenas tróficas.'},
{t:'ambiente',k:'mc',q:'El compost es…',ops:['abono hecho con residuos orgánicos descompuestos','un tipo de plástico','un gas de efecto invernadero','un combustible fósil'],a:0,p:['Se hace con cáscaras y restos de comida.','Los descomponedores hacen el trabajo.'],exp:'El compost es abono que se obtiene dejando que los descomponedores degraden los residuos orgánicos (cáscaras, hojas) con aire. Así se evita el metano de los rellenos y se devuelven nutrientes al suelo.'},
{t:'ambiente',k:'esc',q:'¿Cómo se llama la pérdida de la cobertura de bosque por tala o quema?',a:['deforestacion','la deforestacion'],p:['Es la principal amenaza de la Amazonía.','Viene de «forestal» con el prefijo «de».'],exp:'La deforestación es la pérdida de bosques por tala, quema o cambio de uso del suelo. En Colombia es la principal fuente de emisiones y la mayor causa de pérdida de biodiversidad.'},
{t:'ambiente',k:'mc',q:'¿Por qué el aumento del nivel del mar es un riesgo para ciudades como Cartagena?',ops:['Porque puede inundar las zonas costeras bajas','Porque el agua se vuelve dulce','Porque aumenta la nieve','Porque baja la temperatura'],a:0,p:['El hielo de los polos se derrite y el agua se expande al calentarse.','Cartagena está casi al nivel del mar.'],exp:'El nivel del mar sube porque se derrite el hielo de glaciares y polos y porque el agua se expande al calentarse. Ciudades costeras bajas como Cartagena, Tumaco o San Andrés pueden sufrir inundaciones y erosión.'},
{t:'ambiente',k:'mc',q:'¿Qué gas, además del CO₂, sale en grandes cantidades al quemar bosques?',ops:['Humo con monóxido de carbono y partículas','Oxígeno puro','Helio','Nitrógeno puro'],a:0,p:['Es lo que vuelve gris el cielo en temporada de incendios.','Afecta la respiración de las personas.'],exp:'Los incendios liberan CO₂ y además humo con monóxido de carbono y partículas finas que contaminan el aire, enferman las vías respiratorias y viajan cientos de kilómetros.'},
{t:'ambiente',k:'vf',q:'Los bosques y los páramos ayudan a frenar el cambio climático porque guardan carbono.',a:true,exp:'Verdadero. Los árboles y los suelos de páramos y turberas guardan enormes cantidades de carbono. Conservarlos evita que ese carbono salga como CO₂, por eso protegerlos es una acción de mitigación.'},
{t:'ambiente',k:'mc',q:'¿Cuál de estos es un efecto del cambio climático en la salud en Colombia?',ops:['El dengue llega a zonas más altas y frías que antes','Desaparecen todos los mosquitos','Ya nadie se enferma de gripa','Baja la temperatura de las ciudades'],a:0,p:['El mosquito que transmite el dengue necesita calor.','Con el calentamiento, el calor sube por las montañas.'],exp:'Al subir la temperatura, el mosquito Aedes aegypti, que transmite el dengue, el zika y el chikunguña, puede vivir en zonas más altas que antes, y la enfermedad llega a municipios donde no se conocía.'},
{t:'ambiente',k:'mc',q:'¿Qué es la economía circular?',ops:['Diseñar productos para reutilizar y reciclar sus materiales en vez de botarlos','Vender productos en círculo','Comprar más y botar más','Usar solo energía de carbón'],a:0,p:['Lo contrario de «usar y botar».','Los residuos de un proceso son la materia prima de otro.'],exp:'La economía circular busca que los materiales vuelvan a usarse una y otra vez: productos duraderos, reparables, reutilizables y reciclables, de modo que los residuos se conviertan en materia prima. Es lo contrario de la economía lineal de «extraer, usar y botar».'},
{t:'ambiente',k:'ord',q:'Ordena el camino de una botella plástica que se recicla:',ops:['Se separa en la fuente','La recoge el reciclador','Se clasifica y se lava','Se tritura y se funde','Se fabrica un producto nuevo'],p:['Todo empieza en tu casa.','El final es un objeto nuevo hecho con ese plástico.'],exp:'Separar en la fuente (en casa) → la recoge el reciclador de oficio → se clasifica y se lava → se tritura y se funde → se fabrica un producto nuevo. Si no se separa en casa, casi todo termina en el relleno.'},
{t:'ambiente',k:'mc',q:'¿Por qué es mejor comprar alimentos producidos cerca de donde vives?',ops:['Porque necesitan menos transporte y emiten menos CO₂','Porque siempre son más baratos','Porque no tienen nutrientes','Porque traen más empaques'],a:0,p:['Piensa en los camiones y aviones que los traen.','También ayuda a los campesinos de tu región.'],exp:'Los alimentos locales recorren menos distancia, así que su transporte quema menos combustible y emite menos CO₂. Además apoyan a los campesinos de la región y suelen llegar más frescos.'},
{t:'ambiente',k:'vf',q:'La temperatura promedio del planeta ya subió cerca de 1,2 °C desde la época preindustrial.',a:true,exp:'Verdadero. Desde finales del siglo XIX la temperatura media del planeta ha subido cerca de 1,2 °C, sobre todo por las emisiones humanas. Parece poco, pero ya produce más olas de calor, lluvias extremas y deshielo.'},
{t:'ambiente',k:'mc',q:'¿Qué hace un sumidero de carbono?',ops:['Absorbe y guarda más CO₂ del que emite','Produce petróleo','Libera metano','Destruye la capa de ozono'],a:0,p:['Funciona como una «esponja» de CO₂.','Los océanos, los bosques y los suelos lo son.'],exp:'Un sumidero de carbono absorbe más CO₂ del que libera y lo guarda por mucho tiempo: los bosques, los océanos, los manglares y los suelos de los páramos son sumideros. Deforestarlos los convierte en fuentes de CO₂.'},
{t:'ambiente',k:'mc',q:'En tu colegio quieren ahorrar energía. ¿Cuál es la mejor medida?',ops:['Apagar luces y equipos que no se usan y aprovechar la luz del día','Dejar los computadores encendidos toda la noche','Cerrar las ventanas y prender todas las luces','Usar más aire acondicionado'],a:0,p:['La energía más limpia es la que no se gasta.','La luz del sol es gratis.'],exp:'Apagar lo que no se usa y aprovechar la luz natural reduce el consumo de electricidad sin costo. En Colombia también ayuda a cuidar los embalses en épocas de El Niño.'},
{t:'ambiente',k:'mc',q:'Un campesino recoge agua lluvia en tanques para regar en la época seca. Esa es una medida de:',ops:['adaptación','mitigación','contaminación','deforestación'],a:0,p:['No reduce las emisiones de gases.','Le ayuda a enfrentar las sequías que vienen.'],exp:'Es una medida de adaptación: prepara al campesino para enfrentar las sequías, que se vuelven más frecuentes con el cambio climático. La mitigación, en cambio, reduciría las emisiones.'},
{t:'ambiente',k:'esc',q:'¿Cómo se llama la energía que se obtiene de la luz del Sol con paneles?',a:['solar','energia solar','fotovoltaica','energia fotovoltaica'],p:['Los paneles convierten la luz en electricidad.','Su nombre viene de «Sol».'],exp:'La energía solar (fotovoltaica) convierte la luz del Sol en electricidad con paneles. Es renovable, no emite CO₂ al funcionar y es muy útil en zonas rurales sin red eléctrica.'},
{t:'ambiente',k:'mc',q:'¿Por qué la ganadería extensiva en la Amazonía empeora el cambio climático de dos formas?',ops:['Se tala el bosque para potreros y las vacas emiten metano','Las vacas producen oxígeno','Los potreros guardan más carbono que la selva','Las vacas comen CO₂'],a:0,p:['Piensa en qué había antes del potrero.','Y en el gas que producen las vacas al digerir.'],exp:'La ganadería extensiva empeora el cambio climático porque se tala y quema la selva para hacer potreros (sale el CO₂ guardado en los árboles) y porque las vacas emiten metano al digerir el pasto.'}
]);

/* ───────── REPRODUCCIÓN ───────── */
BIO_AJ('reproduccion',[
['¿Qué ventaja tiene la reproducción asexual','Piensa en cuántos progenitores hacen falta.','No hay que buscar pareja ni formar gametos.','La reproducción asexual es rápida y solo necesita un progenitor: no hay que buscar pareja ni formar gametos. Su desventaja es que los hijos son clones, sin variabilidad genética, así que un cambio del ambiente o una enfermedad puede afectarlos a todos por igual.'],
['Las levaduras y las hidras se reproducen por','Al progenitor le crece una pequeña protuberancia.','Esa «yema» crece y luego se separa.','Es gemación: al organismo le sale una yema (un brote) que crece, se separa y forma un individuo nuevo idéntico. Ocurre en levaduras, hidras, esponjas y corales.'],
['Los zánganos de las abejas nacen de óvulos sin fecundar','Ningún espermatozoide participa.','Viene del griego «virgen» y «origen».','Es partenogénesis: un óvulo se desarrolla sin ser fecundado. En las abejas, los óvulos sin fecundar dan zánganos (machos) y los fecundados dan obreras y reinas.'],
['¿Qué grupo de plantas forma semillas desnudas','Sus semillas no quedan dentro de un fruto.','«Gimnos» significa desnudo.','Las gimnospermas (pinos, cipreses, el romerón colombiano) forman semillas desnudas en conos o piñas, sin un fruto que las envuelva. Las angiospermas, en cambio, tienen flores y frutos.'],
['Los helechos producen esporas en unos puntos cafés','Se ven por el envés (la parte de abajo) de las hojas.','Su nombre empieza por «s».','Los soros son grupos de esporangios bajo las hojas de los helechos; allí se forman las esporas, que el viento dispersa. Los helechos no tienen flores ni semillas.'],
['¿Cuál es la parte de la flor que produce el polen','Es parte del órgano masculino de la flor (el estambre).','Está en la punta del filamento.','La antera, en la punta del estambre, produce los granos de polen, que llevan los gametos masculinos. El órgano femenino es el pistilo (estigma, estilo y ovario).'],
['Después de la fecundación, el ovario de la flor','Es la parte que muchas veces comemos.','Protege las semillas y ayuda a dispersarlas.','Después de la fecundación, el ovario crece y se convierte en el fruto, y los óvulos que tiene dentro se convierten en semillas. El fruto protege las semillas y ayuda a dispersarlas.'],
['Los anfibios como las ranas tienen casi siempre fecundación','Piensa dónde se unen los gametos de la rana.','Ocurre en el agua, fuera del cuerpo de la hembra.','La mayoría de los anfibios tiene fecundación externa: la hembra suelta los óvulos en el agua y el macho los cubre de espermatozoides. Luego los renacuajos sufren metamorfosis hasta ser adultos.'],
['El huevo amniota con cáscara apareció en los','Fue el primer grupo de vertebrados que se independizó del agua para reproducirse.','Son los animales de piel con escamas.','El huevo amniota, con cáscara y membranas que protegen al embrión y lo mantienen húmedo, apareció en los reptiles. Así pudieron reproducirse lejos del agua; luego lo heredaron aves y mamíferos.'],
['La chucha o zarigüeya es un mamífero','Sus crías nacen muy poco desarrolladas.','Terminan de crecer dentro de una bolsa en el vientre de la madre.','La chucha es un marsupial: sus crías nacen muy pequeñas y terminan su desarrollo en la bolsa (marsupio) de la madre, pegadas a los pezones. Es el único marsupial común en Colombia.'],
['¿Dónde se producen los óvulos','Son las gónadas femeninas.','Son dos y están a los lados del útero.','Los óvulos se producen en los ovarios, que además fabrican estrógenos y progesterona. Normalmente madura un óvulo al mes, desde la pubertad hasta la menopausia.'],
['¿Dónde se producen los espermatozoides','Son las gónadas masculinas.','Están en el escroto, fuera del abdomen, porque necesitan una temperatura más baja.','Los espermatozoides se producen en los testículos, que también fabrican testosterona. Desde la pubertad se producen millones cada día.'],
['La capa del útero que se desprende en la menstruación','Es la capa interna del útero.','Se engrosa cada mes para recibir un posible embrión.','El endometrio es la capa interna del útero: cada mes se engrosa con vasos sanguíneos para recibir un embrión. Si no hay embarazo, se desprende y sale como menstruación.'],
['En un ciclo de 28 días, la ovulación ocurre aproximadamente el día','Ocurre más o menos a la mitad del ciclo.','El día 1 es el primer día de la menstruación.','En un ciclo de 28 días, la ovulación ocurre hacia el día 14, por un pico de la hormona LH. Los ciclos varían entre personas, por eso este cálculo no sirve como método anticonceptivo seguro.'],
['¿Qué órgano intercambia nutrientes y oxígeno entre la madre y el bebé','Se forma durante el embarazo y sale después del parto.','El cordón umbilical conecta al bebé con este órgano.','La placenta permite que pasen nutrientes y oxígeno de la sangre de la madre a la del bebé, y desechos en sentido contrario, sin que las dos sangres se mezclen. También produce hormonas del embarazo.'],
['¿Cuál es el único método anticonceptivo que también protege de las ITS','Debe ser una barrera física entre los cuerpos.','Se usa en cada relación y es de látex.','El condón (preservativo) es el único método que, además de evitar el embarazo, protege de las infecciones de transmisión sexual, porque impide el contacto con los fluidos. Por eso se recomienda la doble protección: condón más otro método.'],
['La pastilla de emergencia se puede usar como método','','','Falso. La pastilla de emergencia es solo para emergencias (por ejemplo, si falló el condón). Tiene una dosis alta de hormonas, es menos eficaz que los métodos regulares y no protege de las ITS.'],
['¿Qué infección de transmisión sexual se puede prevenir con una vacuna','Es un virus que puede causar cáncer.','Su sigla tiene tres letras.','La vacuna contra el virus del papiloma humano (VPH) es gratuita en Colombia desde los 9 años. El VPH puede causar verrugas genitales y cáncer de cuello uterino, por eso la vacuna se aplica antes de iniciar la vida sexual.'],
['¿Qué tipo de microorganismo causa la sífilis','Se cura con un antibiótico.','Los antibióticos solo actúan contra un tipo de microorganismo.','La sífilis la causa una bacteria (Treponema pallidum); por eso se cura con penicilina. En el embarazo puede pasar al bebé, por eso las pruebas prenatales son obligatorias.'],
['Una persona puede tener una ITS sin tener síntomas','','','Verdadero. Muchas ITS (como la clamidia, el VPH o el VIH al principio) no dan síntomas por mucho tiempo, pero sí se pueden contagiar. Por eso son importantes las pruebas y el uso del condón.']
]);
BIO_NUEVAS([
{t:'reproduccion',k:'mc',q:'Una bacteria se divide en dos células iguales. Este tipo de reproducción se llama:',ops:['bipartición (fisión binaria)','gemación','fragmentación','esporulación'],a:0,p:['Es reproducción asexual de seres unicelulares.','La célula se parte por la mitad.'],exp:'Es bipartición o fisión binaria: la célula copia su ADN y se divide en dos células hijas idénticas. Así se reproducen bacterias y muchos protistas; en buenas condiciones, algunas bacterias se dividen cada 20 minutos.'},
{t:'reproduccion',k:'mc',q:'Si cortas una estrella de mar en trozos y cada trozo forma una estrella nueva, ocurre:',ops:['fragmentación (regeneración)','partenogénesis','fecundación','metamorfosis'],a:0,p:['Es reproducción asexual.','Cada pedazo vuelve a formar las partes que le faltan.'],exp:'Es fragmentación: el organismo se parte y cada trozo regenera las partes que le faltan, formando un individuo completo. Ocurre en estrellas de mar, planarias y algunas algas.'},
{t:'reproduccion',k:'mc',q:'Sembrar un tallo de yuca para obtener una planta nueva es un ejemplo de:',ops:['reproducción vegetativa por esqueje','reproducción por semillas','polinización','fecundación cruzada'],a:0,p:['No se usan semillas ni flores.','Los agricultores colombianos siembran así la yuca y la caña.'],exp:'Es reproducción vegetativa por esqueje: un trozo de tallo forma raíces y crece una planta nueva idéntica a la madre. Así se siembran yuca, caña de azúcar y rosas.'},
{t:'reproduccion',k:'mc',q:'¿Qué son los gametos?',ops:['Células sexuales con la mitad de los cromosomas','Células de la piel','Órganos de la flor','Hormonas sexuales'],a:0,p:['Se forman por meiosis.','El óvulo y el espermatozoide son ejemplos.'],exp:'Los gametos son las células sexuales (óvulos y espermatozoides en los animales). Se forman por meiosis y tienen la mitad de los cromosomas; al unirse en la fecundación forman el cigoto, con el número completo.'},
{t:'reproduccion',k:'mc',q:'El paso del polen de la antera al estigma de una flor se llama:',ops:['polinización','fecundación','germinación','dispersión'],a:0,p:['Ocurre antes de la fecundación.','Lo hacen el viento, las abejas o los colibríes.'],exp:'La polinización es el transporte del polen desde la antera hasta el estigma. Puede hacerlo el viento, el agua o animales polinizadores (abejas, colibríes, murciélagos). Después el polen forma un tubo y ocurre la fecundación.'},
{t:'reproduccion',k:'mc',q:'Una flor de colores vistosos, con olor y néctar, probablemente es polinizada por:',ops:['animales como abejas, mariposas o colibríes','el viento','el agua','nadie'],a:0,p:['Los colores y el néctar son una «propaganda».','¿A quién le llama la atención el color y el dulce?'],exp:'Las flores vistosas, perfumadas y con néctar atraen animales polinizadores: el animal busca alimento y, sin querer, lleva el polen de flor en flor. Las flores polinizadas por el viento, como las del maíz, son pequeñas y sin color.'},
{t:'reproduccion',k:'mc',q:'¿Cómo se llama la parte femenina de la flor donde está el ovario?',ops:['Pistilo (o carpelo)','Estambre','Pétalo','Sépalo'],a:0,p:['Está en el centro de la flor.','Tiene estigma, estilo y ovario.'],exp:'El pistilo (formado por carpelos) es la parte femenina: el estigma recibe el polen, el estilo lo conduce y el ovario guarda los óvulos. El estambre (filamento y antera) es la parte masculina.'},
{t:'reproduccion',k:'mc',q:'Las semillas del diente de león tienen «paracaídas» y las del cadillo se pegan a la ropa. Son adaptaciones para:',ops:['la dispersión de semillas','la polinización','la fotosíntesis','la germinación en la oscuridad'],a:0,p:['Sirven para que las semillas lleguen lejos de la planta madre.','Una usa el viento y la otra a los animales.'],exp:'Son adaptaciones para la dispersión de semillas: alejarse de la planta madre evita la competencia y coloniza nuevos lugares. Pueden dispersarse por el viento, el agua o animales (que se las comen o las llevan pegadas).'},
{t:'reproduccion',k:'vf',q:'Las aves tienen fecundación interna aunque pongan huevos.',a:true,exp:'Verdadero. En las aves el macho deposita los espermatozoides dentro de la hembra y la fecundación ocurre antes de que se forme la cáscara del huevo. Después el embrión se desarrolla fuera, dentro del huevo (son ovíparas).'},
{t:'reproduccion',k:'mc',q:'Un animal cuyo embrión se desarrolla dentro del cuerpo de la madre y se alimenta de ella es:',ops:['vivíparo','ovíparo','ovovivíparo','hermafrodita'],a:0,p:['Las crías nacen vivas, no de un huevo puesto afuera.','Así nacen casi todos los mamíferos.'],exp:'Es vivíparo: el embrión se desarrolla dentro de la madre y recibe alimento de ella (en los mamíferos, a través de la placenta). Los ovíparos ponen huevos que se desarrollan afuera; los ovovivíparos guardan los huevos dentro hasta que eclosionan.'},
{t:'reproduccion',k:'mc',q:'Las lombrices de tierra tienen órganos masculinos y femeninos en el mismo individuo. Son:',ops:['hermafroditas','asexuales','vivíparas','partenogenéticas'],a:0,p:['Tienen los dos sexos a la vez.','Aun así, se cruzan con otra lombriz.'],exp:'Las lombrices son hermafroditas: cada una produce óvulos y espermatozoides. Aun así, normalmente se cruzan con otra lombriz e intercambian espermatozoides, lo que mantiene la variabilidad genética.'},
{t:'reproduccion',k:'mc',q:'¿Qué hormona hace que se produzcan los cambios de la pubertad en las mujeres y que el endometrio crezca?',ops:['Estrógeno','Insulina','Testosterona','Adrenalina'],a:0,p:['La producen los ovarios.','Su nombre empieza por «E».'],exp:'Los estrógenos, producidos por los ovarios, causan los cambios de la pubertad femenina (crecimiento de los senos, ensanchamiento de las caderas) y hacen crecer el endometrio en la primera mitad del ciclo.'},
{t:'reproduccion',k:'mc',q:'¿Qué es la menstruación?',ops:['La salida del endometrio cuando no hay embarazo','La salida del óvulo del ovario','La unión del óvulo y el espermatozoide','La implantación del embrión'],a:0,p:['Ocurre más o menos cada 28 días.','Tiene que ver con la capa interna del útero.'],exp:'La menstruación es la salida, por la vagina, del endometrio (capa interna del útero) con algo de sangre, cuando no hubo embarazo. Dura de 3 a 7 días y marca el día 1 del ciclo menstrual.'},
{t:'reproduccion',k:'ord',q:'Ordena el camino del espermatozoide desde que se forma:',ops:['Testículo','Epidídimo','Conducto deferente','Uretra'],p:['Empieza en la gónada masculina.','Antes de salir por la uretra pasa por un conducto largo.'],exp:'Los espermatozoides se forman en los testículos, maduran en el epidídimo, suben por los conductos deferentes (donde se mezclan con los líquidos de las vesículas seminales y la próstata para formar el semen) y salen por la uretra.'},
{t:'reproduccion',k:'ord',q:'Ordena las etapas del desarrollo humano antes del nacimiento:',ops:['Cigoto','Mórula','Blastocisto','Embrión','Feto'],p:['Empieza con la unión de los gametos.','La etapa de feto empieza hacia la semana 9.'],exp:'Cigoto (óvulo fecundado) → mórula (bolita de células, días 3-4) → blastocisto (se implanta en el útero hacia el día 7) → embrión (se forman los órganos, hasta la semana 8) → feto (crece y madura hasta el parto).'},
{t:'reproduccion',k:'esc',q:'¿Cómo se llama la célula que resulta de la unión del óvulo y el espermatozoide?',a:['cigoto','el cigoto','zigoto'],p:['Es la primera célula de un nuevo individuo.','Empieza por «c» (también se escribe con «z»).'],exp:'El cigoto es la célula que se forma en la fecundación: tiene los 46 cromosomas (23 del óvulo y 23 del espermatozoide) y, al dividirse muchas veces, origina todo el organismo.'},
{t:'reproduccion',k:'mc',q:'¿Qué infección de transmisión sexual ataca el sistema inmune y, sin tratamiento, causa el sida?',ops:['VIH','Sífilis','VPH','Gonorrea'],a:0,p:['Es un virus.','Destruye los linfocitos T, que coordinan las defensas.'],exp:'El VIH (virus de inmunodeficiencia humana) destruye los linfocitos T del sistema inmune. Sin tratamiento, años después aparece el sida y el cuerpo no puede defenderse de otras infecciones. No tiene cura, pero el tratamiento antirretroviral permite una vida larga y evita el contagio.'},
{t:'reproduccion',k:'vf',q:'El embarazo en la adolescencia tiene más riesgos para la salud de la madre y del bebé.',a:true,exp:'Verdadero. En la adolescencia hay más riesgo de anemia, parto prematuro, bajo peso al nacer y complicaciones, además de efectos en la educación y el proyecto de vida. Por eso son importantes la educación sexual y el acceso a métodos anticonceptivos.'},
{t:'reproduccion',k:'mc',q:'¿Qué métodos anticonceptivos son hormonales?',ops:['La pastilla, la inyección y el implante','El condón','Los días del ciclo','El coito interrumpido'],a:0,p:['Actúan con estrógenos o progesterona.','Impiden la ovulación.'],exp:'La pastilla, la inyección, el implante subdérmico y el parche son métodos hormonales: con estrógenos o progestágenos impiden la ovulación. Son muy eficaces, pero no protegen de las ITS; para eso se necesita el condón.'},
{t:'reproduccion',k:'mc',q:'Durante el embarazo, ¿por qué no se debe consumir alcohol?',ops:['Porque pasa por la placenta y daña al bebé','Porque no tiene ningún efecto','Porque solo afecta a la madre','Porque mejora el crecimiento del bebé'],a:0,p:['La placenta deja pasar muchas sustancias de la madre.','El cerebro del bebé es muy sensible.'],exp:'El alcohol atraviesa la placenta y llega al bebé, cuyo hígado no puede eliminarlo. Puede causar el síndrome alcohólico fetal: bajo peso, malformaciones y daños en el cerebro. No hay una cantidad segura durante el embarazo.'},
{t:'reproduccion',k:'mc',q:'¿Qué ventaja tienen los animales que cuidan a sus crías, como los mamíferos?',ops:['Sobreviven más crías aunque tengan pocas','Tienen miles de crías','No necesitan alimentarlas','Las crías nacen adultas'],a:0,p:['Compara una rana que pone miles de huevos con una vaca que tiene un ternero.','Hay más inversión en cada cría.'],exp:'Los animales que cuidan a sus crías (mamíferos, aves) tienen pocas, pero invierten mucho en cada una (alimento, protección), así que sobreviven más. Los que no las cuidan, como muchos peces y ranas, ponen miles de huevos porque la mayoría muere.'}
]);


/* ── ampliación a 40 o más por tema y sección (versión 2.4): preguntas nuevas de cada tema (cortas, aptas también para los laberintos) ── */
BIO_NUEVAS([
{t:"celula",k:"mc",q:"¿Qué científico dijo que todas las plantas están formadas por células?",ops:["Schleiden","Virchow","Hooke","Darwin"],a:0,p:["Fue un botánico alemán.","Trabajó al mismo tiempo que Schwann, que estudió los animales."],exp:"Matthias Schleiden (1838) concluyó que todas las plantas están formadas por células; Schwann lo extendió a los animales al año siguiente."},
{t:"celula",k:"mc",q:"¿Qué organelo fabrica los lípidos de la célula?",ops:["Retículo endoplasmático liso","Ribosoma","Lisosoma","Nucléolo"],a:0,p:["Es una red de membranas sin ribosomas.","Su nombre dice cómo se ve: sin «granos»."],exp:"El retículo endoplasmático liso no tiene ribosomas y fabrica lípidos; el rugoso, con ribosomas, fabrica proteínas."},
{t:"celula",k:"mc",q:"¿Cuál es la unidad que se usa para medir células?",ops:["El micrómetro (µm)","El kilómetro","El metro","El litro"],a:0,p:["Es la milésima parte de un milímetro.","Su símbolo lleva la letra griega «mu»."],exp:"Las células se miden en micrómetros: 1 µm es la milésima parte de un milímetro. Una bacteria mide unos 2 µm y una célula humana unos 10 a 30 µm."},
{t:"celula",k:"vf",q:"La pared celular de las plantas está por fuera de la membrana.",a:true,exp:"Verdadero. La pared de celulosa rodea la membrana y le da a la célula vegetal forma fija y resistencia."},
{t:"celula",k:"mc",q:"¿Qué gas necesita la mitocondria para la respiración celular?",ops:["Oxígeno","Nitrógeno","Helio","Metano"],a:0,p:["Es el gas que respiramos.","Sin él, la célula hace fermentación."],exp:"La respiración celular aerobia usa oxígeno para degradar la glucosa y obtener ATP; libera CO₂ y agua."},
{t:"celula",k:"mc",q:"¿Qué produce la fotosíntesis además de glucosa?",ops:["Oxígeno","Dióxido de carbono","Alcohol","Ácido láctico"],a:0,p:["Es un gas que se libera al aire.","Viene de romper moléculas de agua."],exp:"La fotosíntesis produce glucosa y libera oxígeno, que sale de la ruptura del agua en la fase luminosa."},
{t:"celula",k:"vf",q:"La difusión simple gasta energía (ATP).",a:false,exp:"Falso. La difusión es transporte pasivo: las sustancias van de donde hay más a donde hay menos sin gastar ATP."},
{t:"celula",k:"mc",q:"¿Qué organelo tienen las células animales y NO las vegetales?",ops:["Centriolos","Pared celular","Cloroplastos","Vacuola central"],a:0,p:["Participa en la división de la célula animal.","Son dos cilindros cerca del núcleo."],exp:"Los centriolos están en las células animales y ayudan a organizar el huso en la división. Pared, cloroplastos y vacuola central son propios de las vegetales."},
{t:"celula",k:"mc",q:"¿Qué parte del núcleo fabrica los ribosomas?",ops:["El nucléolo","La membrana nuclear","El citoplasma","La pared celular"],a:0,p:["Es una zona más oscura dentro del núcleo.","Su nombre es un diminutivo de «núcleo»."],exp:"El nucléolo, dentro del núcleo, fabrica las piezas de los ribosomas, que luego salen al citoplasma."},
{t:"celula",k:"mc",q:"Sacar sustancias de la célula en vesículas se llama:",ops:["Exocitosis","Endocitosis","Ósmosis","Difusión"],a:0,p:["Es lo contrario de la endocitosis.","«Exo» significa afuera."],exp:"En la exocitosis una vesícula se une a la membrana y suelta su contenido afuera; así salen hormonas y enzimas."}
]);
BIO_NUEVAS([
{t:"division",k:"mc",q:"¿Cuántos cromosomas tiene una célula del cuerpo humano?",ops:["46","23","92","12"],a:0,p:["Son 23 parejas.","Es el doble de un gameto."],exp:"Las células del cuerpo son diploides: 46 cromosomas en 23 parejas, una de cada padre."},
{t:"division",k:"mc",q:"Una célula con 46 cromosomas se llama:",ops:["Diploide","Haploide","Procariota","Gameto"],a:0,p:["Tiene dos juegos de cromosomas.","Se escribe 2n."],exp:"Una célula diploide (2n) tiene dos juegos de cromosomas, uno de cada padre."},
{t:"division",k:"mc",q:"Un gameto con 23 cromosomas es:",ops:["Haploide","Diploide","Triploide","Somático"],a:0,p:["Tiene un solo juego de cromosomas.","Se escribe n."],exp:"Los gametos son haploides (n): tienen un solo cromosoma de cada pareja."},
{t:"division",k:"mc",q:"¿En qué etapa del ciclo celular pasa la célula la mayor parte del tiempo?",ops:["Interfase","Profase","Anafase","Telofase"],a:0,p:["No es una etapa de la mitosis.","Allí crece y copia su ADN."],exp:"La célula pasa casi todo su ciclo en interfase, donde crece y copia su ADN; la división es solo una pequeña parte."},
{t:"division",k:"mc",q:"¿En qué fase de la mitosis los cromosomas se alinean en el centro?",ops:["Metafase","Profase","Anafase","Telofase"],a:0,p:["«Meta» recuerda a «medio».","Es la segunda fase."],exp:"En la metafase los cromosomas se ordenan en fila en el centro de la célula."},
{t:"division",k:"mc",q:"¿En qué fase se separan las cromátidas hacia los polos?",ops:["Anafase","Metafase","Profase","Interfase"],a:0,p:["Es la tercera fase.","«Ana» significa hacia arriba o hacia atrás."],exp:"En la anafase las cromátidas hermanas se separan y viajan a polos opuestos."},
{t:"division",k:"mc",q:"¿En qué fase se forman dos núcleos nuevos?",ops:["Telofase","Profase","Metafase","Anafase"],a:0,p:["Es la última fase.","«Telo» significa final."],exp:"En la telofase se forman dos núcleos nuevos alrededor de cada grupo de cromosomas."},
{t:"division",k:"mc",q:"¿En qué fase los cromosomas se condensan y se hacen visibles?",ops:["Profase","Metafase","Anafase","Telofase"],a:0,p:["Es la primera fase.","«Pro» significa antes."],exp:"En la profase el ADN se enrolla, los cromosomas se hacen visibles y se forma el huso."},
{t:"division",k:"mc",q:"¿Cómo se llama la división del citoplasma?",ops:["Citocinesis","Interfase","Meiosis","Replicación"],a:0,p:["Ocurre al final de la mitosis.","«Cito» significa célula."],exp:"La citocinesis parte el citoplasma en dos después de repartir los cromosomas."},
{t:"division",k:"mc",q:"¿Cómo se divide el citoplasma en una célula vegetal?",ops:["Con una placa celular","Con un surco que la estrangula","No se divide","Por gemación"],a:0,p:["La pared rígida no deja estrangularse.","Vesículas del Golgi forman la pared nueva."],exp:"En la célula vegetal se forma una placa celular con vesículas del Golgi que se convierte en la nueva pared."},
{t:"division",k:"mc",q:"¿Cómo se divide el citoplasma en una célula animal?",ops:["Con un anillo que la estrangula","Con una placa de celulosa","Con la pared celular","No se divide"],a:0,p:["Funciona como un cinturón.","Forma un surco."],exp:"En la célula animal un anillo de proteínas se aprieta como un cinturón hasta partirla en dos."},
{t:"division",k:"mc",q:"¿Cuántas células hijas produce la mitosis?",ops:["2","4","1","8"],a:0,p:["Hay una sola división.","Son idénticas a la madre."],exp:"La mitosis produce 2 células hijas idénticas entre sí y a la madre."},
{t:"division",k:"mc",q:"¿Cuántas divisiones tiene la meiosis?",ops:["Dos","Una","Tres","Cuatro"],a:0,p:["Se llaman I y II.","Por eso salen cuatro células."],exp:"La meiosis tiene dos divisiones seguidas (meiosis I y meiosis II) y produce cuatro células."},
{t:"division",k:"mc",q:"¿Para qué sirve la meiosis?",ops:["Para formar gametos","Para reparar heridas","Para crecer","Para hacer fotosíntesis"],a:0,p:["Ocurre en los órganos reproductores.","Forma óvulos y espermatozoides."],exp:"La meiosis forma los gametos (óvulos, espermatozoides y polen) con la mitad de los cromosomas."},
{t:"division",k:"mc",q:"¿Para qué sirve la mitosis?",ops:["Para crecer y reparar tejidos","Para formar óvulos","Para formar polen","Para reducir los cromosomas"],a:0,p:["Produce células idénticas.","Ocurre cuando se cierra una herida."],exp:"La mitosis sirve para crecer, reparar heridas, reemplazar células y reproducirse de forma asexual."},
{t:"division",k:"mc",q:"El intercambio de trozos entre cromosomas homólogos se llama:",ops:["Entrecruzamiento","Replicación","Citocinesis","Mutación"],a:0,p:["Ocurre en la meiosis I.","Aumenta la variabilidad."],exp:"En el entrecruzamiento los cromosomas homólogos intercambian trozos, lo que produce combinaciones nuevas de alelos."},
{t:"division",k:"mc",q:"El síndrome de Down se debe a:",ops:["Tres copias del cromosoma 21","La falta del cromosoma X","Una infección","Una mala alimentación"],a:0,p:["Es una trisomía.","La persona tiene 47 cromosomas."],exp:"El síndrome de Down se debe a una trisomía 21: tres copias del cromosoma 21 por un error en la meiosis."},
{t:"division",k:"mc",q:"Cuando una pareja de cromosomas no se separa en la meiosis se habla de:",ops:["No disyunción","Citocinesis","Interfase","Fecundación"],a:0,p:["«Disyunción» es separación.","Deja gametos con un cromosoma de más o de menos."],exp:"La no disyunción es la falla al separar los cromosomas; produce gametos con cromosomas de más o de menos."},
{t:"division",k:"mc",q:"El cáncer aparece cuando las células:",ops:["se dividen sin control","dejan de dividirse","hacen fotosíntesis","pierden el núcleo"],a:0,p:["Fallan los puntos de control.","Se forma un tumor."],exp:"El cáncer aparece cuando mutaciones dañan los genes que controlan el ciclo y la célula se divide sin parar."},
{t:"division",k:"mc",q:"Las dos copias idénticas de un cromosoma copiado se llaman:",ops:["Cromátidas hermanas","Homólogos","Gametos","Centriolos"],a:0,p:["Están unidas por el centro.","Se separan en la anafase."],exp:"Las cromátidas hermanas son las dos copias idénticas de un cromosoma, unidas por el centrómero."},
{t:"division",k:"mc",q:"¿Dónde ocurre la meiosis en los seres humanos?",ops:["En ovarios y testículos","En la piel","En el hígado","En el corazón"],a:0,p:["Son los órganos reproductores.","Allí se forman los gametos."],exp:"La meiosis ocurre solo en los órganos reproductores: ovarios y testículos."},
{t:"division",k:"mc",q:"Las neuronas que casi nunca se dividen están en la etapa:",ops:["G0","Anafase","Metafase","Telofase"],a:0,p:["Salieron del ciclo.","Es una etapa de descanso."],exp:"Las neuronas y las células del músculo del corazón salen del ciclo a una etapa de descanso llamada G0."},
{t:"division",k:"mc",q:"La imagen de los cromosomas ordenados por parejas es el:",ops:["Cariotipo","Genotipo","Fenotipo","Huso"],a:0,p:["Se hace en un laboratorio.","Muestra si hay un cromosoma de más."],exp:"El cariotipo muestra los cromosomas de una célula ordenados por parejas y por tamaño."},
{t:"division",k:"vf",q:"En la mitosis las células hijas tienen la mitad de los cromosomas.",a:false,exp:"Falso. En la mitosis las células hijas tienen el mismo número que la madre (2n → 2n); la mitad se forma en la meiosis."},
{t:"division",k:"vf",q:"La meiosis produce células distintas entre sí.",a:true,exp:"Verdadero. Por el entrecruzamiento y la orientación al azar, las cuatro células de la meiosis son distintas."},
{t:"division",k:"vf",q:"La célula copia su ADN durante la interfase.",a:true,exp:"Verdadero. En la interfase (fase S) la célula copia su ADN antes de dividirse."},
{t:"division",k:"vf",q:"Las células de la piel se dividen con mucha frecuencia.",a:true,exp:"Verdadero. La piel se renueva constantemente: sus células se dividen todo el tiempo por mitosis."},
{t:"division",k:"vf",q:"La meiosis ocurre en todas las células del cuerpo.",a:false,exp:"Falso. La meiosis solo ocurre en los órganos reproductores; las demás células se dividen por mitosis."},
{t:"division",k:"vf",q:"El tabaco y el exceso de sol aumentan el riesgo de cáncer.",a:true,exp:"Verdadero. Causan mutaciones que pueden dañar los genes que controlan la división celular."},
{t:"division",k:"vf",q:"Los cromosomas homólogos vienen uno de la mamá y otro del papá.",a:true,exp:"Verdadero. En cada pareja de homólogos, un cromosoma viene de la madre y el otro del padre."},
{t:"division",k:"vf",q:"Las bacterias se reproducen por meiosis.",a:false,exp:"Falso. Las bacterias se dividen por bipartición, un tipo de reproducción asexual; no hacen meiosis."},
{t:"division",k:"vf",q:"La telofase es la primera fase de la mitosis.",a:false,exp:"Falso. La telofase es la última; el orden es profase, metafase, anafase y telofase."},
{t:"division",k:"vf",q:"Cada gameto humano tiene 23 cromosomas.",a:true,exp:"Verdadero. Los gametos son haploides: tienen 23 cromosomas, uno de cada pareja."},
{t:"division",k:"mc",q:"¿Qué división ocurre en la raíz de una planta que crece?",ops:["Mitosis","Meiosis","Fecundación","Polinización"],a:0,p:["La planta solo está creciendo.","Las células hijas son iguales."],exp:"La raíz crece porque sus células se dividen por mitosis en la punta."},
{t:"division",k:"vf",q:"El entrecruzamiento ocurre en la mitosis.",a:false,exp:"Falso. El entrecruzamiento ocurre en la meiosis I, entre cromosomas homólogos."},
{t:"division",k:"mc",q:"¿Cuántas células produce la meiosis?",ops:["4","2","1","8"],a:0,p:["Hay dos divisiones seguidas.","2 × 2."],exp:"La meiosis produce 4 células haploides, todas distintas entre sí."},
{t:"division",k:"esc",q:"¿Cómo se llama la división celular que forma dos células idénticas?",a:["mitosis","la mitosis"],p:["Sirve para crecer y reparar heridas.","Sus fases son PMAT."],exp:"La mitosis forma dos células hijas idénticas a la madre, con el mismo número de cromosomas."},
{t:"division",k:"esc",q:"¿Cómo se llama la división que forma los gametos?",a:["meiosis","la meiosis"],p:["Tiene dos divisiones seguidas.","Reduce los cromosomas a la mitad."],exp:"La meiosis forma los gametos haploides en dos divisiones seguidas."},
{t:"division",k:"esc",q:"¿Cómo se llama la estructura de ADN empacado que se ve antes de la división?",a:["cromosoma","cromosomas","el cromosoma"],p:["Los humanos tienen 46.","Se ve como una X."],exp:"El cromosoma es el ADN enrollado y empacado; antes de dividirse se ve como una X de dos cromátidas."},
{t:"division",k:"ord",q:"Ordena las fases de la mitosis:",ops:["Profase","Metafase","Anafase","Telofase"],p:["Recuerda «PMAT».","La última es la que forma los núcleos."],exp:"Profase (se condensan), metafase (se alinean), anafase (se separan) y telofase (dos núcleos)."},
{t:"division",k:"ord",q:"Ordena el ciclo de vida de una célula que se divide:",ops:["La célula crece","Copia su ADN","Reparte los cromosomas","Divide el citoplasma"],p:["Empieza en la interfase.","Termina con la citocinesis."],exp:"En la interfase crece y copia su ADN; luego la mitosis reparte los cromosomas y la citocinesis divide el citoplasma."},
{t:"division",k:"mc",q:"¿Qué estructura jala los cromosomas hacia los polos?",ops:["El huso","La pared celular","El nucléolo","La vacuola"],a:0,p:["Está hecho de fibras de proteína.","Se forma en la profase."],exp:"El huso, formado por fibras (microtúbulos), se une a los cromosomas y los jala hacia los polos."},
{t:"division",k:"mc",q:"Si una célula de perro tiene 78 cromosomas, ¿cuántos tiene su gameto?",ops:["39","78","156","23"],a:0,p:["El gameto es haploide.","Divide entre dos."],exp:"El gameto tiene la mitad de los cromosomas: 78 ÷ 2 = 39."},
{t:"division",k:"mc",q:"Después de la mitosis, una célula con 46 cromosomas da hijas con:",ops:["46","23","92","47"],a:0,p:["La mitosis conserva el número.","2n → 2n."],exp:"La mitosis conserva el número de cromosomas: de 46 salen dos células de 46."},
{t:"division",k:"mc",q:"¿Qué parte del cromosoma une a las cromátidas hermanas?",ops:["El centrómero","El huso","El nucléolo","El ribosoma"],a:0,p:["Está en el centro de la X.","Allí se pegan las fibras del huso."],exp:"El centrómero es el punto donde se unen las cromátidas hermanas y donde se pegan las fibras del huso."}
]);
BIO_NUEVAS([
{t:"reinos",k:"mc",q:"¿Qué categoría está justo debajo del reino?",ops:["Filo","Clase","Orden","Género"],a:0,p:["Recuerda la frase «Doña Reina Fina Clara…».","Es la tercera palabra de la frase."],exp:"Después del reino viene el filo (o división en plantas): Dominio, Reino, Filo, Clase, Orden, Familia, Género, Especie."},
{t:"reinos",k:"mc",q:"El nombre científico se escribe en:",ops:["Latín","Inglés","Griego moderno","Español"],a:0,p:["Es una lengua antigua que ya no cambia.","La usaban los científicos de la época de Linneo."],exp:"Los nombres científicos van en latín (o latinizados) para que sean iguales en todos los países y no cambien con el tiempo."},
{t:"reinos",k:"mc",q:"¿A qué reino pertenece el moho del pan?",ops:["Fungi","Plantae","Monera","Animalia"],a:0,p:["No hace fotosíntesis.","Se alimenta por absorción."],exp:"El moho del pan es un hongo (reino Fungi): forma hifas y se alimenta por absorción del pan."},
{t:"reinos",k:"vf",q:"Todas las plantas hacen fotosíntesis y tienen pared de celulosa.",a:true,exp:"Verdadero (con muy pocas excepciones de plantas parásitas): las plantas son autótrofas y su pared es de celulosa."},
{t:"reinos",k:"mc",q:"¿Qué reino agrupa a los seres pluricelulares que se alimentan por ingestión?",ops:["Animalia","Fungi","Plantae","Protista"],a:0,p:["Tragan su alimento.","Sus células no tienen pared."],exp:"Los animales son pluricelulares, eucariotas y heterótrofos por ingestión: comen y digieren por dentro."},
{t:"reinos",k:"mc",q:"¿Cuántas palabras tiene un nombre científico?",ops:["Dos","Una","Tres","Cuatro"],a:0,p:["Por eso el sistema se llama «binomial».","«Bi» significa dos."],exp:"Tiene dos palabras: el género (con mayúscula) y el epíteto de la especie (con minúscula), en cursiva."},
{t:"reinos",k:"mc",q:"Los seres vivos con núcleo pertenecen al dominio:",ops:["Eukarya","Bacteria","Archaea","Monera"],a:0,p:["«Eu» significa verdadero.","Incluye animales, plantas, hongos y protistas."],exp:"El dominio Eukarya agrupa a todos los seres con células eucariotas: animales, plantas, hongos y protistas."},
{t:"reinos",k:"vf",q:"La ballena es un pez porque vive en el mar.",a:false,exp:"Falso. La ballena es un mamífero: respira por pulmones, tiene pelo al nacer y alimenta a sus crías con leche."},
{t:"reinos",k:"mc",q:"¿Qué tienen en común un murciélago y un ratón?",ops:["Son mamíferos","Son aves","Son reptiles","Son insectos"],a:0,p:["Tienen pelo.","Alimentan a sus crías con leche."],exp:"Los dos son mamíferos: tienen pelo, glándulas mamarias y son endotermos. El murciélago es el único mamífero que vuela."},
{t:"reinos",k:"mc",q:"Las plantas con flores y frutos se llaman:",ops:["Angiospermas","Gimnospermas","Briofitos","Helechos"],a:0,p:["Sus semillas están protegidas.","«Angio» significa recipiente."],exp:"Las angiospermas tienen flores y frutos que envuelven sus semillas, como el mango o la orquídea."},
{t:"reinos",k:"mc",q:"¿Qué organismo NO es un hongo?",ops:["El alga","La levadura","El champiñón","El moho"],a:0,p:["Busca el que hace fotosíntesis.","Vive en el agua y es verde."],exp:"El alga hace fotosíntesis y se clasifica en Protista (o Plantae, según el sistema). Levadura, champiñón y moho son hongos."},
{t:"reinos",k:"vf",q:"Las arqueas pueden vivir en lugares muy salados o muy calientes.",a:true,exp:"Verdadero. Muchas arqueas son extremófilas: viven en salinas, fuentes termales o lugares muy ácidos."}
]);
BIO_NUEVAS([
{t:"sistemas",k:"mc",q:"¿Qué tejido recubre el cuerpo por fuera y los órganos por dentro?",ops:["Epitelial","Muscular","Nervioso","Conectivo"],a:0,p:["La piel es un ejemplo.","Sus células están muy juntas, formando capas."],exp:"El tejido epitelial forma capas de células muy unidas que recubren el cuerpo (piel) y tapizan órganos como el intestino."},
{t:"sistemas",k:"mc",q:"¿Qué órgano bombea la sangre?",ops:["El corazón","El hígado","El pulmón","El riñón"],a:0,p:["Late unas 100 000 veces al día.","Tiene dos aurículas y dos ventrículos."],exp:"El corazón es un músculo que bombea la sangre por las arterias hacia todo el cuerpo."},
{t:"sistemas",k:"mc",q:"¿Qué células de la sangre ayudan a coagular una herida?",ops:["Plaquetas","Glóbulos rojos","Neuronas","Linfocitos"],a:0,p:["Son fragmentos de células.","Forman un tapón cuando te cortas."],exp:"Las plaquetas se pegan en la herida y forman un tapón que detiene el sangrado."},
{t:"sistemas",k:"vf",q:"Las venas llevan la sangre de regreso al corazón.",a:true,exp:"Verdadero. Las arterias sacan la sangre del corazón y las venas la devuelven."},
{t:"sistemas",k:"mc",q:"¿Dónde empieza la digestión de los alimentos?",ops:["En la boca","En el estómago","En el intestino grueso","En el esófago"],a:0,p:["Allí se mastica.","La saliva tiene una enzima."],exp:"La digestión empieza en la boca: los dientes trituran y la amilasa de la saliva empieza a digerir el almidón."},
{t:"sistemas",k:"mc",q:"¿Qué órgano guarda la orina antes de expulsarla?",ops:["La vejiga","El riñón","El uréter","El hígado"],a:0,p:["Es una bolsa elástica.","Está en la parte baja del abdomen."],exp:"La orina se forma en los riñones, baja por los uréteres y se guarda en la vejiga hasta salir por la uretra."},
{t:"sistemas",k:"mc",q:"¿Qué sistema produce las hormonas?",ops:["Endocrino","Digestivo","Óseo","Respiratorio"],a:0,p:["Está formado por glándulas.","La tiroides y el páncreas son parte de él."],exp:"El sistema endocrino tiene glándulas que sueltan hormonas a la sangre, como la tiroides, el páncreas y las suprarrenales."},
{t:"sistemas",k:"vf",q:"La primera línea de defensa del cuerpo es la piel.",a:true,exp:"Verdadero. La piel y las mucosas impiden la entrada de microbios: son la primera línea de defensa."},
{t:"sistemas",k:"mc",q:"¿Cuál es la función de los glóbulos blancos?",ops:["Defender el cuerpo","Llevar oxígeno","Coagular la sangre","Producir bilis"],a:0,p:["Son parte del sistema inmune.","Atacan microbios."],exp:"Los glóbulos blancos defienden el cuerpo: algunos se comen a los microbios y otros fabrican anticuerpos."},
{t:"sistemas",k:"mc",q:"Las tres funciones vitales son nutrición, relación y…",ops:["reproducción","respiración","digestión","circulación"],a:0,p:["Permite que la especie continúe.","Produce nuevos individuos."],exp:"Las funciones vitales son nutrición (obtener materia y energía), relación (responder al ambiente) y reproducción (formar nuevos individuos)."},
{t:"sistemas",k:"mc",q:"¿Qué tejido forma los tendones y los huesos?",ops:["Conectivo","Epitelial","Nervioso","Muscular"],a:0,p:["Une y sostiene otros tejidos.","La sangre también pertenece a este tipo."],exp:"El tejido conectivo une y sostiene: incluye hueso, cartílago, tendones, grasa y sangre."}
]);
BIO_NUEVAS([
{t:"reproduccion",k:"mc",q:"¿Qué parte de la flor recibe el polen?",ops:["El estigma","La antera","El sépalo","El pétalo"],a:0,p:["Está en la punta del pistilo.","Suele ser pegajoso."],exp:"El estigma, en la punta del pistilo, es pegajoso y recibe el polen durante la polinización."},
{t:"reproduccion",k:"mc",q:"¿Cuántos días dura en promedio el ciclo menstrual?",ops:["28","7","14","60"],a:0,p:["Es más o menos un mes.","La ovulación ocurre a la mitad."],exp:"El ciclo menstrual dura en promedio 28 días, aunque varía entre 21 y 35 días según la persona."},
{t:"reproduccion",k:"vf",q:"Las semillas se forman a partir de los óvulos de la flor.",a:true,exp:"Verdadero. Después de la fecundación, los óvulos se convierten en semillas y el ovario en fruto."},
{t:"reproduccion",k:"mc",q:"¿Cómo nacen las crías de los animales ovíparos?",ops:["De huevos puestos fuera de la madre","Dentro de la madre, con placenta","En una bolsa","Por gemación"],a:0,p:["Así nacen las gallinas.","La madre pone huevos."],exp:"Los ovíparos ponen huevos y el embrión se desarrolla fuera de la madre, como las aves y muchos reptiles."},
{t:"reproduccion",k:"mc",q:"¿Dónde se desarrolla el bebé durante el embarazo?",ops:["En el útero","En el ovario","En la vagina","En la trompa de Falopio"],a:0,p:["Es un órgano muscular hueco.","Su capa interna es el endometrio."],exp:"El embrión se implanta en el útero, donde se desarrolla durante unos nueve meses."},
{t:"reproduccion",k:"vf",q:"La gemación es un tipo de reproducción sexual.",a:false,exp:"Falso. En la gemación sale una yema del progenitor: es reproducción asexual y los hijos son clones."},
{t:"reproduccion",k:"mc",q:"El paso de las semillas lejos de la planta madre se llama:",ops:["Dispersión","Polinización","Germinación","Fecundación"],a:0,p:["Lo pueden hacer el viento o los animales.","Evita la competencia con la madre."],exp:"La dispersión aleja las semillas de la planta madre por el viento, el agua o los animales."},
{t:"reproduccion",k:"mc",q:"¿Qué método anticonceptivo es una barrera física?",ops:["El condón","La pastilla","La inyección","El implante"],a:0,p:["Impide que los espermatozoides lleguen al óvulo.","Se usa en cada relación."],exp:"El condón es un método de barrera: impide el paso de los espermatozoides y además protege de las ITS."},
{t:"reproduccion",k:"mc",q:"¿Qué tipo de reproducción hace una fresa con sus estolones?",ops:["Asexual vegetativa","Sexual","Por esporas","Partenogénesis"],a:0,p:["Los estolones son tallos que crecen sobre el suelo.","Las plantas nuevas son iguales a la madre."],exp:"Los estolones forman plantas nuevas idénticas a la madre: es reproducción asexual vegetativa."},
{t:"reproduccion",k:"vf",q:"La placenta permite que la sangre de la madre y la del bebé se mezclen.",a:false,exp:"Falso. La placenta intercambia nutrientes, oxígeno y desechos sin que las dos sangres se mezclen."}
]);
BIO_NUEVAS([
{t:"genetica",k:"mc",q:"Un organismo AA es:",ops:["Homocigoto dominante","Heterocigoto","Homocigoto recesivo","Haploide"],a:0,p:["Sus dos alelos son iguales.","Los dos son de letra mayúscula."],exp:"AA es homocigoto dominante: tiene dos alelos iguales y dominantes. aa sería homocigoto recesivo y Aa heterocigoto."},
{t:"genetica",k:"mc",q:"¿Qué azúcar tiene el ADN?",ops:["Desoxirribosa","Ribosa","Glucosa","Sacarosa"],a:0,p:["Su nombre está dentro de la sigla ADN.","Le falta un oxígeno a la ribosa."],exp:"El ADN (ácido desoxirribonucleico) tiene desoxirribosa; el ARN tiene ribosa."},
{t:"genetica",k:"vf",q:"Los gemelos idénticos tienen el mismo ADN.",a:true,exp:"Verdadero. Los gemelos idénticos vienen de un mismo cigoto que se separó en dos, así que tienen el mismo ADN."},
{t:"genetica",k:"mc",q:"¿Cuántas cadenas tiene el ARN?",ops:["Una","Dos","Tres","Cuatro"],a:0,p:["Es diferente del ADN.","El ADN tiene dos."],exp:"El ARN tiene una sola cadena; el ADN tiene dos, enrolladas en doble hélice."},
{t:"genetica",k:"mc",q:"¿Cómo se llama el paso de ADN a ARN mensajero?",ops:["Transcripción","Traducción","Replicación","Mutación"],a:0,p:["Es como copiar un texto en el mismo idioma.","Ocurre en el núcleo."],exp:"La transcripción copia un gen del ADN en ARN mensajero, dentro del núcleo."},
{t:"genetica",k:"mc",q:"¿Qué cruce usó Mendel para estudiar dos características a la vez?",ops:["Dihíbrido","Monohíbrido","De prueba","Clonación"],a:0,p:["«Di» significa dos.","Da la proporción 9:3:3:1."],exp:"El cruce dihíbrido estudia dos características a la vez, como el color y la forma de la semilla, y da 9:3:3:1."},
{t:"genetica",k:"vf",q:"Todas las mutaciones son dañinas.",a:false,exp:"Falso. Muchas mutaciones son neutras y algunas son útiles; son la fuente de la variación sobre la que actúa la evolución."},
{t:"genetica",k:"mc",q:"¿Qué molécula fabrica la célula a partir de las instrucciones de un gen?",ops:["Una proteína","Un lípido","Un azúcar","Un mineral"],a:0,p:["Está formada por aminoácidos.","La fabrican los ribosomas."],exp:"Cada gen tiene la información para fabricar una proteína, que se arma con aminoácidos en los ribosomas."},
{t:"genetica",k:"mc",q:"Un árbol familiar que muestra cómo se hereda un rasgo se llama:",ops:["Genealogía","Cariotipo","Punnett","Codón"],a:0,p:["Usa cuadros para hombres y círculos para mujeres.","También se llama pedigrí."],exp:"Una genealogía (o pedigrí) muestra las generaciones de una familia y quién tiene un rasgo, para deducir cómo se hereda."},
{t:"genetica",k:"vf",q:"El ambiente puede influir en el fenotipo.",a:true,exp:"Verdadero. El fenotipo depende de los genes y del ambiente: por ejemplo, la estatura depende también de la alimentación."}
]);
BIO_NUEVAS([
{t:"evolucion",k:"mc",q:"¿Qué naturalista publicó «El origen de las especies»?",ops:["Charles Darwin","Lamarck","Mendel","Linneo"],a:0,p:["Viajó en el barco Beagle.","Estudió los pinzones de Galápagos."],exp:"Charles Darwin publicó «El origen de las especies» en 1859, donde explicó la evolución por selección natural."},
{t:"evolucion",k:"mc",q:"Según Lamarck, los órganos que se usan mucho…",ops:["se desarrollan más","desaparecen","no cambian","se vuelven vestigiales"],a:0,p:["Es la ley del uso y desuso.","Pensaba en el cuello de la jirafa."],exp:"Lamarck proponía que el uso desarrolla los órganos y el desuso los atrofia, y que esos cambios se heredan (idea que hoy sabemos que es incorrecta)."},
{t:"evolucion",k:"vf",q:"Los fósiles más profundos suelen ser los más antiguos.",a:true,exp:"Verdadero. Las capas de roca se depositan una sobre otra, así que las de abajo suelen ser más antiguas."},
{t:"evolucion",k:"mc",q:"La fuente original de la variación genética es:",ops:["La mutación","El ejercicio","La alimentación","El clima"],a:0,p:["Es un cambio en el ADN.","Ocurre al azar."],exp:"Las mutaciones crean alelos nuevos: son la fuente original de la variación sobre la que actúa la selección natural."},
{t:"evolucion",k:"mc",q:"¿Qué evidencia de la evolución estudia los restos de seres del pasado?",ops:["Paleontología","Embriología","Genética","Ecología"],a:0,p:["Trabaja con fósiles.","«Paleo» significa antiguo."],exp:"La paleontología estudia los fósiles, que muestran cómo eran los seres vivos del pasado y cómo cambiaron."},
{t:"evolucion",k:"vf",q:"La selección natural actúa sobre los individuos, pero los que evolucionan son las poblaciones.",a:true,exp:"Verdadero. El ambiente favorece a unos individuos, pero el cambio de frecuencias de alelos se ve en la población a lo largo de generaciones."},
{t:"evolucion",k:"mc",q:"¿En qué era geológica vivieron los dinosaurios?",ops:["Mesozoico","Cenozoico","Paleozoico","Precámbrico"],a:0,p:["Es la «era media».","Terminó hace 66 millones de años."],exp:"Los dinosaurios vivieron en el Mesozoico, que terminó hace unos 66 millones de años con el impacto de un asteroide."},
{t:"evolucion",k:"mc",q:"Las razas de perros se obtuvieron por:",ops:["Selección artificial","Selección natural","Deriva genética","Mutaciones dirigidas"],a:0,p:["El ser humano escogió los rasgos.","Es lo mismo que pasó con el maíz."],exp:"Las razas de perros se formaron por selección artificial: las personas escogieron durante generaciones los animales con los rasgos deseados."},
{t:"evolucion",k:"mc",q:"Una especie que solo vive en un lugar del mundo es:",ops:["Endémica","Invasora","Extinta","Migratoria"],a:0,p:["Es lo contrario de cosmopolita.","La rana dorada del Chocó es un ejemplo."],exp:"Una especie endémica solo vive en una región; Colombia tiene muchas, como la rana dorada del Chocó."},
{t:"evolucion",k:"vf",q:"El ser humano evolucionó del chimpancé actual.",a:false,exp:"Falso. Humanos y chimpancés comparten un antepasado común que vivió hace unos 6 a 7 millones de años; ninguno viene del otro."},
{t:"evolucion",k:"mc",q:"¿Qué homínido es el más antiguo de estos?",ops:["Australopithecus","Homo erectus","Homo sapiens","Neandertal"],a:0,p:["Vivió hace más de 3 millones de años.","El fósil «Lucy» pertenece a este grupo."],exp:"Australopithecus vivió hace unos 4 a 2 millones de años; después aparecieron Homo erectus, los neandertales y Homo sapiens."},
{t:"evolucion",k:"mc",q:"¿Qué órganos tienen la misma función pero distinto origen?",ops:["Análogos","Homólogos","Vestigiales","Embrionarios"],a:0,p:["Como el ala de un insecto y la de un ave.","No vienen de un antepasado común."],exp:"Los órganos análogos cumplen la misma función con estructura y origen distintos, como las alas de insectos y aves."},
{t:"evolucion",k:"vf",q:"Los organismos cambian porque desean adaptarse al ambiente.",a:false,exp:"Falso. La variación aparece al azar; el ambiente selecciona a los mejor adaptados. Nadie cambia porque lo desee."},
{t:"evolucion",k:"mc",q:"¿Qué causa que una especie se divida en dos?",ops:["Un aislamiento prolongado","Un año de sequía","El ejercicio","La alimentación"],a:0,p:["Una barrera separa a la población.","Por ejemplo, una cordillera o un río."],exp:"Cuando una población queda aislada durante mucho tiempo, cada grupo cambia por su lado hasta formar especies distintas (especiación)."},
{t:"evolucion",k:"mc",q:"¿Cuántos años aproximadamente tiene la Tierra?",ops:["4600 millones","6000","1 millón","100 millones"],a:0,p:["Es muchísimo más que la historia humana.","Se calcula con la radiactividad de las rocas y los meteoritos."],exp:"La Tierra tiene unos 4600 millones de años, según la datación de rocas y meteoritos."}
]);
BIO_NUEVAS([
{t:"ecosistemas",k:"mc",q:"¿Qué es un factor biótico?",ops:["Un ser vivo del ecosistema","La temperatura","La luz","El suelo"],a:0,p:["«Bio» significa vida.","Es lo contrario de abiótico."],exp:"Los factores bióticos son los seres vivos (plantas, animales, hongos, bacterias) y sus relaciones."},
{t:"ecosistemas",k:"mc",q:"¿Qué organismo es un consumidor secundario?",ops:["Un sapo que come insectos","Un pasto","Una vaca","Un hongo"],a:0,p:["Come a un herbívoro.","Está en el tercer eslabón de la cadena."],exp:"El consumidor secundario se come a un consumidor primario (herbívoro), como el sapo que come insectos."},
{t:"ecosistemas",k:"mc",q:"¿Qué gas toman las plantas del aire para la fotosíntesis?",ops:["CO₂","Oxígeno","Nitrógeno","Metano"],a:0,p:["Es el gas que exhalamos.","Es parte del ciclo del carbono."],exp:"Las plantas toman dióxido de carbono (CO₂) del aire y lo convierten en glucosa con la energía de la luz."},
{t:"ecosistemas",k:"vf",q:"Un herbívoro es un consumidor primario.",a:true,exp:"Verdadero. Los herbívoros se alimentan directamente de productores, por eso son consumidores primarios."},
{t:"ecosistemas",k:"mc",q:"¿Qué relación tienen dos especies que se benefician mutuamente?",ops:["Mutualismo","Parasitismo","Competencia","Depredación"],a:0,p:["Las dos ganan.","Como el colibrí y la flor."],exp:"En el mutualismo (+ +) ambas especies se benefician, como el colibrí y la flor que poliniza."},
{t:"ecosistemas",k:"mc",q:"¿Qué se forma cuando el vapor de agua se enfría?",ops:["Nubes","Ríos","Hielo polar","Suelo"],a:0,p:["Es la condensación.","Están en el cielo."],exp:"Al enfriarse, el vapor se condensa en gotitas que forman las nubes; luego cae como precipitación."},
{t:"ecosistemas",k:"vf",q:"En una pirámide de energía, el nivel de arriba tiene más energía que el de abajo.",a:false,exp:"Falso. Cada nivel tiene cerca del 10 % de la energía del anterior; arriba hay muy poca energía."},
{t:"ecosistemas",k:"mc",q:"¿Cómo se llama el aumento de algas por exceso de nutrientes en el agua?",ops:["Eutrofización","Sucesión","Transpiración","Fotosíntesis"],a:0,p:["Lo causan los fertilizantes.","El agua se queda sin oxígeno."],exp:"La eutrofización es el crecimiento excesivo de algas por exceso de nitrógeno y fósforo; al descomponerse, el agua pierde oxígeno."},
{t:"ecosistemas",k:"mc",q:"El lugar donde vive una especie es su:",ops:["Hábitat","Nicho","Comunidad","Población"],a:0,p:["Es su «dirección».","El nicho sería su «oficio»."],exp:"El hábitat es el lugar donde vive una especie; el nicho es el papel que cumple allí."},
{t:"ecosistemas",k:"mc",q:"¿Qué organismo descompone la materia muerta?",ops:["Un hongo","Un jaguar","Un pasto","Un colibrí"],a:0,p:["Se alimenta por absorción.","Devuelve minerales al suelo."],exp:"Los hongos y las bacterias descomponen la materia muerta y devuelven los minerales al suelo."},
{t:"ecosistemas",k:"vf",q:"La competencia ocurre cuando dos especies usan el mismo recurso limitado.",a:true,exp:"Verdadero. En la competencia (− −) ambas especies pierden porque deben compartir alimento, espacio o agua."},
{t:"ecosistemas",k:"mc",q:"¿Qué proceso del ciclo del agua lleva el agua de la tierra al mar?",ops:["Escorrentía","Evaporación","Condensación","Transpiración"],a:0,p:["El agua corre por la superficie.","Pasa por ríos y quebradas."],exp:"La escorrentía es el agua que corre por la superficie y los ríos hasta llegar al mar."},
{t:"ecosistemas",k:"mc",q:"Una población que crece sin límites tiene una curva en forma de:",ops:["J","S","O","Línea recta horizontal"],a:0,p:["Sube cada vez más rápido.","Cuando hay límites, la curva es en S."],exp:"Sin límites la población crece de forma exponencial (curva en J); con recursos limitados se estabiliza (curva en S)."}
]);
BIO_NUEVAS([
{t:"colombia",k:"mc",q:"¿Qué región tiene el desierto de La Guajira?",ops:["Caribe","Pacífica","Andina","Amazonía"],a:0,p:["Está al norte del país.","Sus costas dan al mar de las Antillas."],exp:"El desierto de La Guajira está en la región Caribe, en el extremo norte de Colombia."},
{t:"colombia",k:"mc",q:"¿Qué piso térmico está por encima de los 4700 m?",ops:["Nival","Páramo","Frío","Templado"],a:0,p:["Allí hay nieve.","Es el más alto de todos."],exp:"Por encima de unos 4700 m está el piso nival, con nieve y glaciares, como en el Nevado del Ruiz."},
{t:"colombia",k:"mc",q:"¿Qué árbol es típico de la costa y vive con raíces en zancos en agua salobre?",ops:["El mangle","El frailejón","La palma de cera","El pino"],a:0,p:["Forma bosques en las desembocaduras.","Sus raíces son guardería de peces."],exp:"El mangle forma los manglares: vive en agua salobre con raíces en zancos y protege la costa."},
{t:"colombia",k:"vf",q:"La región Pacífica es una de las más secas de Colombia.",a:false,exp:"Falso. Es una de las regiones más lluviosas del mundo; en Lloró (Chocó) caen más de 10 000 mm al año."},
{t:"colombia",k:"mc",q:"¿Qué ave es símbolo nacional y está en el escudo?",ops:["El cóndor","El colibrí","La guacamaya","El tucán"],a:0,p:["Es una de las aves voladoras más grandes.","Vive en la alta montaña."],exp:"El cóndor de los Andes es el ave nacional; es un carroñero de alta montaña y está en peligro."},
{t:"colombia",k:"mc",q:"¿En qué región viven el chigüiro y el caimán del Orinoco?",ops:["Orinoquía","Caribe","Insular","Pacífica"],a:0,p:["Es la región de los Llanos.","Sus ríos van al río Orinoco."],exp:"El chigüiro y el caimán del Orinoco viven en la Orinoquía (Llanos Orientales)."},
{t:"colombia",k:"mc",q:"¿Qué región ocupa la menor parte del territorio colombiano?",ops:["Insular","Amazonía","Orinoquía","Andina"],a:0,p:["Está formada por islas.","Incluye San Andrés."],exp:"La región Insular (San Andrés, Providencia, Malpelo y Gorgona) es la más pequeña."},
{t:"colombia",k:"vf",q:"El Parque Nacional Chiribiquete es Patrimonio de la Humanidad.",a:true,exp:"Verdadero. Chiribiquete es Patrimonio Mixto (natural y cultural) desde 2018 por sus tepuyes y pinturas rupestres."},
{t:"colombia",k:"mc",q:"¿Cuánto baja la temperatura por cada 1000 m que se sube?",ops:["Unos 6 °C","Unos 20 °C","Unos 1 °C","No baja"],a:0,p:["Es un número de una cifra.","Por eso Bogotá es más fría que Girardot."],exp:"La temperatura baja unos 6 °C por cada 1000 m de altura; por eso existen los pisos térmicos."},
{t:"colombia",k:"mc",q:"¿Qué especie migra al Pacífico colombiano para tener a sus crías?",ops:["Ballena jorobada","Delfín rosado","Manatí","Tortuga carey"],a:0,p:["Viene desde la Antártida.","Llega entre julio y octubre."],exp:"La ballena jorobada migra desde la Antártida hasta el Pacífico colombiano para aparearse y tener sus crías."},
{t:"colombia",k:"mc",q:"¿Qué palma es el árbol nacional de Colombia?",ops:["Palma de cera","Palma de coco","Palma de aceite","Palma de iraca"],a:0,p:["Es la palma más alta del mundo.","Crece en el Valle de Cocora."],exp:"La palma de cera del Quindío es el árbol nacional; puede medir más de 60 metros y está amenazada."},
{t:"colombia",k:"vf",q:"Comprar animales silvestres como mascota ayuda a protegerlos.",a:false,exp:"Falso. Alimenta el tráfico de fauna, que causa la muerte de muchos animales y es un delito."},
{t:"colombia",k:"mc",q:"¿Cuál es la planta típica del páramo?",ops:["El frailejón","El mangle","El cactus","El pino"],a:0,p:["Tiene hojas peludas.","Crece muy despacio."],exp:"El frailejón es la planta típica del páramo; sus hojas peludas lo protegen del frío y captan agua de la niebla."}
]);
BIO_NUEVAS([
{t:"ambiente",k:"mc",q:"¿Qué gas emiten los carros al quemar gasolina?",ops:["Dióxido de carbono","Oxígeno","Helio","Ozono"],a:0,p:["Es un gas de efecto invernadero.","También lo exhalamos."],exp:"Al quemar gasolina se libera CO₂, el principal gas de efecto invernadero emitido por los humanos."},
{t:"ambiente",k:"vf",q:"El metano calienta más que el CO₂ en sus primeros años en la atmósfera.",a:true,exp:"Verdadero. El metano retiene mucho más calor que el CO₂, aunque dura menos tiempo en la atmósfera."},
{t:"ambiente",k:"mc",q:"¿Qué energía usa la fuerza del viento?",ops:["Eólica","Solar","Hidráulica","Geotérmica"],a:0,p:["Usa grandes molinos.","La Guajira tiene mucha."],exp:"La energía eólica usa aerogeneradores movidos por el viento; La Guajira tiene excelentes vientos."},
{t:"ambiente",k:"mc",q:"¿Qué energía usa el calor del interior de la Tierra?",ops:["Geotérmica","Eólica","Solar","Nuclear"],a:0,p:["Viene de abajo del suelo.","Se aprovecha cerca de volcanes."],exp:"La energía geotérmica aprovecha el calor del interior de la Tierra, por ejemplo cerca de volcanes."},
{t:"ambiente",k:"vf",q:"El carbón y el petróleo son energías renovables.",a:false,exp:"Falso. Son combustibles fósiles: se formaron en millones de años, se agotan y emiten CO₂ al quemarse."},
{t:"ambiente",k:"mc",q:"Acciones que reducen las emisiones son de:",ops:["Mitigación","Adaptación","Contaminación","Deforestación"],a:0,p:["Atacan la causa del problema.","Usar bicicleta es un ejemplo."],exp:"La mitigación reduce las emisiones de gases de efecto invernadero o aumenta su captura."},
{t:"ambiente",k:"mc",q:"Recoger agua lluvia para la sequía es:",ops:["Adaptación","Mitigación","Deforestación","Contaminación"],a:0,p:["Prepara para el clima que viene.","No reduce las emisiones."],exp:"Es adaptación: ajustarse a los efectos del cambio climático, como las sequías."},
{t:"ambiente",k:"vf",q:"Los océanos absorben parte del CO₂ que emitimos.",a:true,exp:"Verdadero. El océano absorbe cerca de un cuarto del CO₂ emitido, pero por eso se acidifica."},
{t:"ambiente",k:"mc",q:"¿Qué fenómeno trae sequías a Colombia?",ops:["El Niño","La Niña","El monzón","Un huracán"],a:0,p:["El Pacífico se calienta.","Bajan los embalses."],exp:"Con El Niño llueve menos en gran parte de Colombia: hay sequías e incendios."},
{t:"ambiente",k:"mc",q:"¿Qué fenómeno trae inundaciones a Colombia?",ops:["La Niña","El Niño","Una sequía","Un eclipse"],a:0,p:["Es lo contrario de El Niño.","Llueve más de lo normal."],exp:"Con La Niña llueve más de lo normal y hay inundaciones y deslizamientos."},
{t:"ambiente",k:"vf",q:"Separar los residuos orgánicos reduce el metano de los rellenos.",a:true,exp:"Verdadero. Si los residuos orgánicos se compostan con aire, no se pudren sin oxígeno en el relleno y no producen metano."},
{t:"ambiente",k:"mc",q:"¿Qué parte de la atmósfera nos protege de la radiación ultravioleta?",ops:["La capa de ozono","Las nubes de lluvia","El CO₂","El nitrógeno"],a:0,p:["Está en la estratosfera.","La dañaron los CFC de los aerosoles."],exp:"La capa de ozono filtra la radiación ultravioleta; se está recuperando gracias al Protocolo de Montreal."},
{t:"ambiente",k:"mc",q:"¿Cuál es la principal causa de emisiones en Colombia?",ops:["La deforestación","Los carros eléctricos","La energía solar","El reciclaje"],a:0,p:["Ocurre sobre todo en la Amazonía.","Tiene que ver con talar bosques."],exp:"En Colombia la mayor fuente de emisiones es la deforestación y el cambio de uso del suelo."},
{t:"ambiente",k:"vf",q:"Un día frío demuestra que no existe el calentamiento global.",a:false,exp:"Falso. El tiempo de un día no es el clima; el clima es el promedio de muchos años, y la tendencia es al calentamiento."},
{t:"ambiente",k:"mc",q:"¿Qué pasa con el nivel del mar por el calentamiento?",ops:["Sube","Baja","No cambia","Se congela"],a:0,p:["El hielo de los polos se derrite.","El agua caliente ocupa más espacio."],exp:"El nivel del mar sube porque se derrite el hielo y el agua se expande al calentarse."},
{t:"ambiente",k:"mc",q:"¿Qué gas producen los arrozales y las vacas?",ops:["Metano","Ozono","Oxígeno","Helio"],a:0,p:["Lo producen bacterias sin oxígeno.","También sale de los rellenos."],exp:"Arrozales inundados, vacas y rellenos sanitarios producen metano por la acción de bacterias sin oxígeno."},
{t:"ambiente",k:"vf",q:"Comer menos carne de res puede reducir la huella de carbono.",a:true,exp:"Verdadero. La ganadería emite metano y está ligada a la deforestación; comer menos carne de res reduce emisiones."},
{t:"ambiente",k:"mc",q:"¿Qué acuerdo de 2015 busca limitar el calentamiento?",ops:["Acuerdo de París","Protocolo de Montreal","Tratado de Versalles","Carta de Jamaica"],a:0,p:["Se firmó en una capital europea.","Busca no pasar de 1,5 a 2 °C."],exp:"El Acuerdo de París (2015) compromete a los países a reducir emisiones para limitar el calentamiento a 1,5 o 2 °C."},
{t:"ambiente",k:"mc",q:"¿Qué color toman los corales cuando pierden sus algas?",ops:["Blanco","Rojo","Negro","Verde"],a:0,p:["Por eso el fenómeno tiene ese nombre.","Es como si se «decoloraran»."],exp:"Los corales que pierden sus algas por el calor se ponen blancos: es el blanqueamiento."},
{t:"ambiente",k:"mc",q:"¿Qué ciudad colombiana está muy expuesta a la subida del mar?",ops:["Cartagena","Bogotá","Tunja","Manizales"],a:0,p:["Está en la costa.","Está casi al nivel del mar."],exp:"Cartagena, en la costa Caribe y casi al nivel del mar, está expuesta a inundaciones por la subida del mar."},
{t:"ambiente",k:"vf",q:"Los páramos guardan carbono en su suelo.",a:true,exp:"Verdadero. Los suelos de páramo guardan mucho carbono; conservarlos evita que salga como CO₂."},
{t:"ambiente",k:"mc",q:"¿Qué hace un panel solar?",ops:["Convierte luz en electricidad","Produce viento","Guarda agua","Quema carbón"],a:0,p:["Usa la luz del Sol.","Es energía fotovoltaica."],exp:"Un panel solar convierte la luz del Sol en electricidad sin emitir CO₂ al funcionar."},
{t:"ambiente",k:"mc",q:"¿Cuál de estos residuos se puede compostar?",ops:["Cáscaras de fruta","Pilas","Botellas de vidrio","Bolsas plásticas"],a:0,p:["Es un residuo orgánico.","Se descompone fácilmente."],exp:"Las cáscaras de fruta son residuos orgánicos que se convierten en abono al compostarlas."},
{t:"ambiente",k:"vf",q:"Las comunidades pobres y rurales son las más vulnerables al cambio climático.",a:true,exp:"Verdadero. Dependen de la lluvia y la naturaleza y tienen menos recursos para recuperarse de sequías o inundaciones."},
{t:"ambiente",k:"mc",q:"¿Qué enfermedad sube a zonas más altas con el calor?",ops:["El dengue","La gripa","La varicela","El sarampión"],a:0,p:["La transmite un mosquito.","El mosquito necesita calor."],exp:"El mosquito Aedes aegypti transmite el dengue; con el calentamiento puede vivir en zonas más altas."}
]);
delete window.BIO_AJ;delete window.BIO_NUEVAS;
